    'nationality' => 'Nigerian', 'parent1Rel' => 'Mother', 'parent1Name' => 'adunni adebayo', 'parent1Phone' => '8031234567',
    'parent2None' => true, 'hobbies' => ['Reading'], 'influenceAreas' => ['Education'], 'heardFrom' => 'WhatsApp', 'promoCode' => ''];
