chk('broadcast reaches member feed', $seen);
// Audience targeting: a centre-scoped broadcast reaches matching members only.
$feedHas = function ($mid, $title) { foreach (backend_dispatch('member.notifications', ['memberId' => $mid])['notifications'] as $n) if ($n['title'] === $title) return true; return false; };
backend_dispatch('admin.broadcast', ['requesterId' => 'NGG-2025-0099', 'title' => 'Egbeda only', 'body' => 'x', 'audience' => 'Egbeda']);
backend_dispatch('admin.broadcast', ['requesterId' => 'NGG-2025-0099', 'title' => 'Ayobo only', 'body' => 'x', 'audience' => 'Ayobo']);
chk('centre-scoped broadcast reaches matching member', $feedHas('NGG-2025-0001', 'Egbeda only')); // NGG-2025-0001 is Egbeda
chk('centre-scoped broadcast hidden from non-matching member', !$feedHas('NGG-2025-0001', 'Ayobo only'));
// Email path is actually invoked when email=true (route used to drop it).
$GLOBALS['__mail_sink'] = [];
$br = backend_dispatch('admin.broadcast', ['requesterId' => 'NGG-2025-0099', 'title' => 'With email', 'body' => 'hi', 'audience' => 'all', 'email' => true]);
unset($GLOBALS['__mail_sink']);
chk('broadcast email fan-out runs when email=true', ($br['emailed'] ?? 0) >= 1);
chk('broadcast history lists past announcements', (function () {
    $h = backend_dispatch('admin.broadcast.history', ['requesterId' => 'NGG-2025-0099']);
    return !empty($h['ok']) && (bool)array_filter($h['announcements'], fn($a) => $a['title'] === 'Egbeda only' && $a['audience'] === 'Egbeda');
})());
// An audience nobody can name is refused — it used to be stamped '' (everyone) and emailed to every active member.
chk('broadcast refuses an unknown audience instead of sending it to everyone', (function () {
    $before = (int)db_row("SELECT COUNT(*) AS n FROM notifications WHERE kind = 'announcement'")['n'];
    $r = backend_dispatch('admin.broadcast', ['requesterId' => 'NGG-2025-0099', 'title' => 'Typo', 'body' => 'x', 'audience' => 'Egbedaa', 'email' => true]);
    return ($r['error'] ?? '') === 'bad_audience' && (int)db_row("SELECT COUNT(*) AS n FROM notifications WHERE kind = 'announcement'")['n'] === $before;
})());
// A centre other than the two that used to be typed into the code can be addressed, and only its members see it.
chk('broadcast reaches a centre beyond the two that used to be hard-coded, and nobody else', (function () use ($feedHas) {
    db_insert('centres', ['centreId' => 'CEN-BC-NEW', 'name' => 'Ikorodu', 'code' => 'IKD', 'color' => '#336699', 'status' => 'active', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    db_insert('members', ['memberId' => 'NGG-BC-IKD', 'fullName' => 'Ike Odu', 'email' => 'ike@bc.example', 'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => 'Ikorodu', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    $r = backend_dispatch('admin.broadcast', ['requesterId' => 'NGG-2025-0099', 'title' => 'Ikorodu only', 'body' => 'x', 'audience' => 'Ikorodu']);
    $ok = !empty($r['ok']) && $feedHas('NGG-BC-IKD', 'Ikorodu only') && !$feedHas('NGG-2025-0001', 'Ikorodu only');
    $h = backend_dispatch('admin.broadcast.history', ['requesterId' => 'NGG-2025-0099']);
    $ik = array_values(array_filter($h['audiences'] ?? [], fn($a) => $a['id'] === 'Ikorodu'));
    $ok = $ok && $ik && $ik[0]['n'] === 1 && ($h['audiences'][0]['id'] ?? '') === 'all';
    db_exec("DELETE FROM members WHERE memberId = 'NGG-BC-IKD'"); db_exec("DELETE FROM centres WHERE centreId = 'CEN-BC-NEW'");
    return $ok;
})());

/* ── Brute-force floors ───────────────────────────────────────────────────
 *
 * rate_limit_default() exists so a config.php that predates a bucket cannot
 * silently fall through to the loose 60/minute default. It covered the
 * second-tier buckets and skipped the credential ones — the deployment that
 * most needs a floor being precisely the one running an old config. Every
 * bucket named here must have a floor, and none of them may be looser than
 * the 60/min default it is meant to replace. */
chk('every bucket that only lived in config.example now has a floor', (function () {
    foreach (['auth.gateway', 'auth.request', 'auth.verify', 'gate.unlock',
              'circle.lookup', 'circle.connect', 'upload.sign', 'hook'] as $op) {
        $f = rate_limit_default($op);
        if (!$f || !isset($f['max'], $f['window'])) return false;
    }
    return true;
})());
/* Having a floor is not enough — a floor looser than the default it replaces
   would be decorative. Checked as a RATE, so 6-per-300s reads as tighter than
   60-per-60s rather than merely smaller. `hook` is deliberately not in this
   list: it carries HMAC-signed webhook bursts, not a guessable secret, and is
   meant to be looser than the default. */
chk('…and every guessable-secret bucket is tighter than the loose default', (function () {
    foreach (['auth.gateway', 'auth.request', 'auth.verify', 'gate.unlock',
              'circle.lookup', 'circle.connect', 'upload.sign'] as $op) {
        $f = rate_limit_default($op);
        if (($f['max'] / $f['window']) > (60 / 60)) return false;
    }
    return true;
})());
chk('…and the guessable-secret buckets are tighter than the mail ones',
    rate_limit_default('circle.lookup')['max'] / rate_limit_default('circle.lookup')['window']
    < rate_limit_default('apply')['max'] / rate_limit_default('apply')['window']);
chk('an unknown bucket still has no floor, so it falls to the configured default',
    rate_limit_default('something.invented') === null);

/* ── Trusted proxies ──────────────────────────────────────────────────────
 *
 * client_ip() reads request state so it is exercised over HTTP elsewhere; the
 * CIDR arithmetic it rests on is pure, and it decides whether a forwarded
 * header is believed. Getting it wrong in the permissive direction restores
 * the original hole — every rate limit in the product opted out of by a header
 * — and in the strict direction lumps every visitor behind a CDN into one
 * bucket. Both are worth a test. */
chk('an address inside a /20 is inside it', ip_in_cidr('173.245.55.9', '173.245.48.0/20'));
chk('…and one just outside it is not', ip_in_cidr('173.245.64.1', '173.245.48.0/20') === false);
chk('a /32 matches exactly one address',
    ip_in_cidr('10.0.0.7', '10.0.0.7/32') && !ip_in_cidr('10.0.0.8', '10.0.0.7/32'));
chk('a bare address behaves as a /32',
    ip_in_cidr('127.0.0.1', '127.0.0.1') && !ip_in_cidr('127.0.0.2', '127.0.0.1'));
chk('a /0 is not accidentally everybody — it is asked for explicitly',
    ip_in_cidr('8.8.8.8', '0.0.0.0/0'));
chk('IPv6 ranges work', ip_in_cidr('2400:cb00::1', '2400:cb00::/32')
    && !ip_in_cidr('2401:cb00::1', '2400:cb00::/32'));
chk('v4 and v6 never match each other',
    !ip_in_cidr('2400:cb00::1', '173.245.48.0/20') && !ip_in_cidr('173.245.55.9', '2400:cb00::/32'));
chk('rubbish never matches', !ip_in_cidr('not-an-ip', '10.0.0.0/8')
    && !ip_in_cidr('10.0.0.1', 'not-a-cidr') && !ip_in_cidr('10.0.0.1', '')
    && !ip_in_cidr('10.0.0.1', '10.0.0.0/99'));
/* The default — no trusted_proxies configured — must trust NOBODY, because
   that is what makes a forwarded header worthless to an attacker. */
chk('with no trusted proxies configured, no proxy is trusted',
    ip_is_trusted_proxy('173.245.55.9', []) === false);
chk('a listed proxy is trusted and an unlisted one is not',
    ip_is_trusted_proxy('173.245.55.9', ['173.245.48.0/20']) === true
    && ip_is_trusted_proxy('9.9.9.9', ['173.245.48.0/20']) === false);

// ── TOTP ──
$setup = backend_dispatch('auth.totpSetup', ['memberId' => 'NGG-2025-0099']);
$secret = $setup['secret'];
chk('totp accepts current code', backend_dispatch('auth.totpVerify', ['memberId' => 'NGG-2025-0099', 'code' => totp_code($secret, intdiv(time(), 30))])['ok'] === true);
chk('totp rejects bad code', backend_dispatch('auth.totpVerify', ['memberId' => 'NGG-2025-0099', 'code' => '000000'])['ok'] === false);
// Backup codes: setup mints 8; each works once at the gate, then is consumed.
chk('totp setup mints 8 backup codes', is_array($setup['backupCodes']) && count($setup['backupCodes']) === 8);
$bc = $setup['backupCodes'][0];
chk('a backup code satisfies the 2FA gate', backend_dispatch('auth.totpVerify', ['memberId' => 'NGG-2025-0099', 'code' => $bc])['backupUsed'] === true);
chk('a backup code cannot be reused', empty(backend_dispatch('auth.totpVerify', ['memberId' => 'NGG-2025-0099', 'code' => $bc])['ok']));
// Lock is a server act: the cleared device session is revoked, so the cookie
// that carried 2FA clearance cannot be replayed after "Lock Control Room".
db_insert('device_sessions', ['sid' => 'lock-test-sid', 'memberId' => 'NGG-2025-0099', 'ip' => '', 'userAgent' => '', 'uaHash' => 'x', 'createdAt' => now_iso(), 'lastSeenAt' => now_iso()]);
chk('lock: auth.lock is mapped and revokes the cleared session', (backend_dispatch('auth.lock', ['memberId' => 'NGG-2025-0099', 'sid' => 'lock-test-sid'])['ok'] ?? false) === true
    && (string)db_row("SELECT revokedAt FROM device_sessions WHERE sid = 'lock-test-sid'")['revokedAt'] !== '');
chk('lock: it is audited', (bool)db_row("SELECT id FROM audit_log WHERE event = 'admin.lock' LIMIT 1"));

/* Re-enrolment is refused once a secret exists — the 2FA bypass.
 *
 * auth/admin-totp-setup.php runs on a session that has NOT passed 2FA (it must:
 * a first-time enroller has no code to give). So while this op would overwrite
 * an existing secret, a stolen password alone was enough to re-issue the second
 * factor and then satisfy the gate with it. The check is that the STORED secret
 * is untouched, not merely that the call returned an error — a refusal that
 * still wrote would be the same breach with a worse error message. */
chk('totp re-enrolment is refused once enrolled', (function () {
    $before = (string)(db_row("SELECT totpSecret FROM members WHERE memberId='NGG-2025-0099'")['totpSecret'] ?? '');
    $re = backend_dispatch('auth.totpSetup', ['memberId' => 'NGG-2025-0099']);
    $after = (string)(db_row("SELECT totpSecret FROM members WHERE memberId='NGG-2025-0099'")['totpSecret'] ?? '');
    return $before !== '' && ($re['error'] ?? '') === 'already_enrolled' && $after === $before;
})());
chk('…and the refusal hands back no secret to enrol with',
    !isset(backend_dispatch('auth.totpSetup', ['memberId' => 'NGG-2025-0099'])['secret']));
chk('…so the authenticator that was already working still works',
    backend_dispatch('auth.totpVerify', ['memberId' => 'NGG-2025-0099',
        'code' => totp_code($secret, intdiv(time(), 30))])['ok'] === true);
chk('…and the refusal is recorded for the person whose factor was targeted',
    (string)(db_row("SELECT subject FROM audit_log WHERE event='admin.totp.setup_refused' ORDER BY id DESC LIMIT 1")['subject'] ?? '') === 'NGG-2025-0099');

/* Guessing the second factor is bounded, and bounded against the ADMIN.
 * Six digits with a ±1 window is a small space; the endpoint's IP bucket was
 * the only ceiling on it, and an IP is a header claim until a trusted proxy
 * vouches for it. */
chk('eight wrong codes lock the admin\'s second factor', (function () {
    attempt_reset('totp', 'NGG-2025-0099');
    for ($i = 0; $i < 8; $i++) backend_dispatch('auth.totpVerify', ['memberId' => 'NGG-2025-0099', 'code' => '000000']);
    return backend_dispatch('auth.totpVerify', ['memberId' => 'NGG-2025-0099', 'code' => '000000'])['error'] === 'too_many_attempts';
})());
chk('…and the CORRECT code is refused while the lock holds', (function () use ($secret) {
    return backend_dispatch('auth.totpVerify', ['memberId' => 'NGG-2025-0099',
        'code' => totp_code($secret, intdiv(time(), 30))])['error'] === 'too_many_attempts';
})());
chk('…and a correct code works again once it lifts', (function () use ($secret) {
    attempt_reset('totp', 'NGG-2025-0099');   // stands in for the clock
    return backend_dispatch('auth.totpVerify', ['memberId' => 'NGG-2025-0099',
        'code' => totp_code($secret, intdiv(time(), 30))])['ok'] === true;
})());

// Super-admin recovery: reset a member's 2FA + password; non-super is refused.
chk('super-admin can reset a member 2FA', !empty(backend_dispatch('admin.members.reset2fa', ['requesterId' => 'NGG-2025-0099', 'memberId' => 'NGG-2025-0099'])['ok']) && (string)(db_row("SELECT totpSecret FROM members WHERE memberId='NGG-2025-0099'")['totpSecret'] ?? '') === '');
chk('non-super cannot reset 2FA', backend_dispatch('admin.members.reset2fa', ['requesterId' => 'NGG-2025-0001', 'memberId' => 'NGG-2025-0099'])['error'] === 'forbidden');
chk('super-admin can reset a member password', !empty(backend_dispatch('admin.members.resetPassword', ['requesterId' => 'NGG-2025-0099', 'memberId' => 'NGG-2025-0001'])['ok']));

// ── Device sessions (Me → Security): list, per-device revoke, sign-out-everywhere ──
db_insert('device_sessions', ['sid' => 'SID-CUR', 'memberId' => 'NGG-2025-0001', 'ip' => '1.1.1.1', 'userAgent' => 'iPhone Safari', 'uaHash' => 'h1', 'createdAt' => now_iso(), 'lastSeenAt' => now_iso(), 'revokedAt' => '']);
db_insert('device_sessions', ['sid' => 'SID-OTH', 'memberId' => 'NGG-2025-0001', 'ip' => '2.2.2.2', 'userAgent' => 'Windows Chrome', 'uaHash' => 'h2', 'createdAt' => now_iso(), 'lastSeenAt' => now_iso(), 'revokedAt' => '']);
chk('security lists active devices, flags the current one', (function () {
    $r = backend_dispatch('member.security', ['requesterId' => 'NGG-2025-0001', 'sid' => 'SID-CUR']);
    $cur = array_filter($r['sessions'], fn($s) => $s['current']);
    return count($r['sessions']) === 2 && count($cur) === 1 && array_values($cur)[0]['sid'] === 'SID-CUR';
})());
chk('revoke one device removes it from the list', (function () {
    backend_dispatch('member.sessions.revoke', ['requesterId' => 'NGG-2025-0001', 'sid' => 'SID-CUR', 'targetSid' => 'SID-OTH']);
    return count(backend_dispatch('member.security', ['requesterId' => 'NGG-2025-0001', 'sid' => 'SID-CUR'])['sessions']) === 1;
})());
chk('sign-out-everywhere keeps only the current session', (function () {
    db_insert('device_sessions', ['sid' => 'SID-X', 'memberId' => 'NGG-2025-0001', 'ip' => '3.3.3.3', 'userAgent' => 'x', 'uaHash' => 'h3', 'createdAt' => now_iso(), 'lastSeenAt' => now_iso(), 'revokedAt' => '']);
    backend_dispatch('member.sessions.revoke', ['requesterId' => 'NGG-2025-0001', 'sid' => 'SID-CUR', 'others' => true]);
    $r = backend_dispatch('member.security', ['requesterId' => 'NGG-2025-0001', 'sid' => 'SID-CUR']);
    return count($r['sessions']) === 1 && $r['sessions'][0]['sid'] === 'SID-CUR';
})());
chk('logout revokes the current device session server-side', (function () {
    backend_dispatch('auth.logout', ['memberId' => 'NGG-2025-0001', 'sid' => 'SID-CUR']);
    return !empty(db_row("SELECT revokedAt FROM device_sessions WHERE sid='SID-CUR'")['revokedAt']);
})());

// ── Posts / newsletter / apply ──
// Headshots are required on intake by default; the bulk apply/gate tests below
// don't submit a photo, so relax the gate here and assert the requirement in a
// dedicated block further down.
setting_set('intake_photo_required', '0', 'test');
chk('post publishes with slug', !empty(backend_dispatch('admin.posts.upsert', ['requesterId' => 'NGG-2025-0099', 'data' => ['kind' => 'blog', 'title' => 'First Post', 'body' => 'Hi', 'status' => 'published']])['slug']));
chk('public reads published post', count(backend_dispatch('public.posts', ['kind' => 'blog'])['posts']) === 1);
chk('newsletter idempotent', backend_dispatch('public.newsletter', ['email' => 'sub@example.com'])['ok'] && backend_dispatch('public.newsletter', ['email' => 'sub@example.com'])['ok']);
chk('apply validates age', backend_dispatch('public.apply', ['kind' => 'teen', 'details' => CLUBTEST_DETAILS, 'consents' => CLUBTEST_CONSENTS, 'why' => CLUBTEST_WHY, 'sex' => 'Male', 'firstName' => 'Kid', 'lastName' => 'Test', 'email' => 'k@example.com', 'phone' => '08031234000', 'dob' => '1985-01-01'])['error'] === 'bad_age');
// Headshot required on intake (teen + volunteer) when the gate is on (default).
setting_set('intake_photo_required', '1', 'test');
chk('apply requires a headshot when the gate is on', backend_dispatch('public.apply', ['kind' => 'teen', 'details' => CLUBTEST_DETAILS, 'consents' => CLUBTEST_CONSENTS, 'why' => CLUBTEST_WHY, 'sex' => 'Male', 'firstName' => 'No', 'lastName' => 'Photo', 'email' => 'nophoto@example.com', 'phone' => '08031234111', 'dob' => '2012-01-01'])['error'] === 'photo_required');
chk('apply passes with a valid cloudinary headshot', !empty(backend_dispatch('public.apply', ['kind' => 'teen', 'program' => 'summer', 'sex' => 'Male', 'firstName' => 'With', 'lastName' => 'Photo', 'email' => 'withphoto@example.com', 'phone' => '08031234112', 'dob' => '2012-01-01', 'photoUrl' => 'https://res.cloudinary.com/demo/image/upload/v1/face.jpg'])['ok']));
setting_set('intake_photo_required', '0', 'test');
chk('apply skips the headshot gate when disabled', !empty(backend_dispatch('public.apply', ['kind' => 'teen', 'program' => 'summer', 'sex' => 'Male', 'firstName' => 'Gate', 'lastName' => 'Off', 'email' => 'gateoff@example.com', 'phone' => '08031234113', 'dob' => '2012-01-01'])['ok']));

// ── Volunteer registration (public taxonomy: admin | mentor | instructor) ──
$vctx = backend_dispatch('public.volunteer.context', []);
chk('volunteer context lists roles', $vctx['roles'] === ['admin', 'mentor', 'instructor']);
chk('volunteer context serves the course catalogue', in_array('Practical Coding', $vctx['courses'], true));
chk('volunteer context serves the faculty catalogue', is_array($vctx['faculties']) && count($vctx['faculties']) >= 1);
// An active centre must exist for volunteer intake (centre is now required).
db_insert('centres', ['centreId' => 'CEN-VOL', 'name' => 'Testville', 'code' => 'TVL', 'color' => '#4C6FFF', 'status' => 'active', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
$vFac = $vctx['faculties'][0];
chk('volunteer apply rejects unknown role', backend_dispatch('public.apply', ['kind' => 'volunteer', 'referees' => VOLTEST_REFS, 'declaration' => true, 'sex' => 'Male', 'role' => 'chef', 'firstName' => 'Vol', 'lastName' => 'One', 'email' => 'vol1@example.com', 'phone' => '08031110009', 'dob' => '1990-01-01'])['error'] === 'bad_role');
chk('volunteer apply rejects a missing centre', backend_dispatch('public.apply', ['kind' => 'volunteer', 'referees' => VOLTEST_REFS, 'declaration' => true, 'sex' => 'Male', 'role' => 'admin', 'firstName' => 'No', 'lastName' => 'Centre', 'email' => 'nocentre@example.com', 'phone' => '08031110077', 'dob' => '1990-01-01'])['error'] === 'centre_required');
chk('volunteer apply rejects an invalid centre', backend_dispatch('public.apply', ['kind' => 'volunteer', 'referees' => VOLTEST_REFS, 'declaration' => true, 'sex' => 'Male', 'role' => 'admin', 'firstName' => 'Bad', 'lastName' => 'Centre', 'email' => 'badcentre@example.com', 'phone' => '08031110078', 'dob' => '1990-01-01', 'centre' => 'Nowhere'])['error'] === 'invalid_centre');
chk('mentor without a faculty is rejected', backend_dispatch('public.apply', ['kind' => 'volunteer', 'referees' => VOLTEST_REFS, 'declaration' => true, 'sex' => 'Male', 'role' => 'mentor', 'firstName' => 'No', 'lastName' => 'Fac', 'email' => 'nofac@example.com', 'phone' => '08031110076', 'dob' => '1990-01-01', 'centre' => 'Testville'])['error'] === 'faculty_required');
chk('instructor without a faculty is rejected', backend_dispatch('public.apply', ['kind' => 'volunteer', 'referees' => VOLTEST_REFS, 'declaration' => true, 'sex' => 'Male', 'role' => 'instructor', 'firstName' => 'No', 'lastName' => 'Fac2', 'email' => 'nofac2@example.com', 'phone' => '08031110075', 'dob' => '1990-01-01', 'centre' => 'Testville', 'courses' => ['Practical Coding']])['error'] === 'faculty_required');
chk('instructor without a course is rejected', backend_dispatch('public.apply', ['kind' => 'volunteer', 'referees' => VOLTEST_REFS, 'declaration' => true, 'sex' => 'Male', 'role' => 'instructor', 'firstName' => 'Vol', 'lastName' => 'One', 'email' => 'vol1@example.com', 'phone' => '08031110001', 'dob' => '1990-01-01', 'centre' => 'Testville', 'faculty' => $vFac, 'courses' => ['Basket Weaving']])['error'] === 'course_required');
chk('volunteer admin role applies clean', backend_dispatch('public.apply', ['kind' => 'volunteer', 'referees' => VOLTEST_REFS, 'declaration' => true, 'sex' => 'Male', 'role' => 'admin', 'firstName' => 'Vol', 'lastName' => 'Admin', 'email' => 'vol-admin@example.com', 'phone' => '08031234567', 'dob' => '1990-01-01', 'centre' => 'Testville'])['ok'] === true);
chk('volunteer centre stored on application', db_row("SELECT centre FROM applications WHERE email = 'vol-admin@example.com'")['centre'] === 'Testville');
chk('volunteer phone stored normalized', db_row("SELECT phone FROM applications WHERE email = 'vol-admin@example.com'")['phone'] === '+2348031234567');
/* ── The headshot a browser can actually produce ──────────────────────────────
 *
 * This intake accepted ONE shape — an unsigned upload to res.cloudinary.com —
 * silently blanked everything else, and then refused the application for having
 * no photo. Cloudinary is opt-in (uploadOrInline carries the image inside the
 * submission when there is no cloud, and there is a whole local photo store for
 * exactly that), so on any deployment without it EVERY volunteer registration
 * failed: the form will not submit without a headshot, the applicant watched
 * theirs appear on screen, and the server said `photo_required`.
 */
(function () {
    db_exec("DELETE FROM centres WHERE centreId = 'CEN-PHOTO'");
    db_insert('centres', ['centreId' => 'CEN-PHOTO', 'name' => 'Photoville', 'code' => 'PHV', 'color' => '#123456',
        'status' => 'active', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    $keep = setting_raw('intake_photo_required');
    setting_set('intake_photo_required', '1', 'test');       // the production default
    // These applications are cleaned up below, and so are the bus rows they
    // queue — a later assertion counts volunteer.applied exactly.
    $obMax = (int)(db_row('SELECT MAX(id) m FROM outbox')['m'] ?? 0);
    // A real JPEG: photo_store_put re-decodes and checks the true image type.
    $jpg = base64_decode('/9j/4AAQSkZJRgABAQEAYABgAAD/2wBDAAgGBgcGBQgHBwcJCQgKDBQNCwsLDBkSEw8UHRofHh0aHBwcJC4nICIsIxwcKDcpLDAxNDQ0Hyc5PTgyPDs0NDP/wAALCAABAAEBAREA/8QAFAABAQAAAAAAAAAAAAAAAAAAAAf/xAAUEAEAAAAAAAAAAAAAAAAAAAAA/8QAFAEBAAAAAAAAAAAAAAAAAAAAAP/EABQRAQAAAAAAAAAAAAAAAAAAAAD/2gAMAwEAAhEDEQA/AKgA/9k=');
    $phSeq = 0;
    $apply = function ($email, $photo) use (&$phSeq) {
        $phSeq++;
        return backend_dispatch('public.apply', ['kind' => 'volunteer', 'referees' => VOLTEST_REFS, 'declaration' => true, 'sex' => 'Female',
            'role' => 'admin', 'firstName' => 'Photo', 'lastName' => 'Case', 'email' => $email,
            'phone' => '080522' . sprintf('%05d', 1000 + $phSeq), 'dob' => '1990-01-01',
            'centre' => 'Photoville', 'why' => 'I care.', 'photoUrl' => $photo]);
    };

    chk('a volunteer can register with the inline photo a no-cloud deployment produces', (function () use ($apply, $jpg) {
        $r = $apply('ph-inline@example.com', 'data:image/jpeg;base64,' . base64_encode($jpg));
        if (empty($r['ok'])) return false;
        // Stored as OUR served path — the bytes were parsed, not a URL trusted.
        $row = db_row("SELECT photoUrl FROM applications WHERE email = 'ph-inline@example.com'");
        return strpos((string)$row['photoUrl'], '/api/public/photo.php?') === 0;
    })());

    chk('…and with a photo already in the local store, or on the configured CDN', (function () use ($apply) {
        return !empty($apply('ph-local@example.com', '/api/public/photo.php?p=abc.jpg')['ok'])
            && !empty($apply('ph-cdn@example.com', 'https://res.cloudinary.com/demo/image/upload/v1/x.jpg')['ok']);
    })());

    chk('…while an arbitrary remote URL is still refused on an unauthenticated form', (function () use ($apply) {
        /* This is a public form. Storing an attacker-chosen URL on a volunteer
         * record, to be rendered later on the public directory, is not a photo
         * upload — which is why the fix is not simply "accept any https". */
        foreach (['https://evil.example/x.jpg', 'javascript:alert(1)', 'file:///etc/passwd', 'not-a-url'] as $bad) {
            if (($apply('ph-bad@example.com', $bad)['error'] ?? '') !== 'photo_required') return false;
        }
        return true;
    })());

    chk('…and a data URL in a format we will not serve is refused, script-bearing ones included', (function () use ($apply) {
        /* SVG is the one that matters: it is an image to a browser and a script
         * host to an attacker, and this record is rendered on a public page. */
        foreach (['data:image/svg+xml;base64,' . base64_encode('<svg xmlns="http://www.w3.org/2000/svg"/>'),
                  'data:text/html;base64,' . base64_encode('<script>1</script>'),
                  'data:image/gif;base64,' . base64_encode('GIF89a')] as $bad) {
            if (($apply('ph-junk@example.com', $bad)['error'] ?? '') !== 'photo_required') return false;
        }
        return true;
    })());

    db_exec("DELETE FROM applications WHERE email LIKE 'ph-%@example.com'");
    db_exec('DELETE FROM outbox WHERE id > ?', [$obMax]);
    db_exec("DELETE FROM centres WHERE centreId = 'CEN-PHOTO'");
    setting_set('intake_photo_required', $keep === '' ? '0' : $keep, 'test');
})();

