    return $ok;
})());
chk('sms: textbee is called as documented — x-api-key, E.164 recipients, deviceId — and a queued batch is a send', (function () {
    $GLOBALS['CONFIG']['sms'] = ['default_country' => 'NG', 'textbee' => ['api_key' => 'tb-key', 'device_id' => 'dev123']];
