/* ── The server-side QR encoder ────────────────────────────────────────────────
 * The maths and the tables are checked here; that the output is a QR a real reader
 * accepts is checked in tests/scanners.test.js, which decodes it with jsQR — the
 * same decoder the kiosks load. An encoder is only correct if a reader agrees.
 */
chk('the QR tables agree with themselves', qr_self_check() === []);
chk('the Reed-Solomon generator matches the published polynomial', (function () {
    /* The first draft built this lowest-degree-first while the division expects
       the monic leading coefficient at index 0. The polynomial was correct and
       every codeword it produced was wrong — invisible until a reader refuses the
       code, which is exactly what happened. */
    [$exp, $log] = qr_gf();
    $g = qr_rs_generator(10);
    $want = [0, 251, 67, 46, 61, 118, 70, 64, 94, 32, 45];
    if (count($g) !== count($want)) return false;
    foreach ($g as $i => $c) if ($log[$c] !== $want[$i]) return false;
    return true;
})());
chk('a version is picked from the payload length, smallest first', (function () {
    return qr_pick_version(10) === 1 && qr_pick_version(14) === 1 && qr_pick_version(15) === 2
        && qr_pick_version(62) === 4 && qr_pick_version(666) === 20
        // Past every supported version it refuses rather than guessing.
        && qr_pick_version(700) === 0;
})());
chk('the encoder produces a real PNG at every version', (function () {
    foreach ([1, 4, 7, 10, 14, 20] as $v) {
        $len = qr_capacity($v);
        $png = qr_encode_png(str_repeat('A', $len), 4);
        if ($png === '' || substr($png, 0, 8) !== "\x89PNG\r\n\x1a\n") return false;
        // IHDR width must be (modules + 8 quiet) * scale.
        $size = 21 + ($v - 1) * 4;
        $w = unpack('N', substr($png, 16, 4))[1];
        if ($w !== ($size + 8) * 4) return false;
    }
    return true;
})());
chk('…and refuses, rather than throwing, on something it cannot hold', (function () {
    return qr_encode_png(str_repeat('A', 900)) === '' && qr_encode_png('') === '';
})());
chk('the timing pattern survives the format reservation', (function () {
    /* Two modules — (6,8) and (8,6) — where the format area crosses the timing
       patterns. Reserving the crossing as format blanked them, and no reader on
       earth decodes that. */
    [$size, $m] = qr_matrix('HELLO');
    for ($i = 8; $i < $size - 8; $i++) {
        if ($m[6][$i] !== ($i % 2 === 0 ? 1 : 0)) return false;
        if ($m[$i][6] !== ($i % 2 === 0 ? 1 : 0)) return false;
    }
    // And the dark module, which the reservation loop used to walk over.
    return $m[$size - 8][8] === 1;
})());
chk('a version-7 code carries version information in the right rows', (function () {
    /* Versions 1-6 have no version area, so a reversed row index decoded fine up
       to 41x41 and on nothing above it. A bug behind a size threshold is one a
       short test payload never reaches. */
    [$size, $m] = qr_matrix(str_repeat('A', qr_capacity(7)));
    if ($size !== 45) return false;
    $vb = QR_VERSION_BITS[7];
    for ($i = 0; $i < 18; $i++) {
        $bit = ($vb >> $i) & 1;
        if ($m[intdiv($i, 3)][$size - 11 + $i % 3] !== $bit) return false;
        if ($m[$size - 11 + $i % 3][intdiv($i, 3)] !== $bit) return false;
    }
    return true;
})());

/* ── The hosted QR the automatic email needs ───────────────────────────────── */
chk('an ID email encodes its own QR when nothing has cached one', (function () {
    /* This is the whole point of the encoder. Before it, an ID issued with no
       browser present — a parent clicking a consent link at 2am — sent a link and
       no code, and no screen anywhere said which families those were. */
    $st = db_row("SELECT studentId, token FROM summer_students WHERE token != '' AND parentEmail != '' LIMIT 1");
    if (!$st) return true;
    @unlink(qr_cache_path((string)$st['token']));
    $GLOBALS['__mail_sink'] = [];
    $r = student_send_id((string)$st['studentId']);
    $mail = $GLOBALS['__mail_sink'];
    unset($GLOBALS['__mail_sink']);
    $hosted = qr_cache_exists((string)$st['token']);
    $body = $mail ? (string)($mail[count($mail) - 1]['html'] ?? $mail[count($mail) - 1]['body'] ?? '') : '';
    return !empty($r['ok']) && $hosted
        // …and the email references the hosted image rather than only the link.
        && strpos($body, 'qr.php?t=') !== false;
})());
chk('…and an already-cached QR is reused rather than re-encoded', (function () {
    $st = db_row("SELECT token FROM summer_students WHERE token != '' LIMIT 1");
    if (!$st) return true;
    $tok = (string)$st['token'];
    qr_ensure_cached($tok);
    $before = filemtime(qr_cache_path($tok));
    clearstatcache();
    $again = qr_ensure_cached($tok);
    // Same file, untouched: re-encoding 300 tokens to produce identical bytes on a
    // shared host is waste, and the browser-rendered copy is the same code anyway.
    return $again && filemtime(qr_cache_path($tok)) === $before;
})());
chk('the email always references the QR, because the URL always resolves', (function () {
    /* The <img> used to be withheld when no PNG was cached at send time, which is
       only the right call while the URL can 404. It cannot now: qr.php encodes on
       demand. Withholding it meant a family got a message with no code and nothing
       said so. */
    $st = db_row("SELECT studentId, token FROM summer_students WHERE token != '' AND parentEmail != '' LIMIT 1");
    if (!$st) return true;
    @unlink(qr_cache_path((string)$st['token']));
    $GLOBALS['__mail_sink'] = [];
    student_send_id((string)$st['studentId']);
    $mail = $GLOBALS['__mail_sink'];
    unset($GLOBALS['__mail_sink']);
    $body = $mail ? (string)($mail[count($mail) - 1]['html'] ?? $mail[count($mail) - 1]['body'] ?? '') : '';
    return strpos($body, 'qr.php?t=') !== false && strpos($body, '<img') !== false;
})());
chk('the gaps read counts who is missing a QR without sending anything', (function () {
    $r = backend_dispatch('admin.id.qrgaps', ['requesterId' => 'NGG-2025-0099']);
    return !empty($r['ok']) && isset($r['verified'], $r['missingQr'], $r['unreachable'], $r['sample'])
        && $r['encoder'] === true;
})());
chk('families with no contact are LISTED, not just counted', (function () use ($GATE) {
    /* Counting them told an admin a number without telling them whose, which is
       not a task anybody can finish. These are the children whose ID was issued
       and never delivered — no email and no phone, usually a row from before the
       form asked for either. Sending harder does nothing; only a contact does. */
    $reg = backend_dispatch('gate.register', ['gate' => $GATE['gateId'], 'data' => [
        'fullName' => 'Lost Contact Kid', 'age' => 12,
        'dob' => gmdate('Y-m-d', strtotime('-12 years -9 months')),
        'faculty' => 'AI & Technology', 'course' => 'Practical Coding', 'centre' => 'Main',
        'parentName' => 'Mrs Lost', 'parentPhone' => '08030000401']]);
    if (empty($reg['studentId'])) return false;
    $sid = (string)$reg['studentId'];
    backend_dispatch('admin.registration.consent.record', ['requesterId' => 'NGG-2025-0099',
        'studentId' => $sid, 'method' => 'paper', 'guardianName' => 'Mrs Lost',
        'consents' => ['participation' => true, 'medical' => true, 'data' => true,
                       'media' => true, 'site_visibility' => true, 'trips' => true, 'comms' => true]]);
    // Now lose both contacts, which is the shape the real rows are in.
    db_update('summer_students', ['parentEmail' => '', 'guardianPhone' => ''], ['studentId' => $sid]);

    $r = backend_dispatch('admin.id.qrgaps', ['requesterId' => 'NGG-2025-0099']);
    $mine = array_values(array_filter($r['unreachableList'] ?? [], fn($x) => $x['studentId'] === $sid));
    /* Asserted on the id, not the name: registration keeps a first and a last
       name and drops the middle, so "Lost Contact Kid" is stored as "Lost Kid".
       A test that pinned the composed name would be testing the name rule. */
    return !empty($r['ok']) && count($mine) === 1
        && $mine[0]['fullName'] !== ''
        // The guardian's NAME is carried even though the contact is not — it is
        // what a coordinator uses to work out who to ring.
        && $mine[0]['guardianName'] === 'Mrs Lost'
        // And they are excluded from the missing-QR list, because sending is not
        // the fix for them and mixing the two hides both problems.
        && !array_filter($r['sample'] ?? [], fn($x) => $x['studentId'] === $sid);
})());
chk('…and adding a contact makes the ID deliverable, through the existing writer', (function () {
    /* Two calls rather than a new endpoint: the student writer already validates
       an address, and a second path that wrote contacts would be a second place
       for that validation to drift. */
    $r = backend_dispatch('admin.id.qrgaps', ['requesterId' => 'NGG-2025-0099']);
    $lost = array_values(array_filter($r['unreachableList'] ?? [], fn($x) => ($x['guardianName'] ?? '') === 'Mrs Lost'));
    if (!$lost) return true;
    $sid = $lost[0]['studentId'];
    $bad = backend_dispatch('admin.summer.student.update', ['requesterId' => 'NGG-2025-0099',
        'studentId' => $sid, 'data' => ['parentEmail' => 'not-an-address']]);
    $up = backend_dispatch('admin.summer.student.update', ['requesterId' => 'NGG-2025-0099',
        'studentId' => $sid, 'data' => ['parentEmail' => 'found@example.com']]);
    $GLOBALS['__mail_sink'] = [];
    $send = backend_dispatch('admin.id.resend', ['requesterId' => 'NGG-2025-0099', 'kind' => 'student', 'id' => $sid]);
    $sent = array_values(array_filter($GLOBALS['__mail_sink'], fn($m) => ($m['to'] ?? '') === 'found@example.com'));
    unset($GLOBALS['__mail_sink']);
    $after = backend_dispatch('admin.id.qrgaps', ['requesterId' => 'NGG-2025-0099']);
    $still = array_filter($after['unreachableList'] ?? [], fn($x) => $x['studentId'] === $sid);
    return ($bad['error'] ?? '') === 'bad_email'      // a typo is refused, not stored
        && !empty($up['ok']) && !empty($send['ok'])
        && count($sent) === 1                          // the ID actually went out
        && in_array('email', $send['channels'] ?? [], true)
        && !empty($send['onFile'])                     // a contact on file is reported as such
        && !$still;                                    // and they leave the list
})());
chk('resending an ID says whether anybody is on file, so a failed send is not called "nobody to send to"', (function () {
    $st = db_row("SELECT studentId, parentEmail, guardianPhone FROM summer_students WHERE token != '' LIMIT 1");
    if (!$st) return true;
    $sid = $st['studentId'];
    db_update('summer_students', ['parentEmail' => '', 'guardianPhone' => ''], ['studentId' => $sid]);
