    return ($pub['error'] ?? '') === 'preflight';
})());
chk('millimetres come from the design\'s own trim size, not from the width of a card', (function () {
    /* The bug this replaced: every mm figure divided by 54/590 — the width of an
       ID card — so the same 98-unit QR measured 9mm whether it sat on a card or
       on an A4 sheet. On A4 it is 23mm and perfectly fine; the old rule would
       have warned about it forever. */
    $card = ['w' => 590, 'wMm' => 54];
    $a4 = ['w' => 877, 'wMm' => 210];
    return abs(ctpl_mm_per_unit($card) * 98 - 8.97) < 0.1
        && abs(ctpl_mm_per_unit($a4) * 98 - 23.5) < 0.5;
})());
chk('a design bigger than anything printable is still refused', (function () {
    $r = backend_dispatch('admin.card.template.save', ['requesterId' => 'NGG-2025-0099', 'template' => [
        'name' => 'Absurd', 'kind' => 'graphic', 'w' => 900, 'h' => 900, 'wMm' => 40000, 'hMm' => 40000,
        'elements' => [],
    ]]);
    return ($r['error'] ?? '') === 'invalid' && in_array('sizeMm', $r['fields'] ?? [], true);
})());

chk('designs are gated on people, not on summer', (function () {
    /* Deliberately a different capability from the roster: the staff who verify
       children and the staff who decide what a credential looks like are
       different jobs, and the second can invalidate every card at a gate. */
    return backend_dispatch('admin.card.templates', ['requesterId' => ''])['ok'] !== true
        && backend_dispatch('admin.card.template.save', ['requesterId' => '', 'template' => []])['ok'] !== true;
})());

chk('bulk resend and the gaps read are both admin-gated', (function () {
    return backend_dispatch('admin.id.resend.bulk', ['requesterId' => '', 'scope' => 'all'])['ok'] !== true
        && backend_dispatch('admin.id.qrgaps', ['requesterId' => ''])['ok'] !== true;
})());

chk('a screen that has drawn a QR can hand it over for the emails that have no browser', (function () {
    /* Mail clients strip data: URIs, so an in-email QR must be a hosted PNG — and
       there is no encoder on the server, only the one the card studio has just
       used to draw every card. An ID issued when a parent clicks a link at 2am has
       no browser to borrow, so the studio lends its own. */
    $tok = db_row("SELECT token FROM summer_students WHERE token != '' LIMIT 1")['token'] ?? '';
    if ($tok === '') return true;
    @unlink(qr_cache_path($tok));
    // A 24x24 PNG — qr_cache_store refuses anything under 60 bytes.
    $im = imagecreatetruecolor(24, 24);
    imagefill($im, 0, 0, imagecolorallocate($im, 255, 255, 255));
    ob_start(); imagepng($im); $png = ob_get_clean(); imagedestroy($im);
    $dataUrl = 'data:image/png;base64,' . base64_encode($png);

    $r = backend_dispatch('admin.qr.warm', ['requesterId' => 'NGG-2025-0099',
        'items' => [['token' => $tok, 'qrPng' => $dataUrl]]]);
    $stored = qr_cache_exists($tok);
    // A second pass must not rewrite what is already hosted.
    $r2 = backend_dispatch('admin.qr.warm', ['requesterId' => 'NGG-2025-0099',
        'items' => [['token' => $tok, 'qrPng' => $dataUrl]]]);
    // And a token belonging to nothing is never cached — no QR-for-anything.
    $r3 = backend_dispatch('admin.qr.warm', ['requesterId' => 'NGG-2025-0099',
        'items' => [['token' => 'NOT-A-REAL-TOKEN', 'qrPng' => $dataUrl]]]);
    @unlink(qr_cache_path($tok));
    return !empty($r['ok']) && ($r['stored'] ?? 0) === 1 && $stored
        && ($r2['stored'] ?? -1) === 0 && ($r2['skipped'] ?? 0) === 1
        && ($r3['stored'] ?? -1) === 0;
})());
chk('…and the hosted image is the server\'s own drawing — a browser cannot plant a QR that opens another address', (function () {
    /* Anybody with `summer` could send any PNG as a token's QR; the email and
       /api/public/qr.php then served it. The bytes sent are now ignored. */
    $tok = db_row("SELECT token FROM summer_students WHERE token != '' LIMIT 1")['token'] ?? '';
    if ($tok === '') return true;
    @unlink(qr_cache_path($tok));
    $im = imagecreatetruecolor(40, 40); imagefill($im, 0, 0, imagecolorallocate($im, 255, 0, 0));
    ob_start(); imagepng($im); $evil = ob_get_clean(); imagedestroy($im);
    backend_dispatch('admin.qr.warm', ['requesterId' => 'NGG-2025-0099', 'items' => [['token' => $tok, 'qrPng' => 'data:image/png;base64,' . base64_encode($evil)]]]);
    $hosted = (string)@file_get_contents(qr_cache_path($tok));
    $own = qr_encode_png(qr_payload_for($tok), 8);
    // …and a resend cannot overwrite it either.
    qr_cache_store($tok, 'data:image/png;base64,' . base64_encode($evil));
    $after = (string)@file_get_contents(qr_cache_path($tok));
    @unlink(qr_cache_path($tok));
    return $hosted !== '' && $hosted !== $evil && $hosted === $own && $after === $own;
})());
chk('the QR warm op is admin-gated', backend_dispatch('admin.qr.warm', ['requesterId' => '', 'items' => [['token' => 'x', 'qrPng' => 'y']]])['ok'] !== true);
chk('the studio asks which QR images are missing before sending any: only real, un-hosted tokens come back', (function () {
    /* Sending every token's PNG on every visit was a quarter of a megabyte a
       request, and a shared host reset the connection for it. The probe sends
       tokens only, and the answer names the ones worth a PNG. */
    $tok = db_row("SELECT token FROM summer_students WHERE token != '' LIMIT 1")['token'] ?? '';
    if ($tok === '') return true;
    @unlink(qr_cache_path($tok));
    $r = backend_dispatch('admin.qr.warm', ['requesterId' => 'NGG-2025-0099', 'probe' => true,
        'items' => [['token' => $tok], ['token' => $tok], ['token' => 'NOT-A-REAL-TOKEN']]]);
    $im = imagecreatetruecolor(24, 24);
    imagefill($im, 0, 0, imagecolorallocate($im, 255, 255, 255));
    ob_start(); imagepng($im); $png = ob_get_clean(); imagedestroy($im);
    backend_dispatch('admin.qr.warm', ['requesterId' => 'NGG-2025-0099', 'items' => [['token' => $tok, 'qrPng' => 'data:image/png;base64,' . base64_encode($png)]]]);
    $r2 = backend_dispatch('admin.qr.warm', ['requesterId' => 'NGG-2025-0099', 'probe' => true, 'items' => [['token' => $tok]]]);
    $wrote = qr_cache_exists($tok);
    @unlink(qr_cache_path($tok));
    return !empty($r['ok']) && ($r['missing'] ?? null) === [$tok] && $wrote && ($r2['missing'] ?? null) === [];
})());

/* ── Consent given off-line ───────────────────────────────────────────────────
 * A desk registration waits for a parent to click a link, and most do. The ones
 * who do not are a guardian with no email address, a phone that cannot open the
 * link, or a paper form filled in at the centre — and those children used to
 * stay pending forever and never get an ID. The tests below are all about what
 * recording it off-line must NOT be allowed to become.
 */
$PC1 = backend_dispatch('gate.register', ['gate' => $GATE['gateId'], 'data' => [
    'fullName' => 'Paper Consent', 'age' => 12, 'dob' => gmdate('Y-m-d', strtotime('-12 years -2 months')),
    'faculty' => 'AI & Technology', 'course' => 'Practical Coding', 'centre' => 'Main',
    'parentName' => 'Mrs Adeyemi', 'parentPhone' => '08030000001']]);

chk('recording a consent off-line is not a "mark verified" switch', (function () use ($PC1) {
    /* A consent has content: which permissions, whose, and how. Every one of
       these refusals is a field that a verify-button would have thrown away. */
    $base = ['requesterId' => 'NGG-2025-0099', 'studentId' => $PC1['studentId']];
    $noMethod = backend_dispatch('admin.registration.consent.record', $base + ['guardianName' => 'Mrs Adeyemi', 'consents' => ['participation' => true]]);
    $noName = backend_dispatch('admin.registration.consent.record', $base + ['method' => 'paper', 'consents' => ['participation' => true]]);
    $noConsents = backend_dispatch('admin.registration.consent.record', $base + ['method' => 'paper', 'guardianName' => 'Mrs Adeyemi', 'consents' => []]);
    return ($noMethod['error'] ?? '') === 'method_required'
        && ($noName['error'] ?? '') === 'guardian_name_required'
        && ($noConsents['error'] ?? '') === 'consents_incomplete'
        // Still pending: not one of those attempts half-wrote anything.
        && db_row("SELECT regStatus FROM summer_students WHERE studentId = ?", [$PC1['studentId']])['regStatus'] === 'parent_pending';
})());
chk('…a free choice must be answered either way, not defaulted', (function () use ($PC1) {
    /* media and site_visibility are p=1 mustAnswer: refusing them must never cost
       a child their place, so they are required to be ANSWERED and never required
       to be granted. A form that silently defaulted them to "no" would record a
       refusal the family never made. */
    $r = backend_dispatch('admin.registration.consent.record', ['requesterId' => 'NGG-2025-0099',
        'studentId' => $PC1['studentId'], 'method' => 'paper', 'guardianName' => 'Mrs Adeyemi',
        'consents' => ['participation' => true, 'medical' => true, 'data' => true, 'trips' => true, 'comms' => true]]);
    return ($r['error'] ?? '') === 'consents_incomplete'
        && in_array('media', $r['missing'] ?? [], true)
        && in_array('site_visibility', $r['missing'] ?? [], true);
})());
chk('a complete off-line consent verifies the child and issues the ID', (function () use ($PC1) {
    $r = backend_dispatch('admin.registration.consent.record', ['requesterId' => 'NGG-2025-0099',
        'studentId' => $PC1['studentId'], 'method' => 'paper', 'guardianName' => 'Mrs Adeyemi',
        'note' => 'Filed in the Egbeda folder',
        'consents' => ['participation' => true, 'medical' => true, 'data' => true,
                       'media' => false, 'site_visibility' => false, 'trips' => true, 'comms' => true]]);
    if (empty($r['ok'])) return false;
    $s = db_row("SELECT regStatus, token, consentSignedName, reviewedById FROM summer_students WHERE studentId = ?", [$PC1['studentId']]);
    $led = db_all("SELECT type, status, method, actorName, recordedById FROM consents WHERE studentId = ?", [$PC1['studentId']]);
    $byType = []; foreach ($led as $c) $byType[$c['type']] = $c;
    return $s['regStatus'] === 'verified' && !empty($s['token'])
        /* The guardian is recorded as the actor and the STAFF MEMBER separately.
           Conflating them would record staff as having consented for a family. */
        && $s['consentSignedName'] === 'Mrs Adeyemi'
        && $byType['participation']['actorName'] === 'Mrs Adeyemi'
        && $byType['participation']['recordedById'] === 'NGG-2025-0099'
        /* And the METHOD is distinct from a parent clicking the link. A
           safeguarding review has to be able to tell a signed form from a click;
           a ledger that flattened the two would be worse than one with gaps. */
        && $byType['participation']['method'] === 'desk_paper'
        // The family's actual answers, including the two they declined.
        && $byType['media']['status'] === 'declined'
        && $byType['site_visibility']['status'] === 'declined'
        && $byType['trips']['status'] === 'granted';
})());
chk('…and recording it twice is a no-op rather than a second ledger entry', (function () use ($PC1) {
    $before = (int)db_row("SELECT COUNT(*) c FROM consents WHERE studentId = ?", [$PC1['studentId']])['c'];
    $r = backend_dispatch('admin.registration.consent.record', ['requesterId' => 'NGG-2025-0099',
        'studentId' => $PC1['studentId'], 'method' => 'paper', 'guardianName' => 'Mrs Adeyemi',
        'consents' => ['participation' => true, 'medical' => true, 'data' => true,
                       'media' => true, 'site_visibility' => true, 'trips' => true, 'comms' => true]]);
    $after = (int)db_row("SELECT COUNT(*) c FROM consents WHERE studentId = ?", [$PC1['studentId']])['c'];
    // Not an error — the desk's job is done — but the ledger must not grow, and
    // the family's real answers must not be overwritten by a second attempt.
    return !empty($r['already']) && $after === $before;
})());
chk('a public self-registration is sent to the review desk, not verified here', (function () use ($GATE) {
    $sg = backend_dispatch('admin.gates.create', ['requesterId' => 'NGG-2025-0099', 'name' => 'Consent selfreg', 'kind' => 'self']);
    $sub = backend_dispatch('selfreg.submit', ['gate' => $sg['gateId'], 'consent' => true, 'data' => [
        'fullName' => 'Self Consent Kid', 'dob' => gmdate('Y-m-d', strtotime('-11 years -1 month')),
        'centre' => 'Main', 'faculty' => 'AI & Technology', 'course' => 'Practical Coding',
        'parentName' => 'Mrs Self', 'parentPhone' => '08030000009']]);
    if (empty($sub['ok'])) return true;   // gate config differs; nothing to assert
    /* A different question — has this SUBMISSION been reviewed — and it has its
       own desk with the photograph and the submitted answers side by side.
       Answering it here would be answering the wrong question. */
    $r = backend_dispatch('admin.registration.consent.record', ['requesterId' => 'NGG-2025-0099',
        'studentId' => $sub['studentId'], 'method' => 'paper', 'guardianName' => 'Mrs Self',
        'consents' => ['participation' => true, 'medical' => true, 'data' => true,
                       'media' => true, 'site_visibility' => true, 'trips' => true, 'comms' => true]]);
    return ($r['error'] ?? '') === 'use_review_desk';
})());
chk('the consent ledger is readable without SQL, with the permission list', (function () use ($PC1) {
    $r = backend_dispatch('admin.registration.consents', ['requesterId' => 'NGG-2025-0099', 'studentId' => $PC1['studentId']]);
    if (empty($r['ok'])) return false;
    /* The permission list comes from the server so the parent form, the desk form
       and the ledger agree about what a consent consists of. Three hard-coded
       copies would drift, and the one that drifts is the record. */
    $types = array_column($r['types'], 'type');
    $required = array_values(array_filter($r['types'], fn($t) => !empty($t['required'])));
    $mustAnswer = array_values(array_filter($r['types'], fn($t) => !empty($t['mustAnswer'])));
    return count($types) === count(CONSENT_TYPES) && in_array('participation', $types, true)
        && count($required) === 3 && count($mustAnswer) === 2
        && count($r['methods']) === count(CONSENT_DESK_METHODS)
        && count($r['ledger']) >= count(CONSENT_TYPES)
        && $r['student']['regStatus'] === 'verified';
})());
chk('the permission list can be read WITHOUT a child, for the sweep', (function () {
    /* "Record consent for everyone waiting" has no single student to probe, and
       requiring one shipped a dialog with an empty method dropdown, no permissions
       to tick and a dead button. The form rendered, so it read as a styling
       problem rather than a missing payload. */
    $r = backend_dispatch('admin.registration.consents', ['requesterId' => 'NGG-2025-0099', 'studentId' => '']);
    return !empty($r['ok']) && $r['student'] === null
        && count($r['types']) === count(CONSENT_TYPES)
        && count($r['methods']) === count(CONSENT_DESK_METHODS);
})());
chk('…while a studentId that does not exist is still an error', (function () {
    return backend_dispatch('admin.registration.consents', ['requesterId' => 'NGG-2025-0099',
        'studentId' => 'SUM-NOPE-999'])['error'] === 'not_found';
})());
chk('recording a consent needs the summer capability', (function () use ($PC1) {
    return backend_dispatch('admin.registration.consent.record', ['requesterId' => '',
        'studentId' => $PC1['studentId'], 'method' => 'paper', 'guardianName' => 'X'])['ok'] !== true;
})());

/* ── Bulk, and the shape that keeps it honest ─────────────────────────────── */
chk('bulk consent takes an explicit list, never a filter the server expands', (function () use ($GATE) {
    $ids = [];
    foreach (['Bulk One', 'Bulk Two'] as $i => $name) {
        $r = backend_dispatch('gate.register', ['gate' => $GATE['gateId'], 'data' => [
            'fullName' => $name, 'age' => 13, 'dob' => gmdate('Y-m-d', strtotime('-13 years -1 month')),
            'faculty' => 'AI & Technology', 'course' => 'Practical Coding', 'centre' => 'Main',
            'parentName' => 'Guardian ' . $i, 'parentPhone' => '0803000010' . $i]]);
        $ids[] = $r['studentId'];
    }
    $none = backend_dispatch('admin.registration.consent.bulk', ['requesterId' => 'NGG-2025-0099',
        'method' => 'paper', 'consents' => ['participation' => true]]);
    $r = backend_dispatch('admin.registration.consent.bulk', ['requesterId' => 'NGG-2025-0099',
        'studentIds' => $ids, 'method' => 'paper',
        'consents' => ['participation' => true, 'medical' => true, 'data' => true,
                       'media' => false, 'site_visibility' => true, 'trips' => true, 'comms' => true]]);
    if (empty($r['ok'])) return false;
    $rows = db_all("SELECT studentId, regStatus, consentSignedName FROM summer_students WHERE studentId IN (?, ?)", $ids);
    $signed = array_column($rows, 'consentSignedName', 'studentId');
    return ($none['error'] ?? '') === 'no_students'
        && count($r['recorded']) === 2 && $r['skipped'] === []
        && count(array_filter($rows, fn($x) => $x['regStatus'] === 'verified')) === 2
        /* Each child's OWN guardian. Twenty families did not all send the same
           person, and stamping one name across them would be the lie this shape
           exists to prevent. */
        && $signed[$ids[0]] === 'Guardian 0' && $signed[$ids[1]] === 'Guardian 1';
})());
chk('…and a child with no guardian on file is skipped and named, not invented', (function () use ($GATE) {
    /* There is nobody to record as having consented, so nothing is recorded —
       and the desk is told which child, so they can go and ask. */
    $r = backend_dispatch('gate.register', ['gate' => $GATE['gateId'], 'data' => [
        'fullName' => 'No Guardian', 'age' => 13, 'dob' => gmdate('Y-m-d', strtotime('-13 years -4 months')),
        'faculty' => 'AI & Technology', 'course' => 'Practical Coding', 'centre' => 'Main',
        'parentName' => 'Temp Name', 'parentPhone' => '08030000099']]);
    /* Then emptied, which is the shape a real row arrives in: an older record
       from before the field was required, or a name cleared during an edit. The
       form itself will not accept a blank one. */
    db_update('summer_students', ['guardianName' => ''], ['studentId' => $r['studentId']]);
    $b = backend_dispatch('admin.registration.consent.bulk', ['requesterId' => 'NGG-2025-0099',
        'studentIds' => [$r['studentId']], 'method' => 'paper',
        'consents' => ['participation' => true, 'medical' => true, 'data' => true,
                       'media' => true, 'site_visibility' => true, 'trips' => true, 'comms' => true]]);
    $skipped = $b['skipped'][0] ?? [];
    return !empty($b['ok']) && $b['recorded'] === []
        && ($skipped['reason'] ?? '') === 'no_guardian_on_file'
        && ($skipped['name'] ?? '') === 'No Guardian'
        && db_row("SELECT regStatus FROM summer_students WHERE studentId = ?", [$r['studentId']])['regStatus'] === 'parent_pending'
        // And nothing was written to the ledger for them.
        && (int)db_row("SELECT COUNT(*) c FROM consents WHERE studentId = ?", [$r['studentId']])['c'] === 0;
})());
chk('the whole pending queue can be swept in one action', (function () use ($GATE) {
    /* A programme that collected consent on paper at intake has a queue a
       stack-at-a-time interface will never clear. The safeguards that matter are
       per child, not per request, so they survive the sweep intact — which is
       what the assertions below check, not merely that it ran. */
    $made = [];
    foreach ([0, 1, 2] as $i) {
        $r = backend_dispatch('gate.register', ['gate' => $GATE['gateId'], 'data' => [
            'fullName' => 'Sweep Kid ' . $i, 'age' => 12,
            'dob' => gmdate('Y-m-d', strtotime('-12 years -5 months')),
            'faculty' => 'AI & Technology', 'course' => 'Practical Coding', 'centre' => 'Main',
            'parentName' => 'Sweep Guardian ' . $i, 'parentPhone' => '0803000020' . $i]]);
        $made[] = $r['studentId'];
    }
    // One of them loses its guardian, so the sweep has something to skip.
    db_update('summer_students', ['guardianName' => ''], ['studentId' => $made[2]]);

    $before = (int)db_row("SELECT COUNT(*) c FROM summer_students WHERE regStatus = 'parent_pending'")['c'];
    if ($before < 3) return false;
    $r = backend_dispatch('admin.registration.consent.bulk', ['requesterId' => 'NGG-2025-0099',
        'scope' => 'all_pending', 'method' => 'paper',
        'consents' => ['participation' => true, 'medical' => true, 'data' => true,
                       'media' => true, 'site_visibility' => true, 'trips' => true, 'comms' => true]]);
    if (empty($r['ok'])) return false;

    $rows = db_all("SELECT studentId, regStatus, consentSignedName FROM summer_students WHERE studentId IN (?, ?, ?)", $made);
    $by = []; foreach ($rows as $x) $by[$x['studentId']] = $x;
    return ($r['scope'] ?? '') === 'all_pending'
        // Nobody is left waiting who had a guardian on file.
        && (int)db_row("SELECT COUNT(*) c FROM summer_students WHERE regStatus = 'parent_pending' AND guardianName != ''")['c'] === 0
        && $by[$made[0]]['regStatus'] === 'verified' && $by[$made[1]]['regStatus'] === 'verified'
        /* Each child's OWN guardian, across a sweep the caller never enumerated.
           This is the property that makes the sweep defensible: one name stamped
           on four hundred families would be a fabrication in the consent ledger. */
        && $by[$made[0]]['consentSignedName'] === 'Sweep Guardian 0'
        && $by[$made[1]]['consentSignedName'] === 'Sweep Guardian 1'
        // And the one with no guardian is still pending, and was named.
        && $by[$made[2]]['regStatus'] === 'parent_pending'
        && count(array_filter($r['skipped'], fn($x) => ($x['reason'] ?? '') === 'no_guardian_on_file')) >= 1;
})());
chk('…a sweep of an empty queue says so rather than reporting a success', (function () {
    $r = backend_dispatch('admin.registration.consent.bulk', ['requesterId' => 'NGG-2025-0099',
        'scope' => 'all_pending', 'centre' => 'Nowhere At All', 'method' => 'paper',
        'consents' => ['participation' => true, 'medical' => true, 'data' => true,
                       'media' => true, 'site_visibility' => true, 'trips' => true, 'comms' => true]]);
    return !empty($r['ok']) && $r['recorded'] === [] && ($r['remaining'] ?? -1) === 0
        && strpos((string)($r['note'] ?? ''), 'Nobody is waiting') !== false;
})());
chk('…and a sweep is audited as a sweep, not as a ticked batch', (function () {
    $row = db_row("SELECT event FROM audit_log WHERE event = 'registration.consent.desk.sweep' ORDER BY id DESC LIMIT 1");
    /* Same writes, different decision. Six months later this line is the only
       way to tell "somebody worked through a stack" from "somebody cleared the
       queue in one click". */
    return !empty($row);
})());
chk('…bulk is capped, so one call cannot verify a cohort', (function () {
    $r = backend_dispatch('admin.registration.consent.bulk', ['requesterId' => 'NGG-2025-0099',
        'studentIds' => array_map(fn($i) => 'SUM-FAKE-' . $i, range(1, CONSENT_BULK_MAX + 1)),
        'method' => 'paper', 'consents' => ['participation' => true, 'medical' => true, 'data' => true,
            'media' => true, 'site_visibility' => true, 'trips' => true, 'comms' => true]]);
    return ($r['error'] ?? '') === 'too_many' && ($r['max'] ?? 0) === CONSENT_BULK_MAX;
})());
chk('…and bulk enforces the same consent rules as one at a time', (function () {
    $r = backend_dispatch('admin.registration.consent.bulk', ['requesterId' => 'NGG-2025-0099',
        'studentIds' => ['SUM-WHATEVER'], 'method' => 'paper',
        'consents' => ['participation' => true]]);
    return ($r['error'] ?? '') === 'consents_incomplete';
})());

chk('gate: revoked link stops working', (function () use ($GATE) {
    backend_dispatch('admin.gates.revoke', ['requesterId' => 'NGG-2025-0099', 'gateId' => $GATE['gateId']]);
    return backend_dispatch('gate.context', ['gate' => $GATE['gateId']])['error'] === 'gate_invalid';
})());
/* ── Idempotent intake ──────────────────────────────────────────────────────
 * What makes a retry safe, and therefore what makes the offline outbox
 * possible. Without it a re-send after a timeout either created a second child
 * or reported a failure for a registration that had already worked. */
chk('intake: no submissionId behaves exactly as before', (function () {
    $n = 0;
    $r = intake_once('', 'test.op', function () use (&$n) { $n++; return ['ok' => true, 'n' => $n]; });
    $r2 = intake_once('', 'test.op', function () use (&$n) { $n++; return ['ok' => true, 'n' => $n]; });
    // Two calls, two runs — an absent key must not start deduplicating.
    return $n === 2 && $r['n'] === 1 && $r2['n'] === 2;
})());
chk('intake: a garbage submissionId is ignored rather than trusted', (function () {
    $n = 0;
    intake_once('../../etc/passwd', 'test.op', function () use (&$n) { $n++; return ['ok' => true]; });
    intake_once('short', 'test.op', function () use (&$n) { $n++; return ['ok' => true]; });
    return $n === 2 && intake_submission_id('../../etc/passwd') === '' && intake_submission_id('short') === '';
})());
chk('intake: the same submissionId runs the work exactly once', (function () {
    $sid = 'sub_' . rand_hex(12);
    $n = 0;
    $mk = function () use (&$n) { $n++; return ['ok' => true, 'studentId' => 'STU-' . $n]; };
    $a = intake_once($sid, 'test.op', $mk);
    $b = intake_once($sid, 'test.op', $mk);
    // The retry gets the FIRST result back, not a second registration.
    return $n === 1 && $a['studentId'] === 'STU-1' && $b['studentId'] === 'STU-1'
        && empty($a['replayed']) && !empty($b['replayed']);
})());
chk('intake: a REFUSAL releases the key so a corrected resubmit works', (function () {
    $sid = 'sub_' . rand_hex(12);
    $bad = intake_once($sid, 'test.op', fn() => ['ok' => false, 'errors' => ['age' => 'Required.']]);
    // Same id, now with good data — must run, not replay the refusal for ever.
    $good = intake_once($sid, 'test.op', fn() => ['ok' => true, 'studentId' => 'STU-OK']);
    return !empty($bad['errors']) && !empty($good['ok']) && ($good['studentId'] ?? '') === 'STU-OK';
})());
chk('intake: a concurrent second attempt is refused, not run twice', (function () {
    $sid = 'sub_' . rand_hex(12);
    $inner = null;
    // Re-enter with the same id from INSIDE the work — the claim is already
    // held, which is the same state a truly concurrent request would see.
    intake_once($sid, 'test.op', function () use ($sid, &$inner) {
        $inner = intake_once($sid, 'test.op', fn() => ['ok' => true, 'studentId' => 'DOUBLE']);
        return ['ok' => true, 'studentId' => 'FIRST'];
    });
    return ($inner['error'] ?? '') === 'in_flight';
})());
chk('intake: a claim abandoned by a dead request is reclaimable', (function () {
    $sid = 'sub_' . rand_hex(12);
    db_insert('intake_submissions', ['submissionId' => $sid, 'op' => 'test.op', 'status' => 'pending',
        'resultJson' => '', 'createdAt' => gmdate('Y-m-d\TH:i:s\Z', time() - (INTAKE_CLAIM_IDLE + 60)), 'completedAt' => '']);
    $r = intake_once($sid, 'test.op', fn() => ['ok' => true, 'studentId' => 'RECLAIMED']);
    // A crash mid-submit must not lock a family out for ever.
    return ($r['studentId'] ?? '') === 'RECLAIMED';
})());
chk('intake: a throw releases the key and still reaches the caller', (function () {
    $sid = 'sub_' . rand_hex(12);
    $threw = false;
    try { intake_once($sid, 'test.op', function () { throw new RuntimeException('boom'); }); }
    catch (Throwable $e) { $threw = true; }
    return $threw && db_row('SELECT id FROM intake_submissions WHERE submissionId = ?', [$sid]) === null;
})());
chk('intake: gate.register is idempotent end to end through dispatch', (function () {
    // Its own gate: the shared $GATE is revoked by an earlier assertion.
    $g = backend_dispatch('admin.gates.create', ['requesterId' => 'NGG-2025-0099', 'kind' => 'register', 'generate' => true, 'name' => 'Idempotency desk']);
    $sid = 'sub_' . rand_hex(12);
    $d = ['fullName' => 'Idem Child', 'age' => 13, 'dob' => gmdate('Y-m-d', strtotime('-13 years -3 months')), 'faculty' => 'Music', 'course' => 'Guitar',
          'centre' => 'Main', 'parentName' => 'Mrs Idem', 'parentPhone' => '08031117777'];
    $a = backend_dispatch('gate.register', ['gate' => $g['gateId'], 'data' => $d, 'submissionId' => $sid]);
    $b = backend_dispatch('gate.register', ['gate' => $g['gateId'], 'data' => $d, 'submissionId' => $sid]);
    $count = (int) db_row("SELECT COUNT(*) c FROM summer_students WHERE fullName = 'Idem Child'")['c'];
    $same = !empty($a['ok']) && !empty($b['ok']) && $a['studentId'] === $b['studentId'];
    db_exec("DELETE FROM summer_students WHERE fullName = 'Idem Child'");
    // One row, and both attempts naming it — NOT a duplicate_suspect warning
    // about a registration that had in fact succeeded.
    return $same && $count === 1 && !empty($b['replayed']);
})());

chk('gate: an active link cannot be deleted — only revoked', (function () {
    $g = backend_dispatch('admin.gates.create', ['requesterId' => 'NGG-2025-0099', 'name' => 'Deletable desk']);
    $r = backend_dispatch('admin.gates.delete', ['requesterId' => 'NGG-2025-0099', 'gateId' => $g['gateId']]);
    // Still there, untouched.
    return $r['error'] === 'not_revoked'
        && db_row('SELECT gateId FROM gate_links WHERE gateId = ?', [$g['gateId']]) !== null;
})());
chk('gate: a revoked link deletes and is gone for good', (function () {
    $g = backend_dispatch('admin.gates.create', ['requesterId' => 'NGG-2025-0099', 'name' => 'Throwaway desk']);
    backend_dispatch('admin.gates.revoke', ['requesterId' => 'NGG-2025-0099', 'gateId' => $g['gateId']]);
    $r = backend_dispatch('admin.gates.delete', ['requesterId' => 'NGG-2025-0099', 'gateId' => $g['gateId']]);
    return !empty($r['ok'])
        && db_row('SELECT gateId FROM gate_links WHERE gateId = ?', [$g['gateId']]) === null
        && backend_dispatch('admin.gates.delete', ['requesterId' => 'NGG-2025-0099', 'gateId' => $g['gateId']])['error'] === 'not_found';
})());
chk('gate: delete is gated, not open to any member', (function () {
    $g = backend_dispatch('admin.gates.create', ['requesterId' => 'NGG-2025-0099', 'name' => 'Guarded desk']);
    backend_dispatch('admin.gates.revoke', ['requesterId' => 'NGG-2025-0099', 'gateId' => $g['gateId']]);
    $blocked = backend_dispatch('admin.gates.delete', ['requesterId' => 'NGG-2025-0001', 'gateId' => $g['gateId']])['error'] === 'forbidden';
    // Clean up so the guarded row does not linger in later assertions.
    backend_dispatch('admin.gates.delete', ['requesterId' => 'NGG-2025-0099', 'gateId' => $g['gateId']]);
    return $blocked;
})());
chk('registration events reached the outbox', (int)db_row("SELECT COUNT(*) c FROM outbox WHERE kind IN ('registration.created','registration.verified')")['c'] >= 2);

// ── Inbound attendance webhook ──
chk('hook: signature scheme verifies + rejects stale/bad', (function () {
    $sec = 'hooksecret'; $ts = (string)time(); $body = '{"a":1}';
    $sig = 'sha256=' . hash_hmac('sha256', $ts . '.' . $body, $sec);
    if (!hook_verify_signature($sec, $ts, $body, $sig)) return false;
    if (hook_verify_signature($sec, (string)(time() - 400), $body, $sig)) return false;   // stale
    if (hook_verify_signature($sec, $ts, $body, 'sha256=deadbeef')) return false;         // wrong
    if (hook_verify_signature('', $ts, $body, $sig)) return false;                        // disabled
    return true;
})());
chk('hook: batch marks summer student (by QR + ref) and member; idempotent; unknown reported', (function () {
    $st = db_row("SELECT studentId, token FROM summer_students WHERE regStatus = 'verified' ORDER BY id DESC LIMIT 1");
    $r = backend_dispatch('hooks.attendance', ['source' => 'unit', 'events' => [
        ['token' => $st['token']],
        ['ref' => 'NGG-2025-0001', 'date' => gmdate('Y-m-d')],
        ['ref' => 'GHOST-404'],
    ]]);
    if (empty($r['ok']) || $r['marked'] !== 2 || $r['unknown'] !== 1) return false;
    $r2 = backend_dispatch('hooks.attendance', ['source' => 'unit', 'events' => [['ref' => $st['studentId']]]]);
    if ($r2['already'] !== 1 || $r2['marked'] !== 0) return false;
    return (int)db_row("SELECT COUNT(*) c FROM attendance WHERE method = 'webhook'")['c'] === 2
        && (int)db_row("SELECT COUNT(*) c FROM outbox WHERE kind = 'attendance.marked'")['c'] >= 2;
})());

// ── The CACENTRE gate asking about NGG cards ──
chk('gate: a student card resolves to the least a desk needs — no guardian, no phone', (function () {
    $st = db_row("SELECT studentId, token, fullName FROM summer_students WHERE regStatus = 'verified' AND token != '' ORDER BY id DESC LIMIT 1");
    $r = backend_dispatch('hooks.gate.resolve', ['token' => strtolower($st['token'])]);
    if (empty($r['ok']) || $r['person']['ref'] !== $st['studentId'] || $r['person']['name'] !== $st['fullName'] || $r['person']['kind'] !== 'student') return false;
    /* punctuality is NGG's own lateness rule for the desk (gate_person_punctuality): a time and a grace, nothing about the child. */
    return array_keys($r['person']) === ['ref', 'name', 'kind', 'status', 'detail', 'expires_on', 'punctuality'];
})());
chk('gate: a withdrawn student is resolved with the reason, not as active', (function () {
