/* One assertion per promise. This was a single conjunction of six, and when
   it failed on MySQL roughly one run in four it said only that something
   among the six was wrong. A conjunction is a cheap way to write a test and
   an expensive way to read one. */
(function () {
    db_update('summer_students', ['centre' => 'Ijaiye'], ['regStatus' => 'verified']);
    $all = backend_dispatch('admin.cards.data', ['requesterId' => 'NGG-2025-0099']);
    chk('cards: the card data loads with at least one verified student (' . count($all['cards'] ?? []) . ')', !empty($all['ok']) && count($all['cards'] ?? []) >= 1);

    /* A student THIS check owns, read back by id.
       It used to assert on cards[0] of the whole list, which is whichever
       verified student sorts first — and if that one's display ID had already
       been minted while they were unplaced, it is "ST-26-007" and stays that
       way, because a printed ID is never reissued. Correct behaviour, failing
       assertion, about one run in seven on MySQL, and the message said only
       that something among six conditions was wrong. The check is about what
       a NEW verified student at a centre gets, so it makes one. */
    $ckc = summer_ensure_cohort();
    db_insert('summer_students', ['studentId' => 'STU-CARD-IJ', 'cohortId' => (string)$ckc['cohortId'], 'token' => 'SUMQR-CARDIJ',
        'handle' => 'cardij', 'fullName' => 'Ije Card', 'age' => 12, 'centre' => 'Ijaiye', 'track' => 'Tech',
        'regStatus' => 'verified', 'status' => 'active', 'enrolledAt' => now_iso(), 'updatedAt' => now_iso()]);
    $d = backend_dispatch('admin.cards.data', ['requesterId' => 'NGG-2025-0099', 'studentId' => 'STU-CARD-IJ']);
    chk('cards: that student\'s card is the one returned', !empty($d['ok']) && count($d['cards'] ?? []) === 1);
    $c = ($d['cards'] ?? [[]])[0];
    $yy = gmdate('y');
    chk('cards: a verified student gets a centre-prefixed serial, IJ-' . $yy . '-NNN (got "' . (string)($c['displayId'] ?? '') . '")',
        (bool)preg_match('/^IJ-' . $yy . '-\d{3}$/', (string)($c['displayId'] ?? '')));
    chk('cards: …and a Summer QR token (got "' . mb_substr((string)($c['token'] ?? ''), 0, 12) . '")', str_starts_with((string)($c['token'] ?? ''), 'SUMQR-'));
    chk('cards: …and their centre\'s own colour (got "' . (string)($c['centre']['color'] ?? '') . '" for centre "' . (string)($c['centre']['name'] ?? '') . '")',
        (string)($c['centre']['color'] ?? '') === '#76B043');
    chk('cards: …and a name, on the programme (' . (string)($d['program']['program'] ?? '') . ')',
        (string)($c['firstName'] ?? '') !== '' && (string)($d['program']['program'] ?? '') === 'LCASP');
    // Allocation is sticky — a second read must not re-serial.
    $d2 = backend_dispatch('admin.cards.data', ['requesterId' => 'NGG-2025-0099', 'studentId' => 'STU-CARD-IJ']);
    chk('cards: the serial is sticky — a second read does not re-allocate',
        (string)($d2['cards'][0]['displayId'] ?? 'x') === (string)($c['displayId'] ?? 'y'));
    /* Taken away again: a fixture that outlives its check becomes somebody
       else's surprise, which is how this check came to be about whichever
       student happened to sort first. */
    db_exec("DELETE FROM summer_students WHERE studentId = 'STU-CARD-IJ'");
})();
chk('cards: gate context serves centre options for the centre field', (function () {
    $g = backend_dispatch('admin.gates.create', ['requesterId' => 'NGG-2025-0099', 'kind' => 'register', 'generate' => true, 'name' => 'Card desk']);
    $ctx = backend_dispatch('gate.context', ['gate' => $g['gateId']]);
    foreach ($ctx['form']['fields'] as $f) if ($f['key'] === 'centre') return ($f['options'] ?? []) === ['Ijaiye'];
    return true; // no centre field in the form — acceptable
})());

/* ═══════════════════════════════════════════════════════════════════════════
   Summer School vs NGG centres — WHO OWNS WHAT
   ═══════════════════════════════════════════════════════════════════════════

   A centre is a PLACE and it belongs to NGG the organisation: an NGG member is
   posted to one all year round, `members.centre` points at its name, and
   `centres.code` is the printed ID prefix and band colour on that member's
   card. The whole directory used to gate on the `summer` capability, so:

     · a Summer School coordinator could rename or delete the centre every NGG
       member's record and printed card depended on, and
     · a year-round member administrator (`people`, no `summer`) could not add
       a centre at all.

   READ is open to both desks — each needs the list to do its job. WRITE is
   `people`. What a coordinator owns instead is their own structure: the
   EDITION and its GROUPS, below.
*/
$SUMONLY = 'NGG-2025-0700';   // summer_admin — caps: ['summer']
db_insert('members', ['memberId' => 'NGG-2025-0730', 'fullName' => 'Pam People', 'email' => 'people-only@example.com',
    'type' => 'NGG', 'status' => 'active', 'role' => 'editor', 'capsExtra' => '["people","inbox"]', 'centre' => 'Egbeda', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
/* An editor granted people + inbox: content, people, inbox and nothing else —
   what the admin role was before it gained club and summer. These checks are
   about a people-only desk, so they keep one. */
$PEOPLEONLY = 'NGG-2025-0730';

chk('centres: the Summer School desk can READ the directory', (function () use ($SUMONLY) {
    $l = backend_dispatch('admin.centres.list', ['requesterId' => $SUMONLY]);
    return !empty($l['ok']) && is_array($l['centres']);
})());
chk('…and is told it may not write it', (function () use ($SUMONLY) {
    return backend_dispatch('admin.centres.list', ['requesterId' => $SUMONLY])['canWrite'] === false;
})());
chk('centres: the Summer School desk CANNOT create one', (function () use ($SUMONLY) {
    $r = backend_dispatch('admin.centres.upsert', ['requesterId' => $SUMONLY, 'data' => ['name' => 'Coordinator Centre', 'code' => 'CCX', 'color' => '#123456']]);
    return ($r['error'] ?? '') === 'forbidden' && ($r['detail'] ?? '') === 'missing_cap:people';
})());
chk('centres: …nor delete one', (function () use ($SUMONLY) {
    return backend_dispatch('admin.centres.delete', ['requesterId' => $SUMONLY, 'centreId' => 'CTR-NOPE'])['error'] === 'forbidden';
})());
chk('centres: the member desk CAN, without holding the summer cap', (function () use ($PEOPLEONLY) {
    $r = backend_dispatch('admin.centres.upsert', ['requesterId' => $PEOPLEONLY, 'data' => ['name' => 'Member Desk Centre', 'code' => 'MDC', 'color' => '#123456']]);
    return !empty($r['ok']) && backend_dispatch('admin.centres.list', ['requesterId' => $PEOPLEONLY])['canWrite'] === true;
})());
chk('centres: the row reports the two programmes separately', (function () {
    $l = backend_dispatch('admin.centres.list', ['requesterId' => 'NGG-2025-0099']);
    foreach ($l['centres'] as $c) {
        if ((string)$c['code'] !== 'IJ') continue;
        // Ijaiye carries the verified summer students seeded above AND is the
        // centre of no NGG member, so the two numbers must differ in kind
        // rather than being one figure read two ways.
        return array_key_exists('summerEnrolled', $c) && array_key_exists('members', $c)
            && $c['enrolled'] === $c['summerEnrolled'];
    }
    return false;
})());

/* Deleting a centre used to be an unconditional DELETE on a row that member
   records point at BY NAME, that summer participants point at by name, that
   summer groups point at by id, and whose code is already printed on physical
   cards. Nothing broke loudly — the records simply started pointing at a
