// ── Cloudinary: a backup account takes over when the main one runs low ──
(function () {
    $keep = $GLOBALS['CONFIG']['cloudinary'] ?? []; $keepP = $GLOBALS['CLOUDINARY_PRIMARY'] ?? null; unset($GLOBALS['CLOUDINARY_PRIMARY']);
    $GLOBALS['CONFIG']['cloudinary'] = ['cloud_name' => 'mainacct', 'api_key' => '111', 'api_secret' => 'mainsecret', 'folder' => 'ngg', 'unsigned_preset' => 'main_preset'];
    setting_set('cloudinary_active', 'primary', 'system'); setting_set('cloudinary_pin', '', 'system'); setting_set('media.usage', null, 'system');
    cloudinary_account_apply();
    $use = ['mainacct' => 95, 'spareacct' => 10];
    $GLOBALS['__media_api_mock'] = function ($m, $path) use (&$use) { $c = $GLOBALS['CONFIG']['cloudinary']['cloud_name']; return ['code' => 200, 'body' => ['credits' => ['usage' => $use[$c], 'limit' => 100]]]; };
    $r = media_usage_refresh(true);
    chk('cloudinary: with no backup set, a spent main account stays put (nothing to move to)', cloudinary_active() === 'primary' && $r['level'] === 'critical');
    $GLOBALS['CLOUDINARY_PRIMARY']['backup'] = ['cloud_name' => 'spareacct', 'api_key' => '222', 'api_secret' => 'sparesecret'];
    $GLOBALS['__mail_sink'] = [];
    $r = media_usage_refresh(true);
    chk('cloudinary: past the line on the main account, the backup takes over', cloudinary_active() === 'backup' && $GLOBALS['CONFIG']['cloudinary']['cloud_name'] === 'spareacct' && $GLOBALS['CONFIG']['cloudinary']['api_secret'] === 'sparesecret');
    chk('…the usage shown is the backup\'s, and AI edits run again', ($r['account'] ?? '') === 'backup' && (int)round((float)$r['pct']) === 10 && cloudinary_credits_ok());
    chk('…the folder and other settings carry over', ($GLOBALS['CONFIG']['cloudinary']['folder'] ?? '') === 'ngg');
    chk('…but never the main account\'s upload preset (it does not exist on the backup)', ($GLOBALS['CONFIG']['cloudinary']['unsigned_preset'] ?? 'x') === '');
    chk('…and the people who run it are told', count(array_filter($GLOBALS['__mail_sink'], fn($m) => strpos($m['subject'], 'backup account') !== false)) >= 1);
    chk('…recorded in the audit log', (bool)db_row("SELECT 1 FROM audit_log WHERE event = 'media.storage.switch' LIMIT 1"));
    service_keys_apply(true);
    chk('cloudinary: re-applying the API keys keeps the backup live (no silent swap back)', $GLOBALS['CONFIG']['cloudinary']['cloud_name'] === 'spareacct');
    $seen = cloudinary_with_account('primary', fn() => $GLOBALS['CONFIG']['cloudinary']['cloud_name']);
    chk('cloudinary: a probe of the main account restores the backup after', $seen === 'mainacct' && $GLOBALS['CONFIG']['cloudinary']['cloud_name'] === 'spareacct');
    $use['mainacct'] = 95;
    media_usage_refresh(true);
    chk('cloudinary: while the main account is still spent, the backup stays', cloudinary_active() === 'backup');
    $use['mainacct'] = 3;
    media_usage_refresh(true);
    chk('cloudinary: when the main account renews, work goes back to it', cloudinary_active() === 'primary' && $GLOBALS['CONFIG']['cloudinary']['cloud_name'] === 'mainacct' && $GLOBALS['CONFIG']['cloudinary']['unsigned_preset'] === 'main_preset');
    $use['mainacct'] = 75;
    media_usage_refresh(true);
    chk('cloudinary: the backup takes over from 70% used, before the main account is nearly spent', cloudinary_active() === 'backup');
    $use['mainacct'] = 3;
    media_usage_refresh(true);
    chk('…and hands back once the main account is under 70% again', cloudinary_active() === 'primary');
    $adm = db_row("SELECT memberId FROM members WHERE role = 'super_admin' AND status = 'active' LIMIT 1");
    $pick = fn($u2) => admin_media_account(['requesterId' => (string)($adm['memberId'] ?? ''), 'use' => $u2]);
    $r = $pick('backup');
    chk('cloudinary: an operator can send new uploads to the backup now', !empty($r['ok']) && $r['uploadsTo'] === 'backup' && $GLOBALS['CONFIG']['cloudinary']['cloud_name'] === 'spareacct');
    media_usage_refresh(true);
    chk('…and the choice holds: a healthy main account does not pull it back', cloudinary_active() === 'backup');
    $r = $pick('primary'); $use['mainacct'] = 75; media_usage_refresh(true);
    chk('cloudinary: a chosen main account stays in use past 70% (the operator decides)', cloudinary_active() === 'primary');
    $use['mainacct'] = 97; media_usage_refresh(true);
    chk('…but a full one is still skipped, so a choice can never stop uploads', cloudinary_active() === 'backup');
    $r = $pick('auto');
    chk('cloudinary: back to automatic clears the choice', !empty($r['ok']) && $r['pin'] === '' && cloudinary_active() === 'backup');
    chk('cloudinary: choosing an account needs the settings capability', (admin_media_account(['requesterId' => 'NGG-NOBODY', 'use' => 'backup'])['ok'] ?? true) === false);
    chk('cloudinary: an account that is not set up cannot be chosen', ($pick('nope')['error'] ?? '') === 'not_found');
    $use['mainacct'] = 3; media_usage_refresh(true);
    // An upload the main account refuses moves to the backup at once and is retried there.
    $tries = [];
    $GLOBALS['__cloudinary_upload_mock'] = null; unset($GLOBALS['__cloudinary_upload_mock']);
    $names = [];
    $GLOBALS['__cld_upload_http'] = function ($named = []) use (&$tries, &$names) { $names[] = $named['public_id'] ?? ''; if ($named) chk('cloudinary: a copy never overwrites (the existing one is returned)', ($named['overwrite'] ?? '') === 'false'); $c = $GLOBALS['CONFIG']['cloudinary']['cloud_name']; $tries[] = $c; return $c === 'mainacct' ? [420, ['error' => ['message' => 'Monthly credit limit reached']]] : [200, ['secure_url' => 'https://res.cloudinary.com/spareacct/image/upload/v1/ngg/photos/x.jpg']]; };
    $up = cloudinary_upload_signed('https://example.com/a.jpg');
    chk('cloudinary: an upload refused for credits switches to the backup and is retried once there', !empty($up['ok']) && $tries === ['mainacct', 'spareacct'] && cloudinary_active() === 'backup');
    $ad = cloudinary_adopt('https://res.cloudinary.com/mainacct/image/upload/c_fill,w_400/v1/ngg/photos/old.jpg');
    chk('cloudinary: on the backup, a photo still on the spent account is copied across before editing', !empty($ad['adopted']) && strpos((string)$ad['url'], 'spareacct') !== false && end($tries) === 'spareacct');
    $ad2 = cloudinary_adopt('https://res.cloudinary.com/spareacct/image/upload/v1/ngg/photos/x.jpg');
    chk('…and one already on the backup is edited where it is', empty($ad2['adopted']));
    cloudinary_adopt('https://res.cloudinary.com/mainacct/image/upload/e_sharpen/v1/ngg/photos/old.jpg');
    $copies = array_values(array_filter($names));
    chk('cloudinary: editing the same old photo again reuses its one copy (same fixed name), never a second', count($copies) === 2 && $copies[0] === $copies[1] && strpos($copies[0], 'copy_') === 0);
    // An account far past its plan (Cloudinary reports 202%) is full, and so is one Cloudinary has stopped.
    setting_set('cloudinary_pin', '', 'system');
    $use['mainacct'] = 202; media_usage_refresh(true);
    chk('cloudinary: a main account reported at 202% is full, and uploads go to the backup', (media_usage_state('primary')['level'] ?? '') === 'critical' && cloudinary_active() === 'backup');
    $GLOBALS['__media_api_mock'] = function ($m, $path) use (&$use) { $c = $GLOBALS['CONFIG']['cloudinary']['cloud_name'];
        return $c === 'mainacct' ? ['code' => 403, 'body' => ['error' => ['message' => 'Account is disabled due to exceeding the plan limits']]] : ['code' => 200, 'body' => ['credits' => ['usage' => $use[$c], 'limit' => 100]]]; };
    media_state_put('primary', ['level' => 'ok', 'pct' => 10.0, 'checkedAt' => gmdate('c', time() - 86400)] + media_usage_state('primary'));
    media_usage_refresh(true);
    chk('cloudinary: an account Cloudinary has stopped ("disabled… plan limits") counts as full, not "keep the last reading"', (media_usage_state('primary')['level'] ?? '') === 'critical' && cloudinary_active() === 'backup');
    // Photos already on the spent account are moved, once each.
    $pm = db_row("SELECT memberId, photoUrl FROM members ORDER BY id LIMIT 1");
    $oldUrl = 'https://res.cloudinary.com/mainacct/image/upload/c_fill,w_400/v1/ngg/photos/m1.jpg';
    db_exec('UPDATE members SET photoUrl = ? WHERE memberId = ?', [$oldUrl, $pm['memberId']]);
    $adm2 = (string)(db_row("SELECT memberId FROM members WHERE role = 'super_admin' AND status = 'active' LIMIT 1")['memberId'] ?? '');
    $moved = [];
    $GLOBALS['__cld_upload_http'] = function ($named = []) use (&$moved) { $moved[] = $named['public_id'] ?? ''; return [200, ['secure_url' => 'https://res.cloudinary.com/spareacct/image/upload/v1/ngg/photos/' . ($named['public_id'] ?? 'x') . '.jpg']]; };
    $sub = [['type' => 'member', 'id' => (string)$pm['memberId']]];
    chk('cloudinary: photos are never moved in bulk: a request must name the people whose photos are needed', (admin_photos_relocate(['requesterId' => $adm2])['error'] ?? '') === 'missing_field' && !$moved);
    chk('…and at most a print run\'s worth at once', (admin_photos_relocate(['requesterId' => $adm2, 'subjects' => array_fill(0, PHOTO_RELOCATE_MAX + 1, $sub[0])])['error'] ?? '') === 'too_many');
    $r = admin_photos_relocate(['requesterId' => $adm2, 'subjects' => $sub]);
    $now = (string)db_row('SELECT photoUrl FROM members WHERE memberId = ?', [$pm['memberId']])['photoUrl'];
    chk('cloudinary: a named photo on the spent account is copied to the account in use, and the record points at the copy', count($r['moved']) === 1 && strpos($now, 'https://res.cloudinary.com/spareacct/') === 0 && $r['moved'][0]['url'] === $now);
    chk('…under a fixed name with overwrite off, so asking again never stores it twice', strpos((string)($moved[0] ?? ''), 'moved_') === 0);
    $r2 = admin_photos_relocate(['requesterId' => $adm2, 'subjects' => $sub]);
    chk('…and once moved, asking again copies nothing (it is no longer on the spent account)', !$r2['moved'] && $r2['kept'] === 1 && count($moved) === 1);
    chk('cloudinary: copying a photo needs the permission that prints that card', (admin_photos_relocate(['requesterId' => 'NGG-NOBODY', 'subjects' => $sub])['ok'] ?? true) === false);
    db_exec('UPDATE members SET photoUrl = ? WHERE memberId = ?', [(string)$pm['photoUrl'], $pm['memberId']]);
    unset($GLOBALS['__cld_upload_http'], $GLOBALS['__media_api_mock'], $GLOBALS['__mail_sink'], $GLOBALS['CLOUDINARY_PRIMARY'], $GLOBALS['__media_active'], $GLOBALS['__media_states']); setting_set('media.usage.accounts', null, 'system');
    setting_set('cloudinary_active', 'primary', 'system'); setting_set('cloudinary_pin', '', 'system'); setting_set('media.usage', null, 'system'); setting_set('cloudinary_credits', 'ok', 'system');
    $GLOBALS['CONFIG']['cloudinary'] = $keep; if ($keepP !== null) $GLOBALS['CLOUDINARY_PRIMARY'] = $keepP;
})();

