})());

chk('a thread keeps its turns in order, and carries them into the next question', (function () {
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = __ichat_mock();
    $a = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099', 'question' => 'Why is Wednesday weak?']);
    if (empty($a['ok'])) { unset($GLOBALS['__ai_mock']); return true; }
    $sawHistory = false;
    $GLOBALS['__ai_mock'] = function ($profile, $system, $turns) use (&$sawHistory) {
        // "And Saturday?" only resolves if the earlier turn travelled with it.
        if (strpos(json_encode($turns), 'earlier_in_this_conversation') !== false) $sawHistory = true;
        return (__ichat_mock())($profile, $system, $turns);
    };
    $b = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099',
        'question' => 'And what about Saturday?', 'threadId' => $a['threadId']]);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    $t = backend_dispatch('analytics.insight.thread', ['requesterId' => 'NGG-2025-0099', 'threadId' => $a['threadId']]);
    $turns2 = $t['thread']['turns'] ?? [];
    return !empty($b['ok']) && $sawHistory && count($turns2) === 2
        && $turns2[0]['seq'] === 1 && $turns2[1]['seq'] === 2
        && $turns2[0]['question'] !== $turns2[1]['question'];
})());
chk('…and a thread is only readable by the admin who opened it', (function () {
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = __ichat_mock();
    $a = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099', 'question' => 'Why is Wednesday weak?']);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    if (empty($a['ok'])) return true;
    $other = backend_dispatch('analytics.insight.thread', ['requesterId' => 'NGG-2025-0098', 'threadId' => $a['threadId']]);
    // Either the other admin is not an admin at all, or the thread is not theirs.
    return empty($other['ok']);
})());
chk('the ask op is admin-gated', backend_dispatch('analytics.insight.ask', ['requesterId' => '', 'question' => 'Why is Wednesday weak?'])['ok'] !== true);

chk('the evidence actually HOLDS the centres — the key it read never existed', (function () {
    /* The reported bug, at its root. insight.php read $d['centres']; Level 6
       emits $d['perCentre']. The loop iterated nothing, $ev['centres'] was
       always [], and so the analyst's "this evidence does not hold
       centre-specific data" was TRUE — while the page above it showed a table
       of five sites. Both sides looked right in isolation and nothing asserted
       that one side's key was the other's. */
    $ev = insight_evidence(['requesterId' => 'NGG-2025-0099']);
    if (!empty($ev['empty'])) return true;
    $c = (array)($ev['centres'] ?? []);
    if (!$c) return false;
    $first = $c[0];
    return (string)($first['centre'] ?? '') !== ''
        // Flattened, not nested: a model reading {"ci":{"rate":47}} does
        // arithmetic on the wrapper as often as on the number.
        && array_key_exists('rate', $first) && is_array($first['ci'] ?? null)
        // …and the detail that lets a centre question be answered rather than
        // merely acknowledged.
        && array_key_exists('enrolled', $first) && array_key_exists('bySex', $first)
        && array_key_exists('avgGrade', $first) && array_key_exists('evidenceItems', $first);
})());

chk('what the evidence can answer is generated from the evidence, not written beside it', (function () {
    /* The reported bug. The router was told, in a hand-written sentence, that
       the evidence held "centre readiness" — vague enough that asked about one
       site it replied "the evidence does not hold centre-specific data", which
       was false: per-centre rates, intervals and verdicts were right there.
       A description of a payload that lives anywhere except in the payload
       drifts, and this one had. */
    $ev = insight_evidence(['requesterId' => 'NGG-2025-0099']);
    if (!empty($ev['empty'])) return true;
    $cap = ichat_capabilities(ichat_shape($ev));
    /* The payload must actually CONTAIN centres. It did not: insight.php read
       $d['centres'] and depth emits $d['perCentre'], so this array was empty in
       production and the analyst's "no centre-specific data" was true. */
    $names = array_map(fn($c) => (string)$c['centre'], (array)($ev['centres'] ?? []));
    if (!$names) return false;
    // Every centre in the payload is NAMED in the description. A model that
    // cannot see the names assumes there are none.
    foreach (array_slice($names, 0, 12) as $n) if (strpos($cap, $n) === false) return false;
    return strpos($cap, 'per-centre figures') !== false
        // …and it still states the real boundary rather than dropping it.
        && strpos($cap, 'NO money') !== false;
})());

chk('…and the ROUTER is told it, which is where the wrong refusal came from', (function () {
    /* Asserting on ichat_capabilities() alone would have passed while the
       router prompt still carried the stale hand-written sentence — which is
       exactly the bug. So this captures the system prompt the router is
       actually sent. */
    $sysSeen = '';
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = function ($profile, $sys, $turns) use (&$sysSeen) {
        if ($profile === ICHAT_ROUTER_PROFILE) $sysSeen = $sys;
        return (__ichat_mock())($profile, $sys, $turns);
    };
    backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099',
        'question' => 'Which centre is furthest behind and why?']);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    if ($sysSeen === '') return true;                        // AI off on this run
    $ev = insight_evidence(['requesterId' => 'NGG-2025-0099']);
    $names = array_map(fn($c) => (string)$c['centre'], (array)($ev['centres'] ?? []));
    if (!$names) return false;   // the payload must HAVE centres; see insight.php
    return strpos($sysSeen, 'THE EVIDENCE HOLDS') !== false
        && strpos($sysSeen, $names[0]) !== false
        // The sentence that produced "the evidence does not hold centre-specific
        // data" is gone, not merely supplemented.
        && strpos($sysSeen, 'centre readiness') === false;
})());

chk('…and it names each block only while that block is actually present', (function () {
    /* The drift guard. Adding learning-by-sex to the payload must make the
       description mention it with nobody editing a string; removing a block
       must make it stop. */
    $withLearning = ichat_capabilities(['centres' => [], 'range' => ['label' => 'W1'],
        'hasLearningBySex' => true, 'segmentRows' => ['Female', 'Male']]);
    $without = ichat_capabilities(['centres' => [], 'range' => ['label' => 'W1'], 'segmentRows' => []]);
    return strpos($withLearning, 'grade') !== false && strpos($withLearning, 'Female and Male') !== false
        && strpos($without, 'grade') === false
        && strpos($without, 'nothing yet') !== false;
})());

chk('a refusal says what the evidence DOES hold, and names the scope that narrowed it', (function () {
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = __ichat_mock(['route' => ['lenses' => ['mechanism'], 'why' => 'w',
        'answerable' => false, 'unanswerable_because' => 'No budget data is held.', 'restated' => 'r']]);
    $r = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099',
        'centre' => 'Ijaiye', 'question' => 'How much did the transport cost last month?']);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    if (empty($r['ok'])) return true;
    $a = (string)($r['turn']['answer'] ?? '');
    /* "This evidence cannot answer that" and nothing else sends a coordinator
       away to guess at a phrasing — and the commonest cause is not the question
       but the pane being scoped to one centre. */
    return $r['turn']['status'] === 'unanswerable'
        && strpos($a, 'No budget data is held.') === 0
        && strpos($a, 'Ijaiye') !== false && strpos($a, 'remove that chip') !== false
        && strpos($a, 'THE EVIDENCE HOLDS') !== false;
})());

/* ── Who is LEAVING, as opposed to how much attendance there was ─────────────
 * The evidence held rates and nothing else, so the panel could describe the
 * AMOUNT of attendance and never that children were leaving. Those are
 * different questions with opposite answers: a cohort where everyone comes
 * three days a week and one where a third have stopped entirely both report
 * 62%, and only one is an emergency. Asked "is anyone slipping away", there was
 * no figure to reach for and the honest answer was "the evidence cannot tell" —
 * which was true, and was the bug.
 *
 * These enable a calendar of their own. The suite runs this section with the
 * programme calendar off, and the attrition figure needs open days to count
 * against — the first version of these tests short-circuited on that and passed
 * against every mutation. */
(function () {
    $keep = setting_get('programme');
    $span = db_row("SELECT MIN(date) a FROM attendance");
    programme_settings_save(['enabled' => true, 'startDate' => (string)($span['a'] ?? '2026-06-01'),
        'endDate' => attendance_today(), 'weekdays' => [1, 2, 3, 4, 5, 6, 7],
        'holidays' => [], 'extraDays' => []], 'test');

    chk('the analyst can see who is LEAVING, not only how much attendance there was', (function () {
        $ev = insight_evidence(['requesterId' => 'NGG-2025-0099']);
        if (!empty($ev['empty'])) return false;
        $A = $ev['attrition'] ?? null;
        if (!is_array($A) || !$A) return false;
        foreach (['stoppedRun', 'openDays', 'children', 'stopped', 'neverCame', 'stoppedPct', 'byCentre'] as $k) {
            if (!array_key_exists($k, $A)) return false;
        }
        /* The SAME threshold the register uses, so "9 have stopped" on the
         * dashboard and nine quoted by the analyst are the same nine children.
         * Two figures for one idea is how a board paper contradicts the screen
         * it was written from. */
        if ((int)$A['stoppedRun'] !== ATT_STOPPED_RUN) return false;
        // Counts only. No child's name, id or contact may be anywhere in it.
        if (preg_match('/(SUM-|STU-|@|\+234)/', (string)json_encode($A))) return false;
        if (!count($A['byCentre'])) return false;
        foreach ($A['byCentre'] as $row) {
            if (!array_key_exists('stoppedPct', $row) || !array_key_exists('children', $row)) return false;
            if ($row['stopped'] > $row['children']) return false;
        }
        return $A['stopped'] + $A['neverCame'] <= $A['children'] && $A['openDays'] > 0;
    })());

    chk('…and the ROUTER is told it holds that, so the question is not refused', (function () {
        /* Same failure mode as the centres: a capability the payload has and the
         * router has never heard of is a question answered "no". Captures the
         * prompt actually sent rather than asserting on the helper alone. */
        $sysSeen = '';
        $cfg = __ichat_config_on();
        $GLOBALS['__ai_mock'] = function ($profile, $sys, $turns) use (&$sysSeen) {
            if ($profile === ICHAT_ROUTER_PROFILE) $sysSeen = $sys;
            return (__ichat_mock())($profile, $sys, $turns);
        };
        backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099',
            'question' => 'Is anyone slipping away from the programme?']);
        unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
        if ($sysSeen === '') return false;
        $ev = insight_evidence(['requesterId' => 'NGG-2025-0099']);
        if (empty($ev['attrition'])) return false;
        // Generated from the payload, so removing the block removes the sentence.
        $with = ichat_capabilities(ichat_shape($ev));
        $without = ichat_capabilities(ichat_shape(array_diff_key($ev, ['attrition' => 1])));
        return strpos($sysSeen, 'STOPPED coming') !== false
            && strpos($with, 'STOPPED coming') !== false
            && strpos($without, 'STOPPED coming') === false;
    })());

    if (is_array($keep)) setting_set('programme', $keep, 'test');
    else programme_settings_save(['enabled' => false, 'startDate' => '', 'endDate' => '',
        'weekdays' => [1, 2, 3, 4, 5], 'holidays' => [], 'extraDays' => []], 'test');
})();

/* ── One definition of "has stopped coming", on every surface ─────────────────
 *
 * The register learned to tell a child who attends badly from one who has left.
 * The analyst's evidence learned it next. The two remaining places that report a
 * rate — the PUBLIC board at /s-status and the analytics workspace a funder
 * report is written from — could not, and a rate is the one figure that hides
 * this: a child who leaves stops being counted absent and simply drops out of
 * the numerator AND the denominator, so quitting nudges the rate UP. A board
 * reading "82% attendance" while a third of the children have gone is not
 * wrong about the 82%; it is silent about the third.
 *
 * The hazard these guard is not "is the figure there" but "is it the SAME
 * figure". Three surfaces each computing "who has stopped" their own way is how
 * a board paper ends up contradicting the screen it was written from, so there
 * is one function — `attendance_retention()` — and these pin every caller to it.
 *
 * A calendar of their own, as above: this section runs with the programme
 * calendar off, and there is nothing to measure against without open days. */
(function () use ($SUR) {
    $keep = setting_get('programme');
    $span = db_row("SELECT MIN(date) a FROM attendance");
    programme_settings_save(['enabled' => true, 'startDate' => (string)($span['a'] ?? '2026-06-01'),
        'endDate' => attendance_today(), 'weekdays' => [1, 2, 3, 4, 5, 6, 7],
        'holidays' => [], 'extraDays' => []], 'test');

    // Two centres of our own, so the figures asserted on are ours rather than
    // whatever the rest of the suite happens to have left in the roster.
    backend_dispatch('admin.centres.upsert', ['requesterId' => $SUR, 'data' => ['name' => 'Retentionville A', 'code' => 'RVA', 'color' => '#2f9e44', 'capacity' => 40]]);
    backend_dispatch('admin.centres.upsert', ['requesterId' => $SUR, 'data' => ['name' => 'Retentionville B', 'code' => 'RVB', 'color' => '#3b5bdb', 'capacity' => 40]]);
    $days = programme_days_elapsed();
    $c = summer_ensure_cohort(); $cid = (string)$c['cohortId'];
    /* A1 came at the start and stopped. A2 comes every open day. A3 never came.
       B1 stopped, at the OTHER centre — that one child is what makes the centre
       allow-list assertions below capable of failing. */
    $ppl = ['RET-A1' => 'Retentionville A', 'RET-A2' => 'Retentionville A',
            'RET-A3' => 'Retentionville A', 'RET-B1' => 'Retentionville B'];
    foreach ($ppl as $id => $centre) {
        db_exec('DELETE FROM attendance WHERE studentId = ?', [$id]);
        db_exec('DELETE FROM summer_students WHERE studentId = ?', [$id]);
        db_insert('summer_students', ['studentId' => $id, 'cohortId' => $cid, 'fullName' => 'Retention ' . $id,
            'handle' => strtolower($id), 'track' => 'Tech', 'centre' => $centre, 'status' => 'active',
            'regStatus' => 'verified']);
    }
    $mark = function (string $id, string $d) use ($cid, $SUR) {
        db_insert('attendance', ['cohortId' => $cid, 'studentId' => $id, 'token' => '', 'date' => $d,
            'checkInAt' => $d . 'T08:00:00Z', 'method' => 'qr', 'byId' => $SUR, 'device' => '',
            'status' => 'present', 'lateMinutes' => 0, 'redline' => 0, 'halfDay' => 0, 'createdAt' => now_iso()]);
    };
    $enoughDays = count($days) >= ATT_STOPPED_RUN + 2;
    if ($enoughDays) {
        foreach (array_slice($days, 0, 2) as $d) { $mark('RET-A1', $d); $mark('RET-B1', $d); }
        foreach ($days as $d) $mark('RET-A2', $d);
    }

    chk('retention: the term-long figure is scoped to the centres asked for', (function () use ($enoughDays) {
        if (!$enoughDays) return false;                      // the fixture must be measurable
        $all = attendance_retention();
        $justA = attendance_retention(['Retentionville A']);
        if (!$all || !$justA) return false;
        $rowOf = function (array $r, string $name) {
            foreach ($r['byCentre'] as $x) if ($x['centre'] === $name) return $x;
            return null;
        };
        $a = $rowOf($all, 'Retentionville A'); $b = $rowOf($all, 'Retentionville B');
        if (!$a || !$b) return false;
        // Unscoped: both centres, and each child landed in the right bucket.
        if ($a['children'] !== 3 || $a['stopped'] !== 1 || $a['neverCame'] !== 1 || $a['stillComing'] !== 1) return false;
        if ($b['children'] !== 1 || $b['stopped'] !== 1) return false;
        /* Scoped: B's leaver must be GONE, not merely un-listed. Dropping the
           allow-list from either the roster query or the attendance queries
           leaves this asserting on a number that changed. */
        if (count($justA['byCentre']) !== 1) return false;
        if ($justA['children'] !== 3 || $justA['stopped'] !== 1) return false;
        if ($justA['stopped'] === $all['stopped']) return false;   // the filter did something
        // The parts add up to the whole, on both.
        return $justA['stopped'] + $justA['neverCame'] + $justA['stillComing'] === $justA['children']
            && $all['stoppedRun'] === ATT_STOPPED_RUN;
    })());

    chk('s-status: the public board reports who has LEFT, not only who came today', (function () {
        $st = public_status([])['status'];
        $R = $st['retention'] ?? null;
        if (!is_array($R) || !$R) return false;
        foreach (['stoppedRun', 'openDays', 'from', 'to', 'children', 'stopped', 'neverCame', 'stillComing', 'stoppedPct', 'byCentre'] as $k) {
            if (!array_key_exists($k, $R)) return false;
        }
        /* THE POINT. Not "the board has a retention figure" but "the board's
           figure is the register's figure". A second definition here would let
           the public page and the coordinator's screen disagree about the same
           children, in public. */
        if ((int)$R['stoppedRun'] !== ATT_STOPPED_RUN) return false;
        $mine = attendance_retention();
        if ($R['stopped'] !== $mine['stopped'] || $R['children'] !== $mine['children']
            || $R['neverCame'] !== $mine['neverCame']) return false;
        if ($R['stopped'] < 2) return false;                 // our two leavers are in it
        // Counts only. This is an unauthenticated page: not one child in it.
        if (preg_match('/(RET-A|RET-B|Retention RET|@|\+234)/', (string)json_encode($R))) return false;
        // …and the per-centre rows carry it too, beside today's rate.
        $seen = false;
        foreach ($st['byCentre'] as $row) {
            if (!array_key_exists('stopped', $row) || !array_key_exists('stillComing', $row)
                || !array_key_exists('neverCame', $row) || !array_key_exists('stoppedPct', $row)) return false;
            if ($row['name'] === 'Retentionville A' && $row['stopped'] === 1 && $row['neverCame'] === 1) $seen = true;
        }
        return $seen;
    })());

    chk('s-status: a board published for one centre does not show another centre\'s losses', (function () {
        $keepPages = setting_raw('status_pages');
        $set = fn(array $centres) => backend_dispatch('admin.status.pages.set', ['requesterId' => 'NGG-2025-0002',
            'data' => ['attendance' => ['published' => true, 'centres' => $centres]]]);
        $set(['Retentionville A']);
        $one = public_status([])['status']['retention'] ?? [];
        $set([]);
        $all = public_status([])['status']['retention'] ?? [];
        if ($keepPages === null) db_exec("DELETE FROM settings WHERE settingKey = 'status_pages'");
        else setting_set('status_pages', safe_json((string)$keepPages), 'test');
        if (!$one || !$all) return false;
        /* B's leaver appears on the unrestricted board and not on A's. Passing
           the allow-list through is the whole assertion: drop it and `$one`
           becomes `$all` and these stop differing. */
        return $one['children'] === 3 && $one['stopped'] === 1
            && count($one['byCentre']) === 1 && $one['byCentre'][0]['centre'] === 'Retentionville A'
            && $all['stopped'] > $one['stopped'] && count($all['byCentre']) > 1;
    })());

    chk('analytics workspace: retention travels with the rate a funder report quotes', (function () {
        $ws = backend_dispatch('analytics.workspace', ['requesterId' => 'NGG-2025-0099'])['workspace'] ?? [];
        $R = $ws['research']['retention'] ?? null;
        if (!is_array($R) || !$R) return false;
        if ((int)$R['stoppedRun'] !== ATT_STOPPED_RUN) return false;
        /* Same figure as the register and the public board, not a third one.
           Compared per centre rather than on the totals, because the workspace
           is scoped to the centres this admin may see while the register's own
           call is not — the totals legitimately differ, and asserting on them
           would only be asserting that this admin can see everything. */
        $rowOf = function (array $r, string $name) {
            foreach ($r['byCentre'] as $x) if ($x['centre'] === $name) return $x;
            return null;
        };
        $mineA = $rowOf(attendance_retention(), 'Retentionville A');
        $wsA = $rowOf($R, 'Retentionville A');
        if (!$mineA || !$wsA || $mineA !== $wsA) return false;
        // Internally consistent: the total is the sum of the centres it lists.
        $sum = 0; foreach ($R['byCentre'] as $x) $sum += (int)$x['children'];
        if ($sum !== (int)$R['children']) return false;
        /* The window is the TERM, never the workspace's date range. Asked of a
           one-day filter, "has stopped coming" would call everyone who missed
           that day a leaver. */
        $wk = backend_dispatch('analytics.workspace', ['requesterId' => 'NGG-2025-0099', 'day' => attendance_today()])['workspace'] ?? [];
        $W = $wk['research']['retention'] ?? null;
        if (($wk['filters']['rangeLabel'] ?? '') === ($ws['filters']['rangeLabel'] ?? '')) return false;  // the filter took
        if (!is_array($W) || ($W['from'] ?? '') !== $R['from'] || ($W['openDays'] ?? 0) !== $R['openDays']) return false;
        // …and it is on the centre rows, so a site above the watch line that is
        // still losing children is visible in the row rather than only in total.
        $seen = false;
        foreach ($ws['research']['centreComparison'] as $row) {
            if (!array_key_exists('stopped', $row) || !array_key_exists('stillComing', $row)
                || !array_key_exists('stoppedPct', $row)) return false;
            if ($row['name'] === 'Retentionville A' && $row['stopped'] === 1 && $row['stillComing'] === 1) $seen = true;
        }
        return $seen;
    })());

    chk('retention says "cannot tell yet" rather than "nobody has left"', (function () {
        /* The dangerous failure is not an error, it is a reassuring zero. With no
           programme calendar there are no open days to count a run of absences
           against, and the honest answer is that the question cannot be answered
           — which the callers render as an absent panel, not as 0%.
           Asserted on the EMPTINESS, because `stopped => 0` would sail through a
           test that only checked the key existed. */
        $keepInner = setting_get('programme');
        programme_settings_save(['enabled' => false, 'startDate' => '', 'endDate' => '',
            'weekdays' => [1, 2, 3, 4, 5], 'holidays' => [], 'extraDays' => []], 'test');
        $bare = attendance_retention();
        $board = public_status([])['status']['retention'] ?? null;
        $ws = backend_dispatch('analytics.workspace', ['requesterId' => 'NGG-2025-0099'])['workspace']['research']['retention'] ?? null;
        if (is_array($keepInner)) setting_set('programme', $keepInner, 'test');
        return $bare === [] && $board === [] && $ws === [];
    })());

    foreach (array_keys($ppl) as $id) {
        db_exec('DELETE FROM attendance WHERE studentId = ?', [$id]);
        db_exec('DELETE FROM summer_students WHERE studentId = ?', [$id]);
    }
    db_exec("DELETE FROM centres WHERE code IN ('RVA','RVB')");
    if (is_array($keep)) setting_set('programme', $keep, 'test');
    else programme_settings_save(['enabled' => false, 'startDate' => '', 'endDate' => '',
        'weekdays' => [1, 2, 3, 4, 5], 'holidays' => [], 'extraDays' => []], 'test');
})();

chk('the analysts can finally see LEARNING by sex, not only attendance', (function () {
    /* The evidence held attendance broken down every way and learning broken
       down no way at all — so the panel could say who turns up and never
       whether girls and boys learn the same amount once they do. That is the
       question serious education funding turns on. */
    $ev = insight_evidence(['requesterId' => 'NGG-2025-0099']);
    if (!empty($ev['empty'])) return true;
    $L = $ev['learning'] ?? null;
    if (!is_array($L) || !isset($L['bySex'])) return false;
    foreach ($L['bySex'] as $r) {
        // Every group carries its coverage, so "12 girls graded of 130" reads as
        // a coverage problem rather than as a finding about girls.
        if (!array_key_exists('enrolled', $r) || !array_key_exists('graded', $r)
            || !array_key_exists('avgGrade', $r) || !array_key_exists('tooThin', $r)) return false;
    }
    return true;
})());

chk('…and a group too small to carry a claim is marked, never merged away', (function () {
    $ev = insight_evidence(['requesterId' => 'NGG-2025-0099']);
    if (!empty($ev['empty'])) return true;
    $rows = $ev['learning']['bySex'] ?? [];
    $thin = array_filter($rows, fn($r) => $r['graded'] < 5);
    foreach ($thin as $r) if (empty($r['tooThin'])) return false;
    // The gap is only stated where BOTH sides are thick enough to mean anything.
    $gap = $ev['learning']['gap'] ?? null;
    if ($gap !== null) {
        $ok = true;
        foreach ($rows as $r) if (in_array($r['sex'], ['Male', 'Female'], true) && !empty($r['tooThin'])) $ok = false;
        return $ok;
    }
    return true;
})());

chk('…and it still passes the privacy gate that guards everything sent out', (function () {
    /* The block is aggregate by construction, but "by construction" is what
       every leak was before it happened. Run the real scrub over the real
       encoded payload. */
    $ev = insight_evidence(['requesterId' => 'NGG-2025-0099']);
    return insight_scrub(json_encode($ev, JSON_UNESCAPED_SLASHES) ?: '') === [];
})());

/* ── The answer as data ──────────────────────────────────────────────────────
 * Tiles, a table and a chart, not only prose. The reason this is safe to add is
 * the reason it needed adding carefully: a chart is more persuasive than a
 * paragraph, so it goes through MORE checking, not less.
 */
chk('the composer bounds the structured blocks instead of passing them through', (function () {
    /* What a model actually returns: nine columns in one row and two in the
       next, two hundred chart points, a tone nobody defined, a bar index off
       the end of the header. None of that is worth failing a turn over; all of
       it would break a renderer that trusted it. */
    $d = ichat_clean_data([
        'stats' => [['label' => 'Attendance', 'value' => '78%', 'note' => 'up 4', 'tone' => 'good'],
                    ['label' => '', 'value' => '9'],                       // no label — dropped
                    ['label' => 'Ungraded', 'value' => '266', 'tone' => 'purple'],  // bad tone
                    ['label' => 'Fourth', 'value' => '1']],                // over the cap
        'table' => ['title' => 'Centres', 'columns' => ['Centre', 'Att.', 'Δ', 'x', 'y', 'z'],
                    'bar' => 1, 'delta' => 9,
                    'rows' => [['Egbeda', '91', '+3'], ['Ayobo'], ['', '', ''], ...array_fill(0, 9, ['a', 'b', 'c'])]],
        'chart' => ['kind' => 'spiral', 'label' => 'wk', 'unit' => '%', 'watch' => 55,
                    'points' => array_merge([['x' => 'w1', 'y' => 68], ['x' => 'w2', 'y' => 'oops'],
                                             ['x' => 'w3', 'y' => 56], ['x' => 'w4', 'y' => 47]],
                                            array_fill(0, 30, ['x' => 'x', 'y' => 1]))],
    ]);
    /* Capped AFTER filtering, so one unusable entry does not cost a usable one
       — the "no label" tile is dropped and the fourth still makes the cut. */
    return count($d['stats']) === 3 && $d['stats'][1]['tone'] === 'neutral'
        && $d['stats'][2]['label'] === 'Fourth'
        && count($d['table']['columns']) === 4
        // The ragged row is PADDED to the header, not dropped — one short row
        // must not lose the whole table — and the all-empty row is dropped.
        && count($d['table']['rows']) === 6 && $d['table']['rows'][1] === ['Ayobo', '', '', '']
        && $d['table']['delta'] === -1 && $d['table']['bar'] === 1
        && $d['chart']['kind'] === 'line' && count($d['chart']['points']) === 12
        && $d['chart']['points'][1]['x'] === 'w3';      // the non-numeric y is gone
})());

chk('a two-point chart is refused — that is a number, not a trend', (function () {
    $d = ichat_clean_data(['chart' => ['kind' => 'line', 'points' => [['x' => 'a', 'y' => 1], ['x' => 'b', 'y' => 2]]]]);
    return !isset($d['chart']);
})());

chk('the structured blocks are grounded against the evidence, exactly like the prose', (function () {
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = __ichat_mock(['answer' => 'Attendance is holding.', 'claims' => [],
        'data' => ['stats' => [['label' => 'Made up', 'value' => '99999', 'tone' => 'bad']]]]);
    $r = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099',
        'question' => 'How is attendance holding up this week?']);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    if (empty($r['ok'])) return true;
    $t = $r['turn'];
    /* DROPPED, not shown with a warning on it. A table with one invented cell
       is what gets screenshotted into a board paper, and no reader maps "some
       figures are unverified" onto the third row. The drop is recorded so this
       is not hiding: the pane says a block was produced and why it is absent. */
    return empty($t['data']['stats'])
        && ($t['checks']['grounded'] ?? true) === false
        && ($t['checks']['dropped'][0]['block'] ?? '') === 'stats'
        && in_array('99999', $t['checks']['dropped'][0]['unverified'] ?? [], true);
})());

chk('…and a block whose figures ARE in the evidence survives and is stored', (function () {
    $cfg = __ichat_config_on();
    /* Built from the evidence the turn will actually be checked against, so
       this proves the check passes real data rather than that it is switched
       off. */
    $ev = insight_evidence(['requesterId' => 'NGG-2025-0099']);
    $nums = array_values(array_unique(ichat_evidence_numbers($ev)));
    if (count($nums) < 4) { __ichat_config_off($cfg); return true; }
    $GLOBALS['__ai_mock'] = __ichat_mock(['answer' => 'Steady.', 'claims' => [], 'data' => [
        'stats' => [['label' => 'Rate', 'value' => (string)$nums[0], 'tone' => 'good']],
        'chart' => ['kind' => 'line', 'label' => 'By week', 'unit' => '',
                    'points' => [['x' => 'a', 'y' => $nums[0]], ['x' => 'b', 'y' => $nums[1]], ['x' => 'c', 'y' => $nums[2]]]],
    ]]);
    $r = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099',
        'question' => 'Give me the weekly shape of attendance please.']);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    if (empty($r['ok'])) return true;
    // Re-read from the store, so this also proves dataJson round-trips.
    $back = backend_dispatch('analytics.insight.thread', ['requesterId' => 'NGG-2025-0099', 'threadId' => $r['threadId']]);
    $turns = $back['thread']['turns'] ?? [];
    $last = end($turns) ?: [];
    return count($last['data']['stats'] ?? []) === 1
        && count($last['data']['chart']['points'] ?? []) === 3
        && empty($last['checks']['dropped']);
})());
chk('a thread can be renamed, archived, and refuses a title that names somebody', (function () {
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = __ichat_mock();
    $a = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099', 'question' => 'Why is Wednesday weak?']);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    if (empty($a['ok'])) return true;
    $tid = $a['threadId'];
    /* A generated title reads identically to the other four times somebody asked
       the same thing, so a conversation nobody can name is one they re-ask —
       and every re-ask is a fresh round of model calls. */
    $ok = backend_dispatch('analytics.insight.rename', ['requesterId' => 'NGG-2025-0099', 'threadId' => $tid, 'title' => '  Wednesday   dip  ']);
    $named = db_row('SELECT title FROM insight_threads WHERE threadId = ?', [$tid]);
    /* A title is the one free-text field in this subsystem that nothing else
       checks, and it lives in the same store as the questions — so it goes
       through the same gate. */
    $leak = backend_dispatch('analytics.insight.rename', ['requesterId' => 'NGG-2025-0099', 'threadId' => $tid,
        'title' => 'Tunde Bakare tunde@example.com']);
    $empty = backend_dispatch('analytics.insight.rename', ['requesterId' => 'NGG-2025-0099', 'threadId' => $tid, 'title' => '   ']);
    $theirs = backend_dispatch('analytics.insight.rename', ['requesterId' => 'NGG-2025-0098', 'threadId' => $tid, 'title' => 'Mine now']);
    // Archived threads leave the picker; nothing is deleted.
    $arch = backend_dispatch('analytics.insight.archive', ['requesterId' => 'NGG-2025-0099', 'threadId' => $tid]);
    $listed = backend_dispatch('analytics.insight.threads', ['requesterId' => 'NGG-2025-0099'])['threads'] ?? [];
    $still = db_row('SELECT COUNT(*) n FROM insight_turns WHERE threadId = ?', [$tid]);
    return !empty($ok['ok']) && (string)$named['title'] === 'Wednesday dip'
        && ($leak['error'] ?? '') === 'question_identifies_someone'
        && ($empty['error'] ?? '') === 'title_required'
        && empty($theirs['ok'])
        && !empty($arch['ok'])
        && !array_filter($listed, fn($t) => $t['threadId'] === $tid)
        && (int)$still['n'] > 0;
})());
chk('a one-word question is refused before anything is spent', (function () {
    $called = 0;
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = function ($p, $s, $t) use (&$called) { $called++; return (__ichat_mock())($p, $s, $t); };
    $r = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099', 'question' => 'why']);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    return empty($r['ok']) && $called === 0;
})());
chk('an hourly budget stops a runaway from spending a programme\'s API key', (function () {
    /* Not rate_limit_check(): that keys on the client IP, so one centre behind a
       single NAT would share a budget between its coordinators, and it terminates
       the response, which is right for a route and wrong here. */
    $slot = (int)floor(time() / 3600);
    $key = 'ichat_budget_' . substr(sha1('NGG-2025-0099'), 0, 12) . '_' . $slot;
    cache_put($key, ['n' => ICHAT_TURNS_PER_HOUR]);
    $called = 0;
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = function ($p, $s, $t) use (&$called) { $called++; return (__ichat_mock())($p, $s, $t); };
    $r = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099', 'question' => 'Why is Wednesday weak?']);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    cache_put($key, ['n' => 0]);
    return empty($r['ok']) && ($r['error'] ?? '') === 'rate_limited' && $called === 0;
})());

/* ── The report ──────────────────────────────────────────────────────────────
 *
 * Pinning answers produced a TRANSCRIPT: N questions in pin order, each honest
 * and traceable. Three things a report does that a transcript cannot were all
 * left to the reader — what the set adds up to, whether the set is even about
 * the same data, and what would make it wrong. The checks are deterministic on
 * purpose: a report-level warning a model might or might not notice is not a
 * warning.
 */

/** A turn as ichat_turn_out() shapes it, for the pure checks below. */
function __rep_turn(array $o): array {
    return array_merge(['seq' => 1, 'question' => 'q', 'answer' => 'a', 'plan' => [], 'claims' => [],
        'data' => [], 'checks' => ['grounded' => true], 'evidenceFp' => 'fp-a', 'rangeLabel' => 'Week 1',
        'status' => 'ok', 'error' => '', 'providers' => [], 'ms' => 1, 'at' => ''], $o);
}

chk('report: findings drawn from different snapshots say so — the whole is misleading when the parts are not', (function () {
    /* THE DANGEROUS ONE. Six questions asked across a week, with the date filter
     * moved in between, produced a document that mixed snapshots and read as one
     * coherent view of one dataset. Every finding correct; the set not. */
    $c = irep_checks([
        __rep_turn(['seq' => 1, 'evidenceFp' => 'fp-a', 'rangeLabel' => 'Last 7 days']),
        __rep_turn(['seq' => 2, 'evidenceFp' => 'fp-b', 'rangeLabel' => 'This term']),
    ]);
    $txt = implode(' | ', array_column($c['notes'], 'text'));
    return $c['mixedEvidence'] === true && $c['snapshots'] === 2
        && $c['mixedRanges'] === true && count($c['ranges']) === 2
        && strpos($txt, 'different snapshots') !== false
        && strpos($txt, 'different date ranges') !== false
        && strpos($txt, 'Last 7 days') !== false;
})());

chk('report: one snapshot and one range raises nothing — the check must not cry wolf', (function () {
    $c = irep_checks([__rep_turn(['seq' => 1]), __rep_turn(['seq' => 2])]);
    return $c['mixedEvidence'] === false && $c['mixedRanges'] === false && $c['notes'] === [];
})());

chk('report: the same headline reported twice with different numbers is named', (function () {
    /* Compared on the STRUCTURED stats rather than on the prose, so this is an
     * exact finding and not a guess. A document printing 78% and 71% under the
     * same word, without noticing, is worse than one printing neither. */
    $c = irep_checks([
        __rep_turn(['seq' => 1, 'question' => 'How is attendance?', 'data' => ['stats' => [['label' => 'Attendance rate', 'value' => '78%']]]]),
        __rep_turn(['seq' => 2, 'question' => 'And at Ayobo?', 'data' => ['stats' => [['label' => 'attendance  rate', 'value' => '71%']]]]),
    ]);
    $txt = implode(' | ', array_column($c['notes'], 'text'));
    return count($c['conflicts']) === 1
        && count($c['conflicts'][0]['values']) === 2
        && strpos($txt, 'report "Attendance rate" differently') !== false
        && strpos($txt, '78%') !== false && strpos($txt, '71%') !== false;
})());

chk('report: the same headline reported twice with the SAME number is not a conflict', (function () {
    $c = irep_checks([
        __rep_turn(['seq' => 1, 'data' => ['stats' => [['label' => 'Attendance', 'value' => '78%']]]]),
        __rep_turn(['seq' => 2, 'data' => ['stats' => [['label' => 'Attendance', 'value' => 'about 78%']]]]),
        // A stat with no number at all cannot disagree with anything.
        __rep_turn(['seq' => 3, 'data' => ['stats' => [['label' => 'Attendance', 'value' => '—']]]]),
    ]);
    return $c['conflicts'] === [];
})());

chk('report: limitations become one deduped section, and the ungrounded ones are counted', (function () {
    /* A caveat printed six times beside six findings is a caveat read none. */
    $c = irep_checks([
        __rep_turn(['seq' => 1, 'data' => ['caveat' => 'Only 4 children were graded.']]),
        __rep_turn(['seq' => 2, 'data' => ['caveat' => 'only 4 children were graded']]),
        __rep_turn(['seq' => 3, 'data' => ['caveat' => 'One centre has not reported.'],
                    'checks' => ['grounded' => false, 'dropped' => [['block' => 'table']]]]),
        __rep_turn(['seq' => 4, 'status' => 'unanswerable']),
    ]);
    $txt = implode(' | ', array_column($c['notes'], 'text'));
    return count($c['limitations']) === 2
        && count($c['ungrounded']) === 1 && $c['droppedBlocks'] === 1 && count($c['unanswerable']) === 1
        && strpos($txt, 'not found in the evidence') !== false
        && strpos($txt, 'withheld') !== false
        && strpos($txt, 'could not be answered') !== false;
})());

chk('report: the summary is held to the same grounding gate as every answer', (function () {
    /* A summary is the one paragraph everybody reads and nobody checks, so a
     * figure in it that is not in the findings is DROPPED rather than shipped
     * with a warning — a summary carrying a caveat still reads as the summary. */
    $turns = [
        __rep_turn(['seq' => 1, 'answer' => 'Attendance is 78% across the programme.']),
        __rep_turn(['seq' => 2, 'answer' => 'Ayobo reaches 71% of its sessions.']),
    ];
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = function ($profile, $sys, $t) {
        return ['ok' => true, 'provider' => 'stub-synth', 'text' => json_encode([
            // 93% is in neither finding. The takeaway is.
            'summary' => 'Attendance sits at 93% overall, which is strong.',
            'takeaways' => ['Ayobo is at 71%, behind the programme.', 'A second figure of 42% needs watching.'],
            'decisions' => [['do' => 'Send a mentor to Ayobo, at 71%.', 'because' => 'it trails']],
            'tension' => '',
        ])];
    };
    $s = irep_synthesis($turns, ['mixedRanges' => false, 'mixedEvidence' => false], 'T');
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    return $s['summary'] === ''                       // 93% dropped the whole sentence
        && count($s['takeaways']) === 1               // 42% dropped its line, 71% kept
        && strpos($s['takeaways'][0], '71%') !== false
        && count($s['decisions']) === 1               // grounded in 71%
        && count($s['dropped']) === 2
        && $s['ok'] === true;                         // something survived, so it still ships
})());

chk('report: a summary with nothing grounded left is withheld entirely, not shipped empty', (function () {
    $turns = [__rep_turn(['seq' => 1, 'answer' => 'Attendance is 78%.']), __rep_turn(['seq' => 2, 'answer' => 'Grades average 61.'])];
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = fn($profile, $sys, $t) => ['ok' => true, 'provider' => 'stub', 'text' => json_encode([
        'summary' => 'Everything is at 99%.', 'takeaways' => ['Also 12345 things.'], 'decisions' => [], 'tension' => '',
    ])];
    $s = irep_synthesis($turns, [], 'T');
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    return $s['ok'] === false && ($s['error'] ?? '') === 'ungrounded' && $s['summary'] === '';
})());

chk('report: the op keeps the reader\'s order and is gated on the thread\'s owner', (function () {
    $cfg = __ichat_config_on();
    $GLOBALS['__ai_mock'] = __ichat_mock();
    $a = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099', 'question' => 'Why is Wednesday weak?']);
    if (empty($a['ok'])) { unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg); return true; }
    $tid = (string)$a['threadId'];
    backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099', 'threadId' => $tid, 'question' => 'And which centre is furthest behind?']);
    // Pin order is an editorial choice: 2 then 1 must come back 2 then 1.
    $r = backend_dispatch('analytics.insight.report', ['requesterId' => 'NGG-2025-0099', 'threadId' => $tid, 'seqs' => [2, 1]]);
    $mine = backend_dispatch('analytics.insight.report', ['requesterId' => 'NGG-2025-0700', 'threadId' => $tid, 'seqs' => [1]]);
    $anon = backend_dispatch('analytics.insight.report', ['requesterId' => '', 'threadId' => $tid]);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    return !empty($r['ok']) && ($r['report']['seqs'] ?? []) === [2, 1]
        && isset($r['report']['checks']['notes'])
        && ($mine['error'] ?? '') === 'not_yours'
        && ($anon['ok'] ?? false) !== true;
})());

chk('report: one finding gets the checks but no model call spent restating it', (function () {
    $cfg = __ichat_config_on();
    $called = 0;
    $GLOBALS['__ai_mock'] = function ($profile, $sys, $t) use (&$called) {
        if (strpos((string)$sys, 'add up to') !== false) $called++;
        return (__ichat_mock())($profile, $sys, $t);
    };
    $a = backend_dispatch('analytics.insight.ask', ['requesterId' => 'NGG-2025-0099', 'question' => 'Why is Wednesday weak?']);
    if (empty($a['ok'])) { unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg); return true; }
    $r = backend_dispatch('analytics.insight.report', ['requesterId' => 'NGG-2025-0099',
        'threadId' => (string)$a['threadId'], 'seqs' => [1]]);
    unset($GLOBALS['__ai_mock']); __ichat_config_off($cfg);
    return !empty($r['ok']) && ($r['report']['synthesis']['error'] ?? '') === 'too_few' && $called === 0
        && ($r['report']['checks']['findings'] ?? 0) === 1;
})());

