        $ref = substr($path, strlen('/transaction/verify/'));
        return ['status' => true, 'data' => ['status' => 'success', 'channel' => 'card', 'reference' => $ref, 'amount' => ($GLOBALS['__don_kobo'] ?? 500000), 'currency' => 'NGN']];
    };
