    chk('volunteer pay · NGG fines owed are known before paying', volpay_ngg_fines_owed('NGG-PAY-M3') === 1000);
    $calls = [];
    $GLOBALS['__volpay_av_mock'] = function (string $op, array $pl) use (&$calls) {
