        if ($op === 'owed') return ['ok' => true, 'owing' => ['vol-pay-3@example.com' => 1000, 'vol-pay-4@example.com' => 9000]];
        if ($op === 'settle') { $o = []; foreach ($pl['items'] as $it) $o[$it['reference']] = $it['amount']; return ['ok' => true, 'settled' => $o]; }
