    db_insert('members', ['memberId' => 'NGG-CI-SUM', 'fullName' => 'Summer Desk', 'email' => 'cisum@example.com', 'type' => 'NGG', 'status' => 'active', 'role' => 'summer_admin', 'createdAt' => $now, 'updatedAt' => $now]);
