        && ($r['student']['kind'] ?? '') === 'member' && ($r['student']['memberId'] ?? '') === 'NGG-CI-1');
    chk('checkin: …into the one attendance table, on the member id',
        (bool)db_row('SELECT id FROM attendance WHERE studentId = ? AND date = ?', ['NGG-CI-1', attendance_today()]));
