        db_insert('qr_codes', ['token' => 'SUMQR-SEAS' . $k, 'batch' => 'T', 'cohortId' => $c, 'status' => 'assigned', 'studentId' => 'SS-SEAS-' . $k, 'createdAt' => $now]);
    }
