    db_insert('members', ['memberId' => 'SUM-QW-1', 'fullName' => 'Summer Quote', 'email' => 'sqw@example.com', 'type' => 'Summer', 'status' => 'active', 'role' => 'member', 'createdAt' => $now, 'updatedAt' => $now]);
