/* ── Programme days per person: their centre's days, counted honestly ────── */
(function () {
    $now = now_iso();
    $today = attendance_today();
    $keep = []; foreach (['memberProgramme', 'policy', 'policy_member_swept_through'] as $k) $keep[$k] = setting_raw($k);
    // The preview of a calendar that is OFF is empty — not every day in a row.
    setting_set('memberProgramme', ['enabled' => false, 'startDate' => '', 'endDate' => '', 'weekdays' => [6], 'holidays' => [], 'extraDays' => []], 'test');
    $st = backend_dispatch('admin.policy.settings', ['requesterId' => 'NGG-2025-0099']);
    chk('days: an OFF calendar previews nothing, not fourteen days in a row', $st['memberCalendar']['enabled'] === false && $st['memberCalendar']['upcoming'] === [] && $st['memberCalendar']['isProgrammeDay'] === null);

    // A Wednesday centre's member is not absent on the shared Saturday.
    $ago = fn($d) => gmdate('Y-m-d', strtotime($today . ' UTC') - $d * 86400);
    db_insert('centres', ['centreId' => 'CEN-PD-W', 'name' => 'Pd Wednesday', 'code' => 'PW', 'status' => 'active', 'meetDays' => 'Wednesdays', 'createdAt' => $now]);
    db_insert('members', ['memberId' => 'NGG-PD-1', 'fullName' => 'Pd Wed', 'email' => 'pd1@example.com', 'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => 'Pd Wednesday', 'createdAt' => $now, 'updatedAt' => $now]);
    db_insert('members', ['memberId' => 'NGG-PD-2', 'fullName' => 'Pd Sat', 'email' => 'pd2@example.com', 'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => '', 'createdAt' => $now, 'updatedAt' => $now]);
    member_programme_settings_save(['enabled' => true, 'startDate' => $ago(30), 'endDate' => $ago(-30), 'weekdays' => [6], 'holidays' => [], 'extraDays' => []], 'test');
    policy_settings_save(['member' => ['enabled' => true, 'checkoutRequired' => false]], 'test');
    // The last 8 days hold exactly one Saturday and one Wednesday.
    $sat = ''; $wed = '';
    for ($i = 1; $i <= 7; $i++) { $d = $ago($i); $n = (int)gmdate('N', strtotime($d . ' UTC')); if ($n === 6) $sat = $d; if ($n === 3) $wed = $d; }
    setting_set('policy_member_swept_through', $ago(8), 'system');
    policy_sweep_member_absences($ago(1));
    $abs = fn($id) => array_column(db_all("SELECT date FROM infractions WHERE personId = ? AND kind = 'absence'", [$id]), 'date');
    chk('days: a Wednesday centre\'s member is absent on their Wednesday, not the shared Saturday', in_array($wed, $abs('NGG-PD-1'), true) && !in_array($sat, $abs('NGG-PD-1'), true));
    chk('days: …while a member on the shared calendar is absent on Saturday', in_array($sat, $abs('NGG-PD-2'), true) && !in_array($wed, $abs('NGG-PD-2'), true));
    chk('days: the desk grades the Wednesday member on Wednesday', policy_is_day_for('NGG-PD-1', $wed, 'member') === true && policy_is_day_for('NGG-PD-1', $sat, 'member') === false);

    // A scan on a day the centre does not meet is not attendance.
    db_insert('attendance', ['cohortId' => '', 'studentId' => 'NGG-PD-1', 'date' => $sat, 'checkInAt' => $sat . 'T09:00:00Z', 'checkOutAt' => '', 'method' => 'test', 'createdAt' => $now]);
    $x = companion_metrics(db_row("SELECT * FROM members WHERE memberId = 'NGG-PD-1'"));
    chk('days: a scan on a non-meeting day does not cancel a real absence', $x['attendance']['present'] === 0 && $x['attendance']['absent'] === $x['attendance']['programmeDays']);

    // The first sweep never backfills the term.
    setting_set('policy_member_swept_through', '', 'system');
    db_exec("DELETE FROM settings WHERE settingKey = 'policy_member_swept_through'");
    db_exec("DELETE FROM infractions WHERE personId LIKE 'NGG-PD-%'");
    policy_sweep_member_absences($ago(1));
    $early = db_row("SELECT MIN(date) d FROM infractions WHERE personId LIKE 'NGG-PD-%' AND kind = 'absence'")['d'];
    chk('days: switching enforcement on does not log absences back to the start of term', $early === null || $early >= $ago(1));

    foreach ($keep as $k => $v) { if ($v === null) db_exec('DELETE FROM settings WHERE settingKey = ?', [$k]); else db_exec('UPDATE settings SET settingValue = ? WHERE settingKey = ?', [$v, $k]); }
    db_exec("DELETE FROM infractions WHERE personId LIKE 'NGG-PD-%'");
    db_exec("DELETE FROM sanctions WHERE personId LIKE 'NGG-PD-%'");
    db_exec("DELETE FROM member_ledger WHERE memberId LIKE 'NGG-PD-%'");
    db_exec("DELETE FROM attendance WHERE studentId LIKE 'NGG-PD-%'");
    db_exec("DELETE FROM members WHERE memberId LIKE 'NGG-PD-%'");
    db_exec("DELETE FROM centres WHERE centreId = 'CEN-PD-W'");
})();

/* ── A sign-out that arrives after the nightly check clears the absence it caused ── */
(function () {
    $now = now_iso();
    $today = attendance_today();
    $keep = []; foreach (['memberProgramme', 'policy', 'policy_member_swept_through', 'policy_member_checkout_since'] as $k) $keep[$k] = setting_raw($k);
    $ago = fn($d) => gmdate('Y-m-d', strtotime($today . ' UTC') - $d * 86400);
    $sat = ''; for ($i = 1; $i <= 7; $i++) { $d = $ago($i); if ((int)gmdate('N', strtotime($d . ' UTC')) === 6) $sat = $d; }
    db_insert('members', ['memberId' => 'NGG-LO-1', 'fullName' => 'Lo Late', 'email' => 'lo1@example.com', 'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => '', 'createdAt' => $now, 'updatedAt' => $now]);
    member_programme_settings_save(['enabled' => true, 'startDate' => $ago(30), 'endDate' => $ago(-30), 'weekdays' => [6], 'holidays' => [], 'extraDays' => []], 'test');
    policy_settings_save(['member' => ['enabled' => true, 'checkoutRequired' => true]], 'test');
    setting_set('policy_member_checkout_since', $ago(20), 'system');
    // Came in through the CACENTRE gate on Saturday; the gate never sent the departure.
    db_insert('attendance', ['cohortId' => '', 'studentId' => 'NGG-LO-1', 'date' => $sat, 'checkInAt' => $sat . 'T07:34:00Z', 'checkOutAt' => '', 'method' => 'webhook', 'createdAt' => $now]);
    setting_set('policy_member_swept_through', $ago(8), 'system');
    policy_sweep_member_absences($ago(1));
    $live = fn() => array_column(db_all("SELECT kind FROM infractions WHERE personId = 'NGG-LO-1' AND date = ? AND (voidedAt IS NULL OR voidedAt = '')", [$sat]), 'kind');
    chk('late sign-out: the sweep counts a day with no sign-out as a half-day, not an absence', in_array('halfday', $live(), true) && in_array('no_checkout', $live(), true) && !in_array('absence', $live(), true));

    $rec = backend_dispatch('admin.members.record', ['requesterId' => 'NGG-2025-0099', 'memberId' => 'NGG-LO-1']);
    $onSat = array_values(array_filter($rec['attendance']['recent'] ?? [], fn($r) => $r['date'] === $sat));
    chk('late sign-out: the record shows that Saturday once, as no sign-out — not present AND absent', count($onSat) === 1 && $onSat[0]['kind'] === 'incomplete' && $onSat[0]['in'] === '07:34');
    chk('late sign-out: …and counts it once, as a half-day — they came', ($rec['attendance']['present'] ?? -1) === 1 && ($rec['attendance']['absent'] ?? -1) === 0 && ($rec['attendance']['halfDays'] ?? -1) === 1);
    $own = backend_dispatch('member.records', ['memberId' => 'NGG-LO-1']);
    $ownSat = array_values(array_filter($own['attendance']['days'] ?? [], fn($r) => $r['date'] === $sat));
    chk('late sign-out: the member\'s own records say it was a half-day, not "present"', ($ownSat[0]['status'] ?? '') === 'no sign-out, a half-day');

    // Days later the gate's back-fill delivers the departure, with its own time.
    $tz = (int)attendance_settings()['tzOffset'];
    $leftAt = gmdate('Y-m-d\TH:i:s\Z', strtotime($sat . ' 17:30:00 UTC') - $tz * 60);
    $h = backend_dispatch('hooks.attendance', ['source' => 'cacentre-gate', 'events' => [['ref' => 'NGG-LO-1', 'action' => 'out', 'date' => $sat, 'scannedAt' => $leftAt]]]);
    $row = db_row('SELECT checkOutAt FROM attendance WHERE studentId = ? AND date = ?', ['NGG-LO-1', $sat]);
    chk('late sign-out: a departure re-sent days later is stamped at the time it happened, not now', ($h['results'][0]['status'] ?? '') === 'marked' && (string)$row['checkOutAt'] === $leftAt);
    chk('late sign-out: …and the no-sign-out half-day and its no_checkout are voided', $live() === []);
    chk('late sign-out: …with the reason kept', (bool)db_row("SELECT 1 FROM infractions WHERE personId = 'NGG-LO-1' AND date = ? AND voidReason LIKE 'Signed out%'", [$sat]));
    $rec2 = backend_dispatch('admin.members.record', ['requesterId' => 'NGG-2025-0099', 'memberId' => 'NGG-LO-1']);
    $onSat2 = array_values(array_filter($rec2['attendance']['recent'] ?? [], fn($r) => $r['date'] === $sat));
    chk('late sign-out: the record now shows a present day with its sign-out time', count($onSat2) === 1 && $onSat2[0]['kind'] === 'present' && $onSat2[0]['out'] === gmdate('H:i', strtotime($leftAt)));
    chk('late sign-out: a departure delivered for a past day sends the member no email today', !array_filter($GLOBALS['__mail_sink'] ?? [], fn($m) => $m['to'] === 'lo1@example.com'));

    // A real absence (never came) is not this path's to clear.
    $other = $ago(15); while ((int)gmdate('N', strtotime($other . ' UTC')) !== 6) $other = gmdate('Y-m-d', strtotime($other . ' UTC') - 86400);
    policy_log('NGG-LO-1', 'member', 'absence', $other, 'No check-in on a member programme day.');
    chk('late sign-out: an absence for a day they never came is untouched', policy_checkout_landed('NGG-LO-1', 'member', $other) === 0);

    foreach ($keep as $k => $v) { if ($v === null) db_exec('DELETE FROM settings WHERE settingKey = ?', [$k]); else db_exec('UPDATE settings SET settingValue = ? WHERE settingKey = ?', [$v, $k]); }
    foreach (['infractions' => 'personId', 'sanctions' => 'personId', 'member_ledger' => 'memberId', 'attendance' => 'studentId', 'members' => 'memberId'] as $t => $c) db_exec("DELETE FROM $t WHERE $c = 'NGG-LO-1'");
})();

