/* ── The training-fee watch: one schedule for the member and the desk ── */
(function () {
    $now = now_iso();
    $keep = setting_raw('fees'); $keepCal = setting_raw('memberProgramme');
    fees_settings_save(['enabled' => true, 'trainingFee' => 10000, 'trainingBasis' => 'session', 'trainingMonths' => 18,
                        'serviceMonths' => 18, 'membershipFee' => 0, 'monthlyDues' => 0, 'balanceCap' => 0], 'test');
    $mk = fn($id, $joinMonthsAgo, $extra = []) => db_insert('members', array_merge(['memberId' => $id, 'fullName' => 'Tw ' . $id, 'email' => strtolower($id) . '@example.com',
        'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => 'Egbeda', 'joinDate' => gmdate('Y-m-d', strtotime('-' . $joinMonthsAgo . ' months')),
        'createdAt' => $now, 'updatedAt' => $now], $extra));
    $mk('NGG-TW-NEW', 2); $mk('NGG-TW-OLD', 24); $mk('NGG-TW-IKJ', 2, ['centre' => 'Ikeja']);
    $mk('NGG-TW-ADM', 0, ['role' => 'admin', 'capsExtra' => json_encode(['fees'])]);
    $mk('NGG-TW-SCOPED', 0, ['role' => 'admin', 'capsExtra' => json_encode(['fees']), 'centreScope' => json_encode(['Egbeda'])]);
    foreach ([['TWS-1', -1, 'Term one'], ['TWS-2', 2, 'Term two'], ['TWS-OLD', -22, 'Long ago']] as [$sid, $off, $name]) {
        db_insert('sessions', ['sessionId' => $sid, 'name' => $name, 'year' => (int)gmdate('Y'),
            'startDate' => gmdate('Y-m-d', strtotime($off . ' months')), 'endDate' => gmdate('Y-m-d', strtotime(($off + 2) . ' months'))]);
    }
    foreach (['NGG-TW-NEW', 'NGG-TW-OLD', 'NGG-TW-IKJ'] as $id) fees_accrue_member(db_row('SELECT * FROM members WHERE memberId = ?', [$id]));
    $new = db_row("SELECT * FROM members WHERE memberId = 'NGG-TW-NEW'");
    $w = fees_training_watch($new);
    $states = array_column($w['rows'], 'state', 'key');
    $tws1 = array_values(array_filter($w['rows'], fn($r) => $r['key'] === 'TWS-1'))[0] ?? [];
    chk('watch: a member in training sees the session charged, dated by the session, and the next one to come', ($states['TWS-1'] ?? '') === 'charged' && ($states['TWS-2'] ?? '') === 'upcoming'
        && ($tws1['date'] ?? '') === gmdate('Y-m-d', strtotime('-1 months')) && $w['charged'] >= 1 && $w['upcoming'] >= 1 && $w['unit'] === 'session' && $w['perUnit'] === 10000);
    chk('watch: …a session before they joined is not on their schedule', !isset($states['TWS-OLD']));
    $acct = backend_dispatch('member.fees', ['memberId' => 'NGG-TW-NEW'])['account'];
    $adm = backend_dispatch('admin.fees.member', ['requesterId' => 'NGG-TW-ADM', 'memberId' => 'NGG-TW-NEW'])['account'];
    chk('watch: the member\'s panel and the Control Room drawer read the same rows', $acct['training']['rows'] === $adm['training']['rows']
        && array_column($acct['schedule'], 'state', 'sessionId') === $states);
    $old = fees_training_watch(db_row("SELECT * FROM members WHERE memberId = 'NGG-TW-OLD'"));
    chk('watch: two years in, nothing is still to come and service is covering it', $old['phase'] === 'service' && $old['upcoming'] === 0 && $old['due'] === 0
        && $old['covered'] > 0 && $old['coveredPct'] > 0 && $old['coveredPct'] < 100);

    // A week basis lists the weeks still to come off the meeting calendar.
    setting_set('memberProgramme', ['enabled' => true, 'startDate' => gmdate('Y-m-d', strtotime('-60 days')), 'endDate' => gmdate('Y-m-d', strtotime('+60 days')),
        'weekdays' => [6], 'holidays' => [], 'extraDays' => []], 'test');
    $refused = fees_settings_save(['trainingBasis' => 'week'] + fees_settings(), 'test');
    chk('settings: switching what the training fee is charged per, with the same amount, is refused — it would turn a session rate into a week rate',
        empty($refused['ok']) && ($refused['error'] ?? '') === 'training_rate_required' && fees_settings()['trainingBasis'] === 'session');
    fees_settings_save(['trainingBasis' => 'week', 'trainingFee' => 2500] + fees_settings(), 'test');
    // Weeks are only charged where the session was not already charged whole; and unfrozen, as a member starting now.
    db_exec("DELETE FROM member_ledger WHERE memberId = 'NGG-TW-NEW' AND kind = 'training'");
    db_exec("UPDATE members SET feeTerms = '' WHERE memberId = 'NGG-TW-NEW'");
    $new = db_row("SELECT * FROM members WHERE memberId = 'NGG-TW-NEW'");
    $ww = fees_training_watch($new);
    $mondays = array_column(array_filter($ww['rows'], fn($r) => $r['state'] === 'upcoming'), 'date');
    chk('watch (week rate): the weeks still to come are listed, one per week, each on its Monday', $ww['unit'] === 'week' && count($mondays) >= 7
        && count($mondays) === count(array_unique($mondays)) && !array_filter($mondays, fn($d) => gmdate('N', strtotime($d . ' UTC')) !== '1'));
    chk('watch (week rate): weeks that have happened but are not charged yet wait for the next run', $ww['due'] > 0
        && !array_filter($ww['rows'], fn($r) => $r['state'] === 'due' && $r['date'] > gmdate('Y-m-d')));
    fees_settings_save(['trainingBasis' => 'session', 'trainingFee' => 10000] + fees_settings(), 'test');

    // The desk's watch over everybody.
    fees_accrue_member($new);
    $all = backend_dispatch('admin.fees.training', ['requesterId' => 'NGG-TW-ADM', 'limit' => 1000]);
    $ids = array_column($all['rows'] ?? [], 'memberId');
    chk('watch (desk): everybody with a training fee is listed, staff are not', !array_diff(['NGG-TW-NEW', 'NGG-TW-OLD', 'NGG-TW-IKJ'], $ids) && !in_array('NGG-TW-ADM', $ids, true));
    $row = array_values(array_filter($all['rows'], fn($r) => $r['memberId'] === 'NGG-TW-OLD'))[0];
    $bal = fees_balance(db_row("SELECT * FROM members WHERE memberId = 'NGG-TW-OLD'"));
    chk('watch (desk): a row agrees with the member\'s own account', $row['charged'] === (int)$bal['trainingCharged'] && $row['covered'] === (int)$bal['programmeCovered']
        && $row['remaining'] === (int)$bal['trainingCharged'] - (int)$bal['programmeCovered']);
    chk('watch (desk): filtering by phase works, and an unknown filter falls back to everybody',
        in_array('NGG-TW-OLD', $svc = array_column(backend_dispatch('admin.fees.training', ['requesterId' => 'NGG-TW-ADM', 'filter' => 'service', 'limit' => 1000])['rows'], 'memberId'), true)
        && !in_array('NGG-TW-NEW', $svc, true)
        && backend_dispatch('admin.fees.training', ['requesterId' => 'NGG-TW-ADM', 'filter' => 'DROP TABLE'])['filter'] === 'all');
    chk('watch (desk): a centre-scoped operator sees only their centres', !in_array('NGG-TW-IKJ', array_column(backend_dispatch('admin.fees.training', ['requesterId' => 'NGG-TW-SCOPED'])['rows'], 'memberId'), true));
    chk('watch (desk): it needs the fees permission', (backend_dispatch('admin.fees.training', ['requesterId' => 'NGG-TW-NEW'])['ok'] ?? true) === false);
    // The query count does not grow with the roster.
    $GLOBALS['__db_qcount'] = 0; backend_dispatch('admin.fees.training', ['requesterId' => 'NGG-TW-ADM']); $q1 = $GLOBALS['__db_qcount'];
    for ($i = 0; $i < 15; $i++) { $mk('NGG-TW-X' . $i, 3); }
    $GLOBALS['__db_qcount'] = 0; backend_dispatch('admin.fees.training', ['requesterId' => 'NGG-TW-ADM']); $q2 = $GLOBALS['__db_qcount'];
    unset($GLOBALS['__db_qcount']);
    chk('watch (desk): fifteen more members cost no more queries', $q2 === $q1);

    db_exec("DELETE FROM member_ledger WHERE memberId LIKE 'NGG-TW-%'");
    db_exec("DELETE FROM members WHERE memberId LIKE 'NGG-TW-%'");
    db_exec("DELETE FROM sessions WHERE sessionId LIKE 'TWS-%'");
    if ($keep === null) db_exec("DELETE FROM settings WHERE settingKey = 'fees'"); else db_exec('UPDATE settings SET settingValue = ? WHERE settingKey = ?', [$keep, 'fees']);
    if ($keepCal === null) db_exec("DELETE FROM settings WHERE settingKey = 'memberProgramme'"); else db_exec('UPDATE settings SET settingValue = ? WHERE settingKey = ?', [$keepCal, 'memberProgramme']);
})();

/* ── The bundled Media Lab course: a course the catalogue does not list, loaded on purpose ── */
(function () {
    $now = now_iso();
    db_insert('members', ['memberId' => 'NGG-ML-ADM', 'fullName' => 'Media Admin', 'email' => 'ml-adm@example.com', 'type' => 'NGG', 'status' => 'active', 'role' => 'club_admin', 'createdAt' => $now, 'updatedAt' => $now]);
    $s = backend_dispatch('admin.curriculum.seed', ['requesterId' => 'NGG-ML-ADM', 'key' => 'media-lab-2026']);
    $rows = $s['rows'] ?? [];
    $cat = array_map('mb_strtolower', club_courses());
    chk('media lab: the course ships, 24 weeks of two sessions, every lesson with a check', count($rows) === 48
        && count(array_unique(array_column($rows, 'week'))) === 24 && !array_filter($rows, fn($r) => !$r['checks']));
    /* It used to file all 48 under "Media Lab", a course nobody could enrol on,
       so every one of them reached nobody. Each lesson now names the media
       course that teaches it — or '' for the handful (safety, honest AI use,
       research) that belong to every member of the programme. */
    chk('media lab: every lesson names a real catalogue course, or everyone',
        !array_filter($rows, fn($r) => $r['course'] !== '' && !in_array(mb_strtolower($r['course']), $cat, true)));
    chk('media lab: the design, photography, video and social weeks each reach their own course',
        count(array_unique(array_filter(array_column($rows, 'course')))) >= 6);
    chk('media lab: it no longer needs the uncatalogued-course flag', ($s['allowNewCourse'] ?? false) === false);
    $proj = 0; $refl = 0;
    foreach ($rows as $r) foreach ($r['checks'] as $c) { if ($c['kind'] === 'project') $proj++; if ($c['kind'] === 'reflection') $refl++; }
    chk('media lab: a team challenge every month, marked on the programme\'s rubric, with a reflection', $proj >= 6 && $refl >= 6
        && !array_filter($rows, fn($r) => array_filter($r['checks'], fn($c) => $c['kind'] === 'project' && !str_contains($c['rubric'], 'Technical skill 30%'))));
    $bodies = implode("\n", array_map(fn($r) => $r['title'] . ' ' . $r['body'] . ' ' . $r['summary'], $rows));
    chk('media lab: consent and age rules are taught before the first photograph of a person', stripos($bodies, 'consent') !== false && stripos($bodies, '13+') !== false
        && array_search('Staying safe online, and asking before you post', array_column($rows, 'title')) < array_search('Portraits — with permission', array_column($rows, 'title')));
    $dry = backend_dispatch('admin.curriculum.import', ['requesterId' => 'NGG-ML-ADM', 'rows' => $rows, 'dryRun' => true]);
    chk('media lab: every lesson passes WITHOUT the uncatalogued-course flag', ($dry['tally']['create'] ?? 0) === 48 && ($dry['tally']['failed'] ?? 1) === 0);
    $ap = backend_dispatch('admin.curriculum.import', ['requesterId' => 'NGG-ML-ADM', 'rows' => $rows, 'digest' => $dry['digest']]);
    chk('media lab: imported as 48 drafts against courses that can be timetabled', ($ap['tally']['create'] ?? 0) === 48
        && in_array('Graphic Design', tt_courses(), true) && in_array('Video Production', tt_courses(), true));
    $ids = array_column(db_all("SELECT unitId FROM curriculum_units WHERE level = 'Media Lab 2026'"), 'unitId');
    if ($ids) { $ph = implode(',', array_fill(0, count($ids), '?'));
        db_exec("DELETE FROM curriculum_checks WHERE unitId IN ($ph)", $ids); db_exec("DELETE FROM curriculum_materials WHERE unitId IN ($ph)", $ids); db_exec("DELETE FROM curriculum_units WHERE unitId IN ($ph)", $ids); }
    db_exec("DELETE FROM members WHERE memberId = 'NGG-ML-ADM'");
})();

/* ── The core courses every member takes: Data Appreciation and Desktop Publishing (owner, 7 Nov 2026:
      "The medialab is for everyone right? Change it to Data Appreciation and Desktop publishing … with
      screenshots, diagrams and presentations and appropriate learning guides and materials") ── */
(function () {
    $now = now_iso();
    db_insert('members', ['memberId' => 'NGG-CORE-ADM', 'fullName' => 'Core Admin', 'email' => 'core-adm@example.com', 'type' => 'NGG', 'status' => 'active', 'role' => 'club_admin', 'createdAt' => $now, 'updatedAt' => $now]);
    $s = backend_dispatch('admin.curriculum.seed', ['requesterId' => 'NGG-CORE-ADM', 'key' => 'core-digital-2026']);
    $rows = $s['rows'] ?? [];
    $by = static fn($c) => array_values(array_filter($rows, fn($r) => $r['course'] === $c));
    chk('core courses · twelve weeks each of Data Appreciation and Desktop Publishing', count($by('Data Appreciation')) === 12 && count($by('Desktop Publishing')) === 12
        && count(array_unique(array_column($by('Data Appreciation'), 'week'))) === 12);
    chk('core courses · they are catalogue courses, so the seed needs no uncatalogued-course flag', ($s['allowNewCourse'] ?? true) === false
        && curriculum_course_canonical('data appreciation') === 'Data Appreciation' && curriculum_course_canonical('Desktop publishing') === 'Desktop Publishing');
    // Every member takes them: a placed pianist, an unplaced member, and division mode alike.
    $pianist = ['memberId' => 'X1', 'type' => 'NGG', 'courses' => json_encode(['Piano'])];
    $nobody  = ['memberId' => 'X2', 'type' => 'NGG'];
    $ctxDiv = ['courseSource' => 'division'];
    chk('core courses · every member takes them — placed, unplaced, and when the division is the enrolment',
        !array_diff(CURR_CORE_COURSES, curriculum_member_courses($pianist)) && !array_diff(CURR_CORE_COURSES, curriculum_member_courses($nobody))
        && !array_diff(CURR_CORE_COURSES, curriculum_member_courses($nobody, $ctxDiv)));
    // More than recognition: each lesson asks for work, and the choice questions name the slip.
    $kinds = []; $whyless = 0;
    foreach ($rows as $r) foreach ($r['checks'] as $c) { $kinds[$c['kind']] = ($kinds[$c['kind']] ?? 0) + 1; if ($c['kind'] === 'mcq' && empty($c['whys'])) $whyless++; }
    chk('core courses · every lesson asks for something that cannot be guessed from four options',
        !array_filter($rows, fn($r) => !array_filter($r['checks'], fn($c) => $c['kind'] !== 'mcq')));
    chk('core courses · practicals, outside exercises, ordering and projects — and every choice question names its slips',
        ($kinds['task'] ?? 0) >= 12 && ($kinds['evidence'] ?? 0) >= 5 && ($kinds['order'] ?? 0) >= 4 && ($kinds['project'] ?? 0) >= 3 && $whyless === 0);
    // The media ship with the code and resolve on a deployment with no media host.
    $missing = [];
    foreach ($rows as $r) {
        preg_match_all('/\]\((media:[^)]+)\)/', $r['body'], $mm);
        $keys = array_merge($mm[1], array_column(array_filter($r['materials'], fn($m) => str_starts_with($m['url'], 'media:')), 'url'));
        foreach ($keys as $k) if (curriculum_media_url($k) === '') $missing[] = $k;
    }
    chk('core courses · every diagram, screenshot, deck and guide ships and resolves' . ($missing ? ' (missing ' . implode(', ', array_slice($missing, 0, 3)) . ')' : ''), $missing === []);
    chk('core courses · a slide deck for every lesson, and the learning guide in week 1',
        !array_filter($rows, fn($r) => !array_filter($r['materials'], fn($m) => $m['kind'] === 'slides'))
        && count(array_filter($rows, fn($r) => array_filter($r['materials'], fn($m) => str_contains($m['url'], 'core/guides/')))) === 2);
    chk('core courses · a lesson body\'s inline picture is served as a real address',
        str_contains(curriculum_unit_public(['unitId' => 'U', 'course' => 'Data Appreciation', 'level' => 'L', 'week' => 1, 'position' => 1, 'title' => 'T', 'summary' => '', 'objectives' => '[]',
            'body' => '![x](media:core/ppdac.svg)', 'durationMins' => 0, 'passMark' => 60, 'status' => 'published', 'version' => 1, 'updatedAt' => ''] + array_fill_keys(['publishedAt', 'source', 'updatedBy', 'createdAt'], ''), [], [], false)['body'], '](/assets/learn-media/core/ppdac.svg)'));
    $dry = backend_dispatch('admin.curriculum.import', ['requesterId' => 'NGG-CORE-ADM', 'rows' => $rows, 'dryRun' => true]);
    chk('core courses · every lesson passes the real importer', ($dry['tally']['create'] ?? 0) === 24 && ($dry['tally']['failed'] ?? 1) === 0);
    chk('core courses · a certificate is styled for each', club_cert_style('Data Appreciation') !== club_cert_style('Desktop Publishing'));
    db_exec("DELETE FROM members WHERE memberId = 'NGG-CORE-ADM'");
})();

/* The six Club-wide Media Lab lessons are retired by the shipped file, never deleted: a lesson that is still
   as shipped stops being taught; one an instructor saved stays theirs; a retired row is never created. */
(function () {
    $saveCfg = $GLOBALS['CONFIG']['seed_bundled_curriculum'] ?? null;
    unset($GLOBALS['CONFIG']['seed_bundled_curriculum']);
    $row = static fn($w, $extra = []) => $extra + ['course' => '', 'level' => 'Retire 2026', 'week' => $w, 'position' => 1, 'title' => 'Club-wide ' . $w,
        'summary' => 'S', 'objectives' => ['O'], 'body' => 'B', 'durationMins' => 30, 'passMark' => 50, 'materials' => [],
        'checks' => [['kind' => 'task', 'prompt' => 'Show what you did', 'rubric' => 'Did it', 'points' => 2]]];
    $GLOBALS['__curriculum_seed_files'] = ['retiretest' => ['key' => 'retiretest', 'lessons' => [$row(1), $row(2)]]];
    db_exec("DELETE FROM settings WHERE settingKey = 'seed_curriculum_retiretest'");
    curriculum_seed_bundled_once();
    $u = static fn($w) => db_row("SELECT * FROM curriculum_units WHERE level = 'Retire 2026' AND week = ?", [$w]);
    db_update('curriculum_units', ['body' => 'Mine.', 'updatedBy' => 'NGG-INSTR'], ['unitId' => $u(2)['unitId']]);
    $GLOBALS['__curriculum_seed_files'] = ['retiretest' => ['key' => 'retiretest', 'lessons' => [$row(1, ['status' => 'retired']), $row(2, ['status' => 'retired']), $row(3, ['status' => 'retired'])]]];
    curriculum_seed_bundled_once();
    chk('retire · a shipped lesson still as shipped is retired, and kept', ($u(1)['status'] ?? '') === 'retired');
    chk('retire · one an instructor saved stays theirs', ($u(2)['status'] ?? '') === 'published' && $u(2)['body'] === 'Mine.');
    chk('retire · a retired row is never created', !$u(3));
    $ml = (json_decode((string)file_get_contents(__DIR__ . '/../_lib/seeds/curriculum-media-lab-2026.json'), true)['lessons'] ?? []);
    chk('retire · the Media Lab file retires exactly its six Club-wide lessons',
        count(array_filter($ml, fn($r) => ($r['status'] ?? '') === 'retired')) === 6 && !array_filter($ml, fn($r) => ($r['status'] ?? '') === 'retired' && $r['course'] !== ''));
    unset($GLOBALS['__curriculum_seed_files']);
    foreach ([1, 2] as $w) { $x = $u($w); if ($x) { db_exec('DELETE FROM curriculum_checks WHERE unitId = ?', [$x['unitId']]); db_exec('DELETE FROM curriculum_units WHERE unitId = ?', [$x['unitId']]); } }
    db_exec("DELETE FROM settings WHERE settingKey = 'seed_curriculum_retiretest'");
    if ($saveCfg !== null) $GLOBALS['CONFIG']['seed_bundled_curriculum'] = $saveCfg;
})();

