    chk('status: a Centre lead account counts as the centre\'s lead', in_array('Sb NGG-SB-LEAD', $cen['Sb Alpha']['leadAccounts'] ?? [], true) && !in_array('no lead', $cen['Sb Alpha']['issues'], true));
