    $GLOBALS['__paystack_mock'] = fn($m, $p, $b) => str_starts_with($p, '/transaction') ? ['status' => true, 'data' => []] : ['status' => false];
    $t = backend_dispatch('admin.keys.test', ['requesterId' => $SU, 'service' => 'paystack']);
