        $calls[] = $m . ' ' . $path;
        if ($path === '/usage') return ['code' => 200, 'body' => ['plan' => 'Free', 'credits' => ['usage' => $usage / 4, 'limit' => 25, 'used_percent' => $usage],
            'storage' => ['usage' => 1, 'used_percent' => $usage - 10], 'bandwidth' => ['usage' => 1, 'used_percent' => 5]]];
