        && (bool)db_row("SELECT 1 FROM ops_events WHERE source = 'media.storage'") && media_uploads_allowed());
    $hits = (int)db_row("SELECT COUNT(*) c FROM audit_log WHERE event = 'media.storage.alert'")['c'];
