        ($gd['error'] ?? '') === 'chained_photos' && ($gd['count'] ?? 0) >= 1 && str_contains((string)($gd['detail'] ?? ''), 'plain images') && !array_filter($calls, static fn($c) => str_starts_with($c, 'DELETE')));
    db_exec("DELETE FROM members WHERE memberId = 'MEDIA-BG'");
