        setting_set('media.refusal.checked', null, 'test'); setting_set('cloudinary_credits', 'ok', 'test');
        unset($GLOBALS['__media_active'], $GLOBALS['CLOUDINARY_PRIMARY'], $GLOBALS['__media_states']);
        $GLOBALS['CONFIG']['cloudinary'] = $main;
    };
    $reset();
