    db_insert('members', ['memberId' => 'NGG-ST-A', 'fullName' => 'Study Ade', 'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => 'Egbeda', 'track' => 'Piano', 'createdAt' => $now, 'updatedAt' => $now]);
    db_insert('members', ['memberId' => 'NGG-ST-B', 'fullName' => 'Study Bisi', 'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'createdAt' => $now, 'updatedAt' => $now]);
    $t = 1_800_000_000;
    $c = ['ease' => 2.5, 'intervalDays' => 0, 'reps' => 0, 'lapses' => 0];
    $g1 = study_schedule($c, 2, $t); $g2 = study_schedule($g1, 2, $t); $g3 = study_schedule($g2, 2, $t);
    chk('flashcards · a card you know comes back after 1 day, then 6, then about 15 (SM-2)', $g1['intervalDays'] === 1 && $g2['intervalDays'] === 6 && $g3['intervalDays'] >= 14 && $g3['intervalDays'] <= 16);
    $again = study_schedule($g3, 0, $t);
    chk('flashcards · a card you miss comes back in ten minutes, starts over, and gets a little harder', $again['intervalDays'] === 0 && $again['reps'] === 0 && $again['lapses'] === 1
        && strtotime($again['dueAt']) === $t + 600 && $again['ease'] < $g3['ease']);
    chk('flashcards · easy goes further than good; hard less far; ease never drops below 1.3', study_schedule($g2, 3, $t)['intervalDays'] > $g3['intervalDays'] && study_schedule($g2, 1, $t)['intervalDays'] < $g3['intervalDays']
        && study_schedule(['ease' => 1.3, 'reps' => 0, 'intervalDays' => 0, 'lapses' => 0], 0, $t)['ease'] === 1.3);

    $A = ['memberId' => 'NGG-ST-A'];
    chk('flashcards · a deck needs a name, and a half-filled card is named before anything is saved', (study_deck_save($A + ['name' => ''])['error'] ?? '') === 'name_required'
        && (study_deck_save($A + ['name' => 'Cells', 'cards' => [['front' => 'Nucleus', 'back' => 'Holds DNA'], ['front' => 'Ribosome', 'back' => '']]])['row'] ?? -1) === 1
        && (int)db_row("SELECT COUNT(*) n FROM study_decks WHERE memberId = 'NGG-ST-A'")['n'] === 0);
    chk('flashcards · more than ' . STUDY_CARDS_MAX . ' cards in a deck is refused, and the cap is named', (study_deck_save($A + ['name' => 'Big', 'cards' => array_fill(0, STUDY_CARDS_MAX + 1, ['front' => 'a', 'back' => 'b'])])['max'] ?? 0) === STUDY_CARDS_MAX);
    $s = study_deck_save($A + ['name' => 'Cells', 'cards' => [['front' => 'Nucleus', 'back' => 'Holds DNA'], ['front' => 'Mitochondria', 'back' => 'Make energy'], ['front' => '', 'back' => '']]]);
    $deckId = $s['deckId'] ?? '';
    chk('flashcards · a deck is saved with its filled cards (blank rows dropped), all due now', !empty($s['ok']) && $s['cards'] === 2 && study_decks($A)['decks'][0]['due'] === 2);
    chk('flashcards · another member cannot open, review, edit or delete my deck', (study_deck(['memberId' => 'NGG-ST-B', 'deckId' => $deckId])['error'] ?? '') === 'not_found'
        && (study_due(['memberId' => 'NGG-ST-B', 'deckId' => $deckId])['error'] ?? '') === 'not_found'
        && (study_deck_save(['memberId' => 'NGG-ST-B', 'deckId' => $deckId, 'name' => 'Mine now'])['error'] ?? '') === 'not_found'
        && (study_deck_delete(['memberId' => 'NGG-ST-B', 'deckId' => $deckId])['error'] ?? '') === 'not_found'
        && study_decks(['memberId' => 'NGG-ST-B'])['decks'] === []);
    $due = study_due($A + ['deckId' => $deckId]);
    $card = $due['cards'][0];
    chk('flashcards · someone else\'s card cannot be reviewed, and a grade must be 0–3', (study_review(['memberId' => 'NGG-ST-B', 'cardId' => $card['cardId'], 'grade' => 3])['error'] ?? '') === 'not_found'
        && (study_review($A + ['cardId' => $card['cardId'], 'grade' => 7])['error'] ?? '') === 'bad_grade');
    $rv = study_review($A + ['cardId' => $card['cardId'], 'grade' => 2]);
    chk('flashcards · reviewed "good", a card is not due again until tomorrow', !empty($rv['ok']) && $rv['intervalDays'] === 1 && count(study_due($A + ['deckId' => $deckId])['cards']) === 1);
    $full = study_deck($A + ['deckId' => $deckId]);
    $kept = array_values(array_filter($full['cards'], fn($x) => $x['cardId'] === $card['cardId']))[0];
    study_deck_save($A + ['deckId' => $deckId, 'name' => 'Cells 2', 'cards' => [['cardId' => $kept['cardId'], 'front' => 'Nucleus (edited)', 'back' => 'Holds DNA']]]);
    $after = study_deck($A + ['deckId' => $deckId]);
    chk('flashcards · editing keeps a card\'s progress; a card left out is removed', count($after['cards']) === 1 && $after['cards'][0]['front'] === 'Nucleus (edited)' && $after['cards'][0]['reps'] === 1 && $after['deck']['name'] === 'Cells 2');
    chk('flashcards · pasted cards: "front — back", "front :: back", tab and "front: back" all split once', count(study_parse_lines("Cell — the unit of life\nAtom :: smallest part\nH2O\twater\nKe: a term: with colon\nno separator here")) === 4
        && study_parse_lines("Ke: a term: with colon")[0]['back'] === 'a term: with colon');

    chk('logs · a focus block and a typing run are logged; nonsense is refused', !empty(study_log($A + ['tool' => 'focus', 'minutes' => 25, 'label' => 'Maths']))
        && !empty(study_log($A + ['tool' => 'typing', 'wpm' => 42, 'accuracy' => 97])) && (study_log($A + ['tool' => 'chess'])['error'] ?? '') === 'bad_tool'
        && (study_log($A + ['tool' => 'focus', 'minutes' => 0])['error'] ?? '') === 'too_short');
    $yday = gmdate('Y-m-d', time() + 3600 - 86400);
    db_insert('study_sessions', ['memberId' => 'NGG-ST-A', 'tool' => 'focus', 'minutes' => 50, 'at' => $now, 'day' => $yday]);
    $st = study_stats($A);
    chk('logs · the week counts focus minutes by day, the streak counts days in a row, typing keeps the best', $st['focusWeek'] === 75 && $st['streak'] === 2 && $st['typing']['best'] === 42
        && count($st['week']) === 7 && end($st['week'])['minutes'] === 25);
    chk('logs · another member sees none of it', study_stats(['memberId' => 'NGG-ST-B'])['focusWeek'] === 0);

    // A deck from one of my lessons, on the study helper's allowance.
    db_insert('curriculum_units', ['unitId' => 'CU-ST-1', 'course' => 'Piano', 'level' => '', 'week' => 1, 'position' => 1, 'title' => 'Intervals', 'status' => 'published', 'version' => 1,
        'body' => "## Learn\n\nA tone is two semitones.\n\n## This week's assignment\n\nSECRET-TASK", 'objectives' => '[]', 'createdAt' => $now]);
    $prevAi = $GLOBALS['CONFIG']['ai'] ?? null;
    $GLOBALS['CONFIG']['ai'] = ['gemini_api_key' => 'g-test', 'anthropic_api_key' => 'sk-test', 'anthropic_model' => 'claude-opus-4-1'];
    $sys = ''; $GLOBALS['__ai_mock'] = function ($pr, $system, $turns) use (&$sys) { $sys = $system; return ['ok' => true, 'provider' => 'mock', 'text' => "Tone :: Two semitones\nSemitone :: The very next key\nnot a card"]; };
    db_exec("DELETE FROM member_state WHERE memberId = 'NGG-ST-A' AND stateKey LIKE 'ai.tutor.%'");
    $ai = study_cards_ai($A + ['unitId' => 'CU-ST-1']);
    chk('flashcards · the study helper writes cards from MY lesson — not its assignment — and saves nothing yet', !empty($ai['ok']) && count($ai['cards']) === 2 && $ai['cards'][0]['back'] === 'Two semitones'
        && str_contains($sys, 'two semitones') && !str_contains($sys, 'SECRET-TASK') && (int)db_row("SELECT COUNT(*) n FROM study_decks WHERE memberId = 'NGG-ST-A' AND name = 'Intervals'")['n'] === 0
        && $ai['left'] === CURR_TUTOR_PER_DAY - 1);
    $GLOBALS['__ai_mock'] = fn($pr, $system, $turns) => ['ok' => false, 'error' => 'ai_down'];
    $before = (int)db_row("SELECT stateValue FROM member_state WHERE memberId = 'NGG-ST-A' AND stateKey = ?", ['ai.tutor.' . gmdate('Y-m-d')])['stateValue'];
    chk('flashcards · a failed attempt gives the allowance back', empty(study_cards_ai($A + ['unitId' => 'CU-ST-1'])['ok'])
        && (int)db_row("SELECT stateValue FROM member_state WHERE memberId = 'NGG-ST-A' AND stateKey = ?", ['ai.tutor.' . gmdate('Y-m-d')])['stateValue'] === $before);
    chk('flashcards · a lesson outside my course is refused', (study_cards_ai($A + ['unitId' => 'CU-TU-X'])['error'] ?? '') === 'not_found');
    unset($GLOBALS['__ai_mock']);
    if ($prevAi === null) unset($GLOBALS['CONFIG']['ai']); else $GLOBALS['CONFIG']['ai'] = $prevAi;
    // Quiz me and Summarise my notes, on the same allowance.
    $GLOBALS['CONFIG']['ai'] = ['gemini_api_key' => 'g-test', 'anthropic_api_key' => 'sk-test', 'anthropic_model' => 'claude-opus-4-1'];
    $sys = ''; $GLOBALS['__ai_mock'] = function ($pr, $system, $turns) use (&$sys) { $sys = $system . "\n" . ($turns[0]['text'] ?? ''); return ['ok' => true, 'provider' => 'mock', 'text' => json_encode(['questions' => [
        ['q' => 'How many semitones in a tone?', 'options' => ['One', 'Two', 'Three', 'Four'], 'answer' => 1, 'why' => 'A tone is two semitones.'],
        ['q' => 'Broken: three options', 'options' => ['a', 'b', 'c'], 'answer' => 0],
        ['q' => 'Broken: answer out of range', 'options' => ['a', 'b', 'c', 'd'], 'answer' => 7],
        ['q' => 'Broken: repeated options', 'options' => ['a', 'a', 'b', 'c'], 'answer' => 0],
        ['q' => 'Q2', 'options' => ['w', 'x', 'y', 'z'], 'answer' => 3, 'why' => ''],
        ['q' => 'Q3', 'options' => ['1', '2', '3', '4'], 'answer' => 0, 'why' => ''],
    ]])]; };
    $qz = study_quiz_ai($A + ['unitId' => 'CU-ST-1']);
    chk('quiz · five questions on MY lesson — never its assignment — and a malformed question is dropped, not shown', !empty($qz['ok']) && count($qz['questions']) === 3
        && $qz['questions'][0]['answer'] === 1 && str_contains($sys, 'two semitones') && !str_contains($sys, 'SECRET-TASK'));
    $GLOBALS['__ai_mock'] = fn($pr, $system, $turns) => ['ok' => true, 'provider' => 'mock', 'text' => '{"questions":[{"q":"only one","options":["a","b","c","d"],"answer":0}]}'];
    $u0 = (int)db_row("SELECT stateValue FROM member_state WHERE memberId = 'NGG-ST-A' AND stateKey = ?", ['ai.tutor.' . gmdate('Y-m-d')])['stateValue'];
    chk('quiz · too few good questions is a refusal, and the allowance is given back', (study_quiz_ai($A + ['unitId' => 'CU-ST-1'])['error'] ?? '') === 'ai_no_quiz'
        && (int)db_row("SELECT stateValue FROM member_state WHERE memberId = 'NGG-ST-A' AND stateKey = ?", ['ai.tutor.' . gmdate('Y-m-d')])['stateValue'] === $u0);
    chk('quiz · a quiz score is logged as a study session', !empty(study_log($A + ['tool' => 'quiz', 'accuracy' => 80, 'cards' => 5, 'label' => 'Intervals'])));
    $GLOBALS['__ai_mock'] = function ($pr, $system, $turns) use (&$sys) { $sys = $turns[0]['text'] ?? ''; return ['ok' => true, 'provider' => 'mock', 'text' => json_encode(['summary' => 'Cells are the units of life.', 'terms' => [['term' => 'Cell', 'meaning' => 'The smallest unit of life'], ['term' => '', 'meaning' => 'dropped']]])]; };
    $notes = str_repeat('Cells are the smallest unit of life. The nucleus holds DNA. ', 3);
    $nr = study_notes_ai($A + ['text' => $notes]);
    chk('notes · my own notes are summarised, with key terms ready to become cards (empty ones dropped)', !empty($nr['ok']) && $nr['summary'] === 'Cells are the units of life.' && $nr['terms'] === [['front' => 'Cell', 'back' => 'The smallest unit of life']] && str_contains($sys, 'nucleus holds DNA'));
    chk('notes · a few words are not notes', (study_notes_ai($A + ['text' => 'too short'])['error'] ?? '') === 'notes_too_short');
    $u1 = (int)db_row("SELECT stateValue FROM member_state WHERE memberId = 'NGG-ST-A' AND stateKey = ?", ['ai.tutor.' . gmdate('Y-m-d')])['stateValue'];
    $sg = study_notes_ai($A + ['text' => $notes . ' Sometimes I want to hurt myself after school.']);
    chk('notes · notes that talk about being hurt get people to talk to, not a summary — and nothing is spent', !empty($sg['safeguarding']) && str_contains($sg['summary'], 'safeguarding')
        && (int)db_row("SELECT stateValue FROM member_state WHERE memberId = 'NGG-ST-A' AND stateKey = ?", ['ai.tutor.' . gmdate('Y-m-d')])['stateValue'] === $u1);
    chk('lessons · the member\'s division is given, so their course lab comes first', study_lessons($A)['division'] === 'Creative & Performing Arts' || study_lessons($A)['track'] === 'Piano');
    unset($GLOBALS['__ai_mock']);
    chk('flashcards · deleting a deck deletes its cards', !empty(study_deck_delete($A + ['deckId' => $deckId])['ok']) && (int)db_row("SELECT COUNT(*) n FROM study_cards WHERE deckId = ?", [$deckId])['n'] === 0);
    db_exec("DELETE FROM study_sessions WHERE memberId LIKE 'NGG-ST-%'"); db_exec("DELETE FROM study_decks WHERE memberId LIKE 'NGG-ST-%'"); db_exec("DELETE FROM study_cards WHERE memberId LIKE 'NGG-ST-%'");
    db_exec("DELETE FROM curriculum_units WHERE unitId = 'CU-ST-1'"); db_exec("DELETE FROM members WHERE memberId LIKE 'NGG-ST-%'"); db_exec("DELETE FROM member_state WHERE memberId LIKE 'NGG-ST-%'");
})();

/* NGG and Summer School name their own centre leads: different people. */
(function () {
    $A = 'NGG-2025-0099';
    db_insert('volunteers', ['volunteerId' => 'VOL-LD-N', 'fullName' => 'Nneka Club Lead', 'email' => 'ldn@example.com', 'role' => 'admin', 'status' => 'active', 'safeguarding' => 'cleared', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    db_insert('volunteers', ['volunteerId' => 'VOL-LD-S', 'fullName' => 'Sola Summer Lead', 'email' => 'lds@example.com', 'role' => 'admin', 'status' => 'active', 'safeguarding' => 'cleared', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    $r = backend_dispatch('admin.centres.upsert', ['requesterId' => $A, 'data' => ['name' => 'Leadsville', 'code' => 'LV', 'color' => '#76B043', 'programmes' => ['ngg', 'summer'],
        'leadVolunteerId' => 'VOL-LD-N', 'summerLeadVolunteerId' => 'VOL-LD-S']]);
    chk('centre saves with an NGG lead and a separate Summer lead', !empty($r['ok']));
    $row = null;
    foreach ((backend_dispatch('admin.centres.list', ['requesterId' => $A])['centres'] ?? []) as $c) if ($c['name'] === 'Leadsville') $row = $c;
    chk('directory reports each programme\'s own lead', $row && $row['leadName'] === 'Nneka Club Lead' && $row['summerLeadName'] === 'Sola Summer Lead');
    $c = db_row("SELECT * FROM centres WHERE name = 'Leadsville'");
    chk('public meta: the Summer page names the Summer lead, the Club the NGG lead',
        centre_public_meta($c, 'summer')['lead'] !== centre_public_meta($c, 'ngg')['lead']);
    chk('an unknown Summer lead is refused', (backend_dispatch('admin.centres.upsert', ['requesterId' => $A, 'data' => ['centreId' => $c['centreId'], 'name' => 'Leadsville', 'code' => 'LV', 'color' => '#76B043', 'summerLeadVolunteerId' => 'VOL-NOPE']])['error'] ?? '') === 'bad_lead');
    db_exec("DELETE FROM centres WHERE name = 'Leadsville'"); db_exec("DELETE FROM volunteers WHERE volunteerId IN ('VOL-LD-N','VOL-LD-S')");
})();

/* Club portal v3 (domain/club-portal.php): NGG centres only, scoped per row,
 * announcements wait for an admin, check-ins reach the mentor, fine caps hold. */
(function () {
    $now = now_iso();
    db_insert('centres', ['centreId' => 'CP-A', 'name' => 'Cpalpha', 'code' => 'CPA', 'color' => '#111111', 'status' => 'active', 'programmes' => 'ngg', 'meetDays' => 'Saturdays', 'meetTime' => '9am-2pm', 'createdAt' => $now, 'updatedAt' => $now]);
    db_insert('centres', ['centreId' => 'CP-B', 'name' => 'Cpbeta', 'code' => 'CPB', 'color' => '#222222', 'status' => 'active', 'programmes' => 'ngg,summer', 'meetDays' => 'Wednesdays', 'meetTime' => '5pm-7pm', 'createdAt' => $now, 'updatedAt' => $now]);
    db_insert('centres', ['centreId' => 'CP-S', 'name' => 'Cpsummer', 'code' => 'CPS', 'color' => '#333333', 'status' => 'active', 'programmes' => 'summer', 'createdAt' => $now, 'updatedAt' => $now]);
    $mk = static fn($id, $name, $role, $centre, $extra = []) => db_insert('members', array_merge(['memberId' => $id, 'fullName' => $name, 'email' => strtolower($id) . '@cp.example', 'type' => 'NGG', 'status' => 'active',
        'role' => $role, 'centre' => $centre, 'createdAt' => $now, 'updatedAt' => $now], $extra));
    $mk('CP-ADM', 'Ada Admin', 'admin', 'Cpalpha');
    $mk('CP-CLB', 'Cole Club', 'club_admin', 'Cpalpha');
    $mk('CP-LEAD', 'Lola Lead', 'centre_lead', 'Cpalpha', ['centreScope' => '["CP-A"]']);
    $mk('CP-M1', 'Tobi Alpha', 'member', 'Cpalpha', ['parentEmail' => 'p1@cp.example', 'parentName' => 'Mrs Alpha', 'track' => 'Coding']);
    $mk('CP-M2', 'Bimpe Beta', 'member', 'Cpbeta', ['parentEmail' => 'p2@cp.example', 'track' => 'Robotics']);
    $mk('CP-M3', 'Gone Quiet', 'member', 'Cpalpha', ['status' => 'inactive']);

    $boot = fn($who) => backend_dispatch('admin.clubp.boot', ['requesterId' => $who]);
    $names = fn($r) => array_column($r['centres'] ?? [], 'name');
    chk('club portal: a club admin covers every NGG centre, never a Summer-only venue',
        in_array('Cpalpha', $names($boot('CP-CLB')), true) && in_array('Cpbeta', $names($boot('CP-CLB')), true) && !in_array('Cpsummer', $names($boot('CP-CLB')), true));
    chk('club portal: a centre lead covers their own centre only', $names($boot('CP-LEAD')) === ['Cpalpha'] && !empty($boot('CP-LEAD')['me']['scoped']));
    $a = null; foreach ($boot('CP-CLB')['centres'] as $c) if ($c['name'] === 'Cpalpha') $a = $c;
    chk('club portal: a centre reads its days and hours from its meeting text', $a && $a['days'] === [6] && $a['open'] === '09:00' && $a['close'] === '14:00');
    chk('club portal: a summer coordinator is refused', empty(backend_dispatch('admin.clubp.boot', ['requesterId' => 'NGG-2025-0099']) ['ok']) === false);

    $d = backend_dispatch('admin.clubp.dashboard', ['requesterId' => 'CP-LEAD']);
    chk('club portal: dashboard counts only the lead\'s centre', !empty($d['ok']) && ($d['memberStats']['byStatus'][0][1] ?? -1) === 1 && isset($d['centreStats']['CP-A']) && !isset($d['centreStats']['CP-B']));
    chk('club portal: dashboard counts active members missing a required permission', ($d['counts']['permissionsMissing'] ?? 0) === 1);

    // Permissions: recorded through the member desk's op, and scoped on the way in.
    $r = backend_dispatch('admin.clubp.consent.set', ['requesterId' => 'CP-LEAD', 'memberId' => 'CP-M2', 'type' => 'participation', 'v' => 'g', 'method' => 'Paper form']);
    chk('club portal: a lead cannot record a permission at another centre', ($r['error'] ?? '') === 'out_of_scope');
    foreach (['participation', 'medical', 'data'] as $t) backend_dispatch('admin.clubp.consent.set', ['requesterId' => 'CP-LEAD', 'memberId' => 'CP-M1', 'type' => $t, 'v' => 'g', 'method' => 'Paper form']);
    $c = backend_dispatch('admin.clubp.consents', ['requesterId' => 'CP-LEAD']);
    $row = null; foreach ($c['rows'] ?? [] as $x) if ($x['id'] === 'CP-M1') $row = $x;
    chk('club portal: recorded permissions read back, with the guardian', $row && ($row['consent']['medical']['v'] ?? '') === 'g' && $row['consent']['guardian'] === 'Mrs Alpha' && ($c['totals']['missingRequired'] ?? -1) === 0);

    // Check-ins: a struggling member reaches their mentor; "seen" hides it.
    db_insert('mentors', ['mentorId' => 'CP-MEN', 'fullName' => 'Mo Mentor', 'email' => 'mo@cp.example', 'status' => 'active', 'centre' => 'Cpalpha', 'createdAt' => $now, 'updatedAt' => $now]);
    db_insert('mentor_assignments', ['memberId' => 'CP-M1', 'mentorId' => 'CP-MEN', 'status' => 'active', 'startedAt' => $now]);
    db_insert('member_checkins', ['memberId' => 'CP-M1', 'week' => '2026-W42', 'wellbeing' => 'Struggling', 'note' => 'Exams', 'createdAt' => $now]);
    $ci = backend_dispatch('admin.clubp.checkins', ['requesterId' => 'CP-CLB'])['checkins'] ?? [];
    $one = null; foreach ($ci as $x) if ($x['memberId'] === 'CP-M1') $one = $x;
    chk('club portal: a struggling check-in shows as low, with the mentor', $one && $one['tone'] === 'bad' && $one['mentor'] === 'Mo Mentor' && !$one['told']);
    $t = backend_dispatch('admin.clubp.checkin', ['requesterId' => 'CP-CLB', 'id' => 'CP-M1|2026-W42', 'act' => 'tell']);
    chk('club portal: telling the mentor is recorded', !empty($t['ok']) && $t['mentor'] === 'Mo Mentor' && (string)db_row("SELECT toldAt FROM club_checkin_state WHERE checkinKey = 'CP-M1|2026-W42'")['toldAt'] !== '');
    backend_dispatch('admin.clubp.checkin', ['requesterId' => 'CP-CLB', 'id' => 'CP-M1|2026-W42', 'act' => 'seen']);
    $ids = array_column(backend_dispatch('admin.clubp.checkins', ['requesterId' => 'CP-CLB'])['checkins'] ?? [], 'memberId');
    chk('club portal: a check-in marked seen leaves the list, and undo brings it back', !in_array('CP-M1', $ids, true)
        && !empty(backend_dispatch('admin.clubp.checkin', ['requesterId' => 'CP-CLB', 'id' => 'CP-M1|2026-W42', 'act' => 'unseen'])['ok'])
        && in_array('CP-M1', array_column(backend_dispatch('admin.clubp.checkins', ['requesterId' => 'CP-CLB'])['checkins'], 'memberId'), true));

    // Announcements: a coordinator's waits; an admin approves and it goes out.
    $s1 = backend_dispatch('admin.clubp.ann.save', ['requesterId' => 'CP-CLB', 'action' => 'submit', 'ann' => ['title' => 'No class', 'body' => 'Closed for the holiday.', 'aud' => 'members', 'centre' => 'Cpalpha', 'ch' => ['app']]]);
    chk('club portal: a coordinator\'s announcement waits for approval', !empty($s1['ok']) && $s1['announcement']['status'] === 'pending' && empty($s1['stats']));
    $no = backend_dispatch('admin.clubp.ann.save', ['requesterId' => 'CP-CLB', 'action' => 'approve', 'ann' => ['id' => $s1['announcement']['id']]]);
    chk('club portal: a coordinator cannot approve one', ($no['error'] ?? '') === 'forbidden');
    $sb = backend_dispatch('admin.clubp.ann.save', ['requesterId' => 'CP-ADM', 'action' => 'sendback', 'ann' => ['id' => $s1['announcement']['id']]]);
    chk('club portal: sending back needs a note', ($sb['error'] ?? '') === 'note_required');
    $ap = backend_dispatch('admin.clubp.ann.save', ['requesterId' => 'CP-ADM', 'action' => 'approve', 'ann' => ['id' => $s1['announcement']['id']]]);
    chk('club portal: an admin approves and it goes out to the centre\'s members only', !empty($ap['ok']) && $ap['announcement']['status'] === 'sent' && ($ap['stats']['app'] ?? 0) === 1
        && (bool)db_row("SELECT id FROM notifications WHERE memberId = 'CP-M1' AND title = 'No class'") && !db_row("SELECT id FROM notifications WHERE memberId = 'CP-M2' AND title = 'No class'"));
    $ld = backend_dispatch('admin.clubp.ann.save', ['requesterId' => 'CP-LEAD', 'action' => 'draft', 'ann' => ['title' => 'x', 'body' => 'y', 'centre' => 'all', 'ch' => ['app']]]);
    chk('club portal: a lead\'s announcement is held to their own centre', !empty($ld['ok']) && $ld['announcement']['centre'] === 'Cpalpha');
