    $reg = $q(['view' => 'register', 'rf' => 'absent', 'date' => gmdate('Y-m-d', strtotime(attendance_today() . ' -1 days'))]);
    chk('ss3 · the register names who was not in on a day', $reg['kpis']['absent'] === 1 && $reg['list'][0]['id'] === 'SS3-K-002');

