    chk('journal · …and the reading is on the record', (bool)db_row("SELECT 1 FROM audit_log WHERE event = 'mentor.journal.read' AND subject = 'ANC-KID'"));
    chk('journal · not a mentor of another child', (backend_dispatch('member.mentor.journal', ['requesterId' => 'ANC-M2', 'subjectId' => 'ANC-KID'])['error'] ?? '') === 'not_in_caseload'
        && (backend_dispatch('member.mentor.journal', ['requesterId' => 'ANC-M', 'subjectId' => 'ANC-OTHER'])['error'] ?? '') === 'not_in_caseload');
    db_exec("UPDATE mentors SET kind = 'peer' WHERE mentorId = 'ANCT-1'");
    chk('journal · never a peer mentor, even an assigned one', (backend_dispatch('member.mentor.journal', ['requesterId' => 'ANC-M', 'subjectId' => 'ANC-KID'])['error'] ?? '') === 'peer_no_journal');
    db_exec("UPDATE mentors SET kind = '' WHERE mentorId = 'ANCT-1'");
    $pg = backend_dispatch('member.mentor.journal', ['requesterId' => 'ANC-M', 'subjectId' => 'ANC-KID', 'before' => 2]);
    chk('journal · pages on from where the mentor is', array_column($pg['entries'], 'entryId') === ['ANC-J3'] && $pg['more'] === false);
    db_exec("DELETE FROM journal WHERE memberId LIKE 'ANC-%'");
    $ls = backend_dispatch('member.mentor.child.lessons', ['requesterId' => 'ANC-M', 'subjectId' => 'ANC-KID']);
    chk('lessons · the assigned mentor gets the mentee\'s lessons, gated like Growth', !empty($ls['ok']) && array_key_exists('curriculum', $ls));
    /* A mentor whose own record names another centre (they mentor across
       centres) is refused by the older record gate (not_your_centre) while
       Growth, gated by the assignment, opens: Lessons must follow Growth. */
    db_exec("UPDATE mentors SET centre = 'Elsewhere' WHERE mentorId = 'ANCT-1'");
    chk('lessons · a mentor based at another centre still gets their mentee\'s lessons, as Growth does', !empty(backend_dispatch('member.mentor.child.lessons', ['requesterId' => 'ANC-M', 'subjectId' => 'ANC-KID'])['ok'])
        && !empty(backend_dispatch('member.mentor.growth', ['requesterId' => 'ANC-M', 'subjectId' => 'ANC-KID'])['ok']));
    db_exec("UPDATE mentors SET centre = 'Anchorville' WHERE mentorId = 'ANCT-1'");
    chk('lessons · …and a mentor of another child does not', empty(backend_dispatch('member.mentor.child.lessons', ['requesterId' => 'ANC-M2', 'subjectId' => 'ANC-KID'])['ok']));
    db_exec("UPDATE mentor_assignments SET status = 'ended' WHERE memberId = 'ANC-KID'");
    chk('anchor · when the assignment ends, so does the connection', (backend_dispatch('member.mentor.anchor', ['requesterId' => 'ANC-M', 'subjectId' => 'ANC-KID'])['error'] ?? '') === 'not_in_caseload'
        && backend_dispatch('member.circle', ['requesterId' => 'ANC-KID'])['circle']['mentor'] === false);
    $wipe();
})();

// ── Wi-Fi: NGG's people and its say, sent to CACENTRE (domain/wifi-cacentre.php) ──
(function () {
    $now = now_iso(); $C = 'Cac Push Centre';
    db_insert('centres', ['centreId' => 'CEN-CACP', 'name' => $C, 'code' => 'CP', 'status' => 'active']);
    $mem = fn(string $id, array $x) => db_insert('members', array_merge(['memberId' => $id, 'fullName' => 'Cac ' . $id, 'email' => strtolower($id) . '@Example.com', 'type' => 'NGG',
        'status' => 'active', 'role' => 'member', 'centre' => $C, 'createdAt' => $now, 'updatedAt' => $now], $x));
    $mem('NGG-CP-ACT', ['displayId' => '026-701']);
    $mem('NGG-CP-SUS', ['displayId' => '026-702', 'status' => 'suspended']);
    $mem('NGG-CP-OVR', ['displayId' => '026-703']);
    $mem('NGG-CP-MEN', ['displayId' => '026-704', 'role' => 'mentor']);
    $mem('SUM-CP-1', ['type' => 'Summer', 'role' => 'member']);
    $today = attendance_today();
    db_insert('summer_cohorts', ['cohortId' => 'CP-LIVE', 'name' => 'Cac live', 'status' => 'active', 'startDate' => gmdate('Y-m-d', strtotime($today . ' -2 days')), 'endDate' => gmdate('Y-m-d', strtotime($today . ' +10 days')), 'createdAt' => $now]);
    db_insert('summer_students', ['studentId' => 'SS-CP-1', 'cohortId' => 'CP-LIVE', 'fullName' => 'Cac Participant', 'centre' => $C, 'status' => 'active', 'displayId' => 'CP-26-001']);
    db_insert('wifi_accounts', ['subjectType' => 'member', 'subjectId' => 'NGG-CP-OVR', 'username' => '026-703', 'pinSealed' => wifi_pin_seal('123456'), 'override' => 'off',
        'pinSetAt' => $now, 'createdAt' => $now, 'updatedAt' => $now]);

    $all = []; foreach (wifi_cac_people() as $r) $all[$r['id']] = $r;
    $p = fn($id) => $all[$id] ?? [];
    chk('wifi→cacentre · an active member goes as an NGG member, on, at their centre’s card code', ($p('NGG-CP-ACT')['kind'] ?? '') === 'member' && $p('NGG-CP-ACT')['verdict'] === 'on'
        && $p('NGG-CP-ACT')['homeSite'] === 'cp' && $p('NGG-CP-ACT')['printedId'] === '026-701'
        && ($p('NGG-CP-ACT')['why'] ?? '') === '' && $p('NGG-CP-ACT')['email'] === 'ngg-cp-act@example.com');
    chk('wifi→cacentre · a suspension here is NGG saying off, with the reason in words', ($p('NGG-CP-SUS')['verdict'] ?? '') === 'off' && $p('NGG-CP-SUS')['why'] === WIFI_CASE_WORDS['blocked']);
    chk('wifi→cacentre · a hand-set override here travels as NGG’s say', ($p('NGG-CP-OVR')['verdict'] ?? '') === 'off' && $p('NGG-CP-OVR')['why'] === WIFI_CASE_WORDS['override']);
    chk('wifi→cacentre · a mentor goes as staff, with no home site (staff sign in anywhere)',
        ($p('NGG-CP-MEN')['kind'] ?? '') === 'staff' && ($p('NGG-CP-MEN')['homeSite'] ?? '') === '');
    chk('wifi→cacentre · a participant goes within their edition, until its end date', ($p('summer-SS-CP-1')['kind'] ?? '') === 'participant' && $p('summer-SS-CP-1')['verdict'] === 'on'
        && $p('summer-SS-CP-1')['validUntil'] === gmdate('Y-m-d', strtotime($today . ' +10 days')) && $p('summer-SS-CP-1')['printedId'] === 'CP-26-001');
    chk('wifi→cacentre · a Summer-type member record is not sent as a member', !isset($all['SUM-CP-1']));
    /* The PROPERTY, not a fixed list: an empty field may be left out (absent
       and empty are the same to CACENTRE, and the roster is paged by bytes),
       but a field outside the agreed set may never appear. Pinning the exact
       list would fail for a reason that has nothing to do with privacy. */
    $agreed = ['id', 'kind', 'name', 'email', 'printedId', 'homeSite', 'homeLocation', 'homeName', 'verdict', 'why', 'validUntil'];
    $keys = []; foreach ($all as $r) $keys += array_flip(array_keys($r));
    chk('wifi→cacentre · only the agreed fields travel: no phone, birthday, guardian or money'
        . (($x = array_diff(array_keys($keys), $agreed)) ? ' — ' . implode(', ', $x) : ''), !$x);
    /* The place travels with the code: NGG's centre code is not CACENTRE's site
       code, and the code alone left whole centres "with no site". */
    $cpRow = $p('NGG-CP-ACT');
    $cpCentre = db_row("SELECT cacLocationId FROM centres WHERE code = 'CP' OR LOWER(code) = 'cp' LIMIT 1");
    chk('wifi→cacentre · each row names its place as well as its code (location id when linked, else the centre name)',
        ($cpRow['homeSite'] ?? '') === 'cp' && ((string)($cpCentre['cacLocationId'] ?? '') !== '' ? ($cpRow['homeLocation'] ?? '') === (string)$cpCentre['cacLocationId'] : ($cpRow['homeName'] ?? '') !== ''));
    chk('wifi→cacentre · staff carry no place', !isset($p('NGG-CP-MEN')['homeName']) && !isset($p('NGG-CP-MEN')['homeLocation']));
    chk('wifi→cacentre · and the three that decide anything are always there',
        !array_filter($all, fn($r) => !isset($r['id'], $r['kind'], $r['verdict'])));

    // The call: what the gate (gate/src/wifi.ts) checks, re-done here — NGG's own attendance scheme.
    $sec = str_repeat('k', 40); $t0 = 1800000000;
    $rq = wifi_cac_request('wifi.roster', ['full' => true, 'people' => [$p('NGG-CP-ACT')]], $sec, $t0);
    $hd = []; foreach ($rq['headers'] as $h) { [$k, $v] = explode(': ', $h, 2); $hd[$k] = $v; }
    $c = json_decode($rq['body'], true);
    chk('wifi→cacentre · the roster rides the attendance connection: to the gate, signed sha256=HMAC(attendance secret, ts.body)',
        str_ends_with($rq['url'], '/v1/issuers/ngg/wifi') && $hd['X-NGG-Timestamp'] === (string)$t0
        && hash_equals('sha256=' . hash_hmac('sha256', $t0 . '.' . $rq['body'], $sec), $hd['X-NGG-Signature'])
        && $c['typ'] === 'wifi.roster' && $c['full'] === true && $c['people'][0]['id'] === 'NGG-CP-ACT');
    chk('wifi→cacentre · two identical calls are never the same signature (the gate spends each once)',
        wifi_cac_request('wifi.card', ['op' => 'show', 'id' => 'x'], $sec, $t0)['body'] !== wifi_cac_request('wifi.card', ['op' => 'show', 'id' => 'x'], $sec, $t0)['body']);

    // One connection: the Wi-Fi is on exactly when attendance is, with its secret.
    $GLOBALS['CONFIG']['hooks']['attendance_secret'] = '';
    chk('wifi→cacentre · with no attendance secret nothing is sent', (wifi_cac_push('test')['error'] ?? '') === 'not_configured' && (wifi_cac_tick()['skipped'] ?? '') === 'no key');
    $GLOBALS['CONFIG']['hooks']['attendance_secret'] = 'short';
    chk('wifi→cacentre · a secret too short to be one counts as none', !wifi_cac_ready());
    $GLOBALS['CONFIG']['dir_push_secret'] = str_repeat('d', 40);
    chk('wifi→cacentre · the directory key opens no Wi-Fi: only the attendance secret does', !wifi_cac_ready());
    $GLOBALS['CONFIG']['hooks']['attendance_secret'] = str_repeat('a', 40);
    chk('wifi→cacentre · the attendance secret IS the Wi-Fi’s: there is no second one', wifi_cac_ready());
    // A roster too big for one request goes in parts that share one sync id, so CACENTRE can withdraw people.
    $sent = [];
    $GLOBALS['__wifi_cac_post_mock'] = function ($typ, $claims) use (&$sent) {
        $sent[] = $claims; $sy = $claims['sync'] ?? null;
        return ['ok' => true, 'applied' => count($claims['people']), 'refused' => 0, 'gone' => 0,
                'sync' => $sy ? ['complete' => !empty($sy['last'])] : null];
    };
    $keepMax = $GLOBALS['CONFIG']['wifi']['cac_body_max'] ?? null;
    $GLOBALS['CONFIG']['wifi']['cac_body_max'] = 4096;
    $pr = wifi_cac_push('test');
    $ids = array_unique(array_map(fn($c) => $c['sync']['id'] ?? '', $sent));
    $nParts = count($sent);
    chk('wifi→cacentre · a paged roster: every part carries the same sync id and its place, n of N', $nParts > 1 && count($ids) === 1 && reset($ids) !== ''
        && array_map(fn($c) => $c['sync']['part'], $sent) === range(1, $nParts) && array_map(fn($c) => $c['sync']['last'], $sent) === array_merge(array_fill(0, $nParts - 1, false), [true])
        && !in_array(true, array_map(fn($c) => $c['full'], $sent), true));
    chk('…and when CACENTRE confirms the set complete, the push says so and makes no "nobody withdrawn" note', !empty($pr['synced']) && !isset($pr['note']));
    $sent = [];
    $GLOBALS['__wifi_cac_post_mock'] = fn($typ, $claims) => ['ok' => true, 'applied' => count($claims['people']), 'refused' => 0, 'gone' => 0];
    $pr = wifi_cac_push('test');
    chk('…but a CACENTRE that does not read sync yet is reported honestly: nobody was withdrawn', empty($pr['synced']) && str_contains((string)($pr['note'] ?? ''), 'nobody was withdrawn'));
    // CACENTRE's host firewall answering 406: the part is halved until it goes through, and one person refused alone is named, not the whole list lost.
    $GLOBALS['CONFIG']['wifi']['cac_body_max'] = 1 << 20;
    $bad = wifi_cac_people()[0]['id'] ?? '';
    $sent = [];
    $GLOBALS['__wifi_cac_post_mock'] = function ($typ, $claims) use (&$sent, $bad) {
        if (count($claims['people']) > 40 || in_array($bad, array_column($claims['people'], 'id'), true)) return ['ok' => false, 'error' => 'CACENTRE answered 406.', 'http' => 406];
        $sent[] = $claims; return ['ok' => true, 'applied' => count($claims['people']), 'refused' => 0, 'gone' => 0, 'sync' => ['complete' => !empty($claims['sync']['last'])]];
    };
    $pr = wifi_cac_push('test');
    $through = array_merge(...array_map(fn($c) => array_column($c['people'], 'id'), $sent ?: [['people' => []]]));
    chk('wifi→cacentre · a 406 from CACENTRE’s host splits the list until each part goes through; everybody else arrives', $pr['ok'] && count($through) === count(wifi_cac_people()) - 1 && !in_array($bad, $through, true));
    chk('…the one person refused even alone is named, and nothing is called complete (nobody withdrawn)', $pr['firewalled'] === [$bad] && empty($pr['synced'])
        && !in_array(true, array_map(fn($c) => $c['sync']['last'], $sent), true) && str_contains((string)$pr['note'], $bad));
    chk('…and the parts that went through are numbered 1..n in order', array_map(fn($c) => $c['sync']['part'], $sent) === range(1, count($sent)));
    unset($GLOBALS['__wifi_cac_post_mock']);
    if ($keepMax === null) unset($GLOBALS['CONFIG']['wifi']['cac_body_max']); else $GLOBALS['CONFIG']['wifi']['cac_body_max'] = $keepMax;
    // Only a live record is a member: deleted, merged and unknown statuses are blocked, not "on".
    foreach (['deleted', 'merged', 'pending', 'weird-import'] as $stz) {
        $dz = wifi_access_for(['memberId' => 'NGG-WX-' . $stz, 'type' => 'NGG', 'status' => $stz, 'role' => 'member'], ['usage' => null, 'policy' => null]);
        chk('wifi · a member whose record is ' . $stz . ' has no Wi-Fi (blocked, not the member default)', $dz['case'] === 'blocked' && $dz['access'] === 'off');
    }
    $dz = wifi_access_for(['memberId' => 'NGG-WX-act', 'type' => 'NGG', 'status' => 'active', 'role' => 'member'], ['usage' => null, 'policy' => null]);
    chk('wifi · an active member still gets the member case', $dz['case'] === 'member');
    $GLOBALS['CONFIG']['dir_push_secret'] = '';

    // Members keep their PIN on their own dashboard. A centre whose NGG router still fetches keeps NGG's PIN;
    // once it has moved, Me → Wi-Fi asks CACENTRE — and says so honestly when CACENTRE can't be reached.
    $GLOBALS['CONFIG']['dir_push_url'] = 'http://127.0.0.1:9';   // nothing listens there
    db_insert('wifi_gateways', ['gatewayId' => 'GCP000001', 'centre' => $C, 'platform' => 'mikrotik', 'label' => 'Still on NGG', 'keyHash' => 'x', 'createdAt' => $now, 'lastSeenAt' => $now]);
    chk('wifi→cacentre · while the centre’s router still fetches from NGG, the member sees NGG’s PIN', !wifi_cac_serves($C, false)
        && (backend_dispatch('member.wifi.get', ['memberId' => 'NGG-CP-ACT'])['wifi']['username'] ?? '') === '026-701');
    db_exec("UPDATE wifi_gateways SET lastSeenAt = ? WHERE gatewayId = 'GCP000001'", [gmdate('Y-m-d\\TH:i:s', time() - 3 * 86400)]);
    $g = backend_dispatch('member.wifi.get', ['memberId' => 'NGG-CP-ACT']);
    chk('wifi→cacentre · once it has moved, the dashboard asks CACENTRE, and an outage is an honest error, never NGG’s stale PIN', wifi_cac_serves($C, false)
        && empty($g['ok']) && ($g['error'] ?? '') === 'cacentre_unreachable' && !isset($g['wifi']));
    db_exec("DELETE FROM wifi_gateways WHERE gatewayId = 'GCP000001'");
    $GLOBALS['CONFIG']['hooks']['attendance_secret'] = ''; $GLOBALS['CONFIG']['dir_push_url'] = '';

    // Who may: the status for anybody with network; sending only for somebody who sees every centre.
    $mem('NGG-CP-SA', ['role' => 'super_admin']);
    $mem('NGG-CP-ADM', ['role' => 'admin']);
    $st = backend_dispatch('admin.wifi.cacentre', ['requesterId' => 'NGG-CP-SA']);
    chk('wifi→cacentre · the status says whether it is set up, and that a super admin may send', !empty($st['ok']) && $st['configured'] === false && $st['canSend'] === true);
    chk('wifi→cacentre · an admin without network sees neither', (backend_dispatch('admin.wifi.cacentre', ['requesterId' => 'NGG-CP-ADM'])['error'] ?? '') === 'forbidden'
        && (backend_dispatch('admin.wifi.cacentre.push', ['requesterId' => 'NGG-CP-ADM'])['error'] ?? '') === 'forbidden');
    // Moving a router to CACENTRE.
    $sv = backend_dispatch('admin.wifi.gateway.save', ['requesterId' => 'NGG-CP-SA', 'platform' => 'mikrotik', 'centre' => $C, 'label' => 'Moving router']);
    $mg = $sv['gateway']['gatewayId']; $mk = $sv['key'];
    backend_dispatch('wifi.feed', ['gatewayId' => $mg, 'key' => $mk, 'since' => 0]);
    chk('wifi→cacentre · a router can’t be marked moved before NGG is connected', (backend_dispatch('admin.wifi.gateway.moved', ['requesterId' => 'NGG-CP-SA', 'gatewayId' => $mg])['error'] ?? '') === 'cacentre_not_connected');
    $GLOBALS['CONFIG']['hooks']['attendance_secret'] = str_repeat('a', 40);
    chk('wifi→cacentre · while it still fetches from NGG, its members keep NGG’s PIN', !wifi_cac_serves($C, false));
    $mv = backend_dispatch('admin.wifi.gateway.moved', ['requesterId' => 'NGG-CP-SA', 'gatewayId' => $mg]);
    chk('wifi→cacentre · marked moved, its members see CACENTRE’s PIN at once, not a day later', !empty($mv['ok']) && $mv['gateway']['movedAt'] !== '' && wifi_cac_serves($C, false));
    chk('wifi→cacentre · NGG stops watching it: one line, “Runs from CACENTRE”', count($mv['gateway']['diagnosis']) === 1 && $mv['gateway']['diagnosis'][0]['title'] === 'Runs from CACENTRE' && $mv['gateway']['health'] === 'ok');
    chk('wifi→cacentre · if NGG’s script is still on it, it is told it moved — never sent an empty list', (backend_dispatch('wifi.feed', ['gatewayId' => $mg, 'key' => $mk, 'since' => 0])['error'] ?? '') === 'moved_to_cacentre');
    db_exec("UPDATE wifi_gateways SET lastSeenAt = ? WHERE gatewayId = ?", [gmdate('Y-m-d\\TH:i:s\\Z', time() - 6 * 3600), $mg]);
    $dg = wifi_silent_digest();
    chk('wifi→cacentre · a moved router going quiet is not reported silent', !in_array($mg, array_column(db_all("SELECT gatewayId FROM wifi_gateways WHERE silentAlertAt <> ''"), 'gatewayId'), true));
    $bk = backend_dispatch('admin.wifi.gateway.moved', ['requesterId' => 'NGG-CP-SA', 'gatewayId' => $mg, 'undo' => true]);
    $f2 = backend_dispatch('wifi.feed', ['gatewayId' => $mg, 'key' => $mk, 'since' => 1]);
    chk('wifi→cacentre · back to NGG: it is fed again, with a full list', !empty($bk['ok']) && $bk['gateway']['movedAt'] === '' && !empty($f2['ok']) && !empty($f2['full']));
    chk('wifi→cacentre · marking it twice changes nothing', !empty(backend_dispatch('admin.wifi.gateway.moved', ['requesterId' => 'NGG-CP-SA', 'gatewayId' => $mg, 'undo' => true])['unchanged']));
    db_exec("DELETE FROM wifi_gateways WHERE gatewayId = ?", [$mg]);
    // The starting-password list is admin-only, and asks nothing of CACENTRE until NGG is connected.
    chk('wifi→cacentre · an admin without network cannot see starting passwords', (backend_dispatch('admin.wifi.cacentre.starts', ['requesterId' => 'NGG-CP-ADM'])['error'] ?? '') === 'forbidden');
    $GLOBALS['CONFIG']['hooks']['attendance_secret'] = '';
    chk('wifi→cacentre · before attendance is connected the list says so', (backend_dispatch('admin.wifi.cacentre.starts', ['requesterId' => 'NGG-CP-SA'])['error'] ?? '') === 'not_configured');
    $hook = (string)file_get_contents(__DIR__ . '/../hooks/wifi-feed.php');
    $set = (string)file_get_contents(__DIR__ . '/../_lib/domain/wifi-setup.php');
    chk('wifi · a MikroTik is refused with 200, which RouterOS keeps (it drops a 4xx body); others keep the status', str_contains($hook, "\$ros ? 200 :"));
    chk('wifi · …and NGG’s script logs the reason (bad_key, moved_to_cacentre), not “incomplete”', str_contains($set, ':if ([:pick \\$d 0 7] = "#error;") do={ :set ok false; :set nggWifiErr'));
    db_exec("DELETE FROM wifi_accounts WHERE subjectId = 'NGG-CP-OVR'");
    db_exec("DELETE FROM summer_students WHERE studentId = 'SS-CP-1'"); db_exec("DELETE FROM summer_cohorts WHERE cohortId = 'CP-LIVE'");
    db_exec("DELETE FROM members WHERE memberId LIKE 'NGG-CP-%' OR memberId = 'SUM-CP-1'"); db_exec("DELETE FROM centres WHERE centreId = 'CEN-CACP'");
})();

/* ══ Consent: withdrawing one, and the ledger being READ the way it is
      WRITTEN ══════════════════════════════════════════════════════════════

   Two findings from the 27 October audit, and the second is the one that
   mattered. The bulk action sent `withdrawn` while consent_record() took
   only granted|declined, so a withdrawal failed on every row with no
   usable reason. Fixing that alone would have been worse than leaving it:
   `consents` is an append-only ledger, and two readers matched ANY granted
   row ever rather than the latest — so a withdrawal would have been
   accepted, recorded, and then ignored by the screens that act on it,
   which is the one failure mode a consent system must not have. */
(function () {
    $mid = 'CW-' . bin2hex(random_bytes(3));
    db_insert('members', ['memberId' => $mid, 'fullName' => 'Withdraw Test', 'role' => 'member',
        'status' => 'active', 'type' => 'NGG', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);

    $latest = fn() => (string)(consent_state($mid)['site_visibility']['status'] ?? '');
    $inNoConsentSegment = function () use ($mid): bool {
        [$sql, $args] = member_segment_sql('no_consent');
        $rows = db_all("SELECT memberId FROM members WHERE $sql", $args);
        return in_array($mid, array_column($rows, 'memberId'), true);
    };

    chk('consent: a withdrawal is a status in its own right, not a synonym for declined',
        consent_record($mid, 'site_visibility', 'granted', 'form', 'T')['ok']
        && consent_record($mid, 'site_visibility', 'withdrawn', 'staff', 'T')['ok']
        && $latest() === 'withdrawn');

    /* "Never agreed" and "agreed and then took it back" are different
       facts to a family and different facts in law — only the second
       means data was lawfully collected and must now stop being used. */
    chk('consent: declined and withdrawn are both kept, and are not the same row',
        (int)db_row("SELECT COUNT(DISTINCT status) c FROM consents WHERE studentId = ?", [$mid])['c'] === 2);

    chk('consent: a status the ledger does not know is still refused',
        (consent_record($mid, 'site_visibility', 'maybe', 'staff', 'T')['error'] ?? '') === 'bad_status');

    /* The real one. The segment that finds people whose photo may not be
       shown read the whole ledger, so it was blind to everybody who had
       ever granted — which is exactly the group that changes its mind. */
    chk('consent: withdrawing puts somebody back into the "no consent" segment',
        $inNoConsentSegment());

    chk('consent: granting again takes them out of it', (function () use ($mid, $inNoConsentSegment) {
        consent_record($mid, 'site_visibility', 'granted', 'form', 'T');
        return !$inNoConsentSegment();
    })());

    chk('consent: and declining after that puts them back', (function () use ($mid, $inNoConsentSegment) {
        consent_record($mid, 'site_visibility', 'declined', 'form', 'T');
        return $inNoConsentSegment();
    })());

    /* The bulk action and the ledger name one list between them. They
       named two, which is how a withdrawal cleared the first and was
       refused by the second on every row. */
    chk('consent: the bulk action accepts exactly what the ledger accepts',
        str_contains((string)file_get_contents(dirname(__DIR__) . '/_lib/domain/members-bulk.php'), 'CONSENT_STATUSES')
        && CONSENT_STATUSES === ['granted', 'declined', 'withdrawn']);

    chk('consent: a bulk withdrawal is no longer refused before it starts', (function () use ($mid) {
        $r = admin_members_bulk(['requesterId' => 'SUPER', 'action' => 'consent', 'ids' => [$mid],
            'consentType' => 'media', 'consentStatus' => 'withdrawn']);
        /* It may still refuse for a reason of its own — rights, scope —
           but never again with bad_consent, which meant "that word is
           not a word" for a word the screen itself sends. */
        return ($r['error'] ?? '') !== 'bad_consent';
    })());

    db_exec('DELETE FROM consents WHERE studentId = ?', [$mid]);
    db_exec('DELETE FROM members WHERE memberId = ?', [$mid]);
})();

/* ══ Erasing a member, and the one record it deliberately keeps ════════

   The 27 October audit listed the surviving volunteer record as a gap.
   It is not: a volunteer record is the record that this adult was vetted
   and supervised children, and for safeguarding that has to outlive the
   account. The right to erasure yields where there is an overriding
   obligation, and deleting it on request would let somebody remove the
   only evidence that they were ever there.

   What WAS wrong is that the code said nothing, so a retention nobody
   decided looks identical to one nobody noticed. These pin both halves:
   the member really is erased, and the thing that is kept is counted and
   named rather than left behind quietly. */
(function () {
    $mid = 'ER-' . bin2hex(random_bytes(3));
    db_insert('members', ['memberId' => $mid, 'fullName' => 'Vee Teacher', 'role' => 'member',
        'status' => 'active', 'type' => 'NGG', 'email' => 'vee@example.org', 'phone' => '08030000000',
        'photoUrl' => '/u/vee.jpg', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    db_insert('volunteers', ['volunteerId' => 'V-' . $mid, 'memberId' => $mid, 'fullName' => 'Vee Teacher',
        'email' => 'vee@example.org', 'phone' => '08030000000', 'role' => 'Instructor', 'status' => 'active']);

    $r = member_erase($mid, 'SUPER', '127.0.0.1');

    chk('erase: the member record itself is scrubbed', !empty($r['ok']) && (function () use ($mid) {
        $m = db_row('SELECT fullName, email, phone, photoUrl, status FROM members WHERE memberId = ?', [$mid]);
        return $m && (string)$m['fullName'] === 'Deleted member' && (string)$m['email'] === ''
            && (string)$m['phone'] === '' && (string)$m['photoUrl'] === '' && (string)$m['status'] === 'deleted';
    })());

    /* Kept on purpose. If somebody "fixes" this by deleting the row, this
       is the test that should stop them and send them to the comment. */
    chk('erase: a linked volunteer record SURVIVES — it is a safeguarding record, not a copy of the member',
        (int)db_row('SELECT COUNT(*) c FROM volunteers WHERE memberId = ?', [$mid])['c'] === 1);

    chk('erase: and the caller is told what was kept, rather than left to find out',
        ($r['volunteerRecordsKept'] ?? 0) === 1);

    /* So the person asking to be forgotten can be told exactly what was
       kept and why, and an auditor sees a decision rather than a miss. */
    chk('erase: the retention is on the audit trail, with its reason', (function () use ($mid) {
        $row = db_row("SELECT meta FROM audit_log WHERE event = 'member.erase' AND subject = ? ORDER BY id DESC LIMIT 1", [$mid]);
        $meta = $row ? json_decode((string)$row['meta'], true) : null;
        return is_array($meta) && ($meta['volunteerRecordsKept'] ?? 0) === 1
            && str_contains((string)($meta['why'] ?? ''), 'Safeguarding');
    })());

    /* A member who never volunteered has nothing kept, and the audit row
       does not imply otherwise. */
    $plain = 'ER2-' . bin2hex(random_bytes(3));
    db_insert('members', ['memberId' => $plain, 'fullName' => 'Just Member', 'role' => 'member',
        'status' => 'active', 'type' => 'NGG', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    $r2 = member_erase($plain, 'SUPER', '127.0.0.1');
    chk('erase: somebody who never volunteered has nothing kept and is not said to have',
        ($r2['volunteerRecordsKept'] ?? null) === 0
        && (string)(db_row("SELECT meta FROM audit_log WHERE event = 'member.erase' AND subject = ? ORDER BY id DESC LIMIT 1", [$plain])['meta'] ?? '') === '');

    db_exec('DELETE FROM volunteers WHERE memberId = ?', [$mid]);
    db_exec('DELETE FROM members WHERE memberId IN (?, ?)', [$mid, $plain]);
})();

/* ── Where a course leads: providers, awards and who holds one ───────────── */
(function () {
    $now = now_iso();
    $mk = fn($id, $role, $extra = []) => db_insert('members', array_merge(['memberId' => $id, 'fullName' => 'Prv ' . $id,
        'email' => strtolower($id) . '@example.com', 'type' => 'NGG', 'status' => 'active', 'role' => $role,
        'createdAt' => $now, 'updatedAt' => $now], $extra));
    $mk('NGG-PRV-ADM', 'club_admin');                       // holds `curriculum`
    $mk('NGG-PRV-ED', 'editor');                            // does not
    $mk('NGG-PRV-M1', 'member', ['track' => 'Piano', 'centre' => 'Egbeda']);
    $mk('NGG-PRV-M2', 'member', ['track' => 'Guitar', 'centre' => 'Egbeda']);
    $A = 'NGG-PRV-ADM';

    chk('providers: writing the registry is the curriculum cap, not an editor\'s',
        (backend_dispatch('admin.providers.save', ['requesterId' => 'NGG-PRV-ED', 'data' => ['name' => 'x']])['error'] ?? '') === 'forbidden');

    chk('providers: a body needs a name',
        (backend_dispatch('admin.providers.save', ['requesterId' => $A, 'data' => ['name' => '  ']])['error'] ?? '') === 'name_required');

    $p1 = backend_dispatch('admin.providers.save', ['requesterId' => $A, 'data' => [
        'name' => 'Testwood Examinations Board', 'country' => 'United Kingdom',
        'url' => 'https://www.trinitycollege.com/', 'free' => false, 'costNote' => 'Entry fee per grade']]);
    $p2 = backend_dispatch('admin.providers.save', ['requesterId' => $A, 'data' => [
        'name' => 'Testwood Free Academy', 'url' => 'https://www.freecodecamp.org/', 'free' => true]]);
    chk('providers: a body is added and reads back', !empty($p1['ok']) && !empty($p2['ok'])
        && ($p1['provider']['slug'] ?? '') === 'testwood-examinations-board' && ($p2['provider']['free'] ?? false) === true);
    $P1 = (string)$p1['providerId']; $P2 = (string)$p2['providerId'];

    chk('providers: a url that is not http(s) is dropped rather than stored',
        ($p1['provider']['url'] ?? '') === 'https://www.trinitycollege.com/'
        && (backend_dispatch('admin.providers.save', ['requesterId' => $A, 'data' => ['name' => 'Bad', 'url' => 'javascript:alert(1)']])['provider']['url'] ?? 'x') === '');

    $a1 = backend_dispatch('admin.providers.award.save', ['requesterId' => $A, 'data' => [
        'providerId' => $P1, 'title' => 'Graded Examination in Music', 'kind' => 'graded_exam',
        'level' => 'Grade 3', 'courses' => ['Piano', 'Piano', ' Guitar '], 'validMonths' => 0]]);
    $a2 = backend_dispatch('admin.providers.award.save', ['requesterId' => $A, 'data' => [
        'providerId' => $P2, 'title' => 'Responsive Web Design', 'kind' => 'certificate',
        'courses' => ['Practical Coding'], 'free' => true]]);
    chk('providers: an award is added under its body, its courses deduped and trimmed',
        !empty($a1['ok']) && ($a1['award']['courses'] ?? []) === ['Piano', 'Guitar']
        && ($a1['award']['provider'] ?? '') === 'Testwood Examinations Board');
    $AW1 = (string)$a1['awardId']; $AW2 = (string)$a2['awardId'];

    chk('providers: an award must name a body that exists',
        (backend_dispatch('admin.providers.award.save', ['requesterId' => $A, 'data' => ['providerId' => 'PRV-NOPE', 'title' => 'x']])['error'] ?? '') === 'provider_not_found');

    /* Rule 2 — `earned` requires the date every count is built on. */
    $noDate = backend_dispatch('admin.providers.credential.set', ['requesterId' => $A, 'memberId' => 'NGG-PRV-M1',
        'data' => ['awardId' => $AW1, 'state' => 'earned']]);
    chk('providers: "holds it" is refused without the date it was awarded',
        ($noDate['error'] ?? '') === 'awarded_on_required');

    /* Rule 3 — an award belongs to its body, and a mismatch is refused. */
    $cross = backend_dispatch('admin.providers.credential.set', ['requesterId' => $A, 'memberId' => 'NGG-PRV-M1',
        'data' => ['awardId' => $AW1, 'providerId' => $P2, 'state' => 'aiming']]);
    chk('providers: an award claimed under the wrong body is refused, never re-pointed',
        ($cross['error'] ?? '') === 'award_not_of_provider');

    $ok1 = backend_dispatch('admin.providers.credential.set', ['requesterId' => $A, 'memberId' => 'NGG-PRV-M1',
        'data' => ['awardId' => $AW1, 'state' => 'earned', 'awardedOn' => '2026-03-14', 'grade' => 'Merit']]);
    chk('providers: a result is recorded against the member, with their centre',
        !empty($ok1['ok']) && (string)(db_row("SELECT centre FROM member_credentials WHERE memberId = 'NGG-PRV-M1'")['centre'] ?? '') === 'Egbeda');

    /* Rule 1 — one row per member per award; recording again corrects it. */
    backend_dispatch('admin.providers.credential.set', ['requesterId' => $A, 'memberId' => 'NGG-PRV-M1',
        'data' => ['awardId' => $AW1, 'state' => 'earned', 'awardedOn' => '2026-03-14', 'grade' => 'Distinction']]);
    chk('providers: recording it again is a correction, not a second credential',
        (int)db_row("SELECT COUNT(*) c FROM member_credentials WHERE memberId = 'NGG-PRV-M1' AND awardId = '$AW1'")['c'] === 1
        && (string)db_row("SELECT grade FROM member_credentials WHERE memberId = 'NGG-PRV-M1'")['grade'] === 'Distinction');

    /* A member's own aim, and the line they may not cross. */
    $aim = backend_dispatch('member.providers.aim', ['memberId' => 'NGG-PRV-M2', 'awardId' => $AW1]);
    chk('providers: a member can say they are working towards one', !empty($aim['ok'])
        && (string)db_row("SELECT state FROM member_credentials WHERE memberId = 'NGG-PRV-M2'")['state'] === 'aiming');
    chk('providers: a member cannot assert they hold one — their centre records that',
        (prv_credential_write(db_row("SELECT * FROM members WHERE memberId = 'NGG-PRV-M2'"),
            ['awardId' => $AW1, 'state' => 'earned', 'awardedOn' => '2026-01-01'], false, 'NGG-PRV-M2')['error'] ?? '') === 'staff_records_this');
    backend_dispatch('admin.providers.credential.set', ['requesterId' => $A, 'memberId' => 'NGG-PRV-M2',
        'data' => ['awardId' => $AW1, 'state' => 'registered']]);
    chk('providers: once the centre has recorded a result, the member cannot take it back',
        (backend_dispatch('member.providers.aim', ['memberId' => 'NGG-PRV-M2', 'awardId' => $AW1, 'remove' => true])['error'] ?? '') === 'staff_records_this');

    /* Rule 6 — lapsed is derived from the date, never written by a job. */
    $lapsing = backend_dispatch('admin.providers.award.save', ['requesterId' => $A, 'data' => [
        'providerId' => $P2, 'title' => 'Expiring thing', 'validMonths' => 12, 'courses' => ['Piano']]]);
    backend_dispatch('admin.providers.credential.set', ['requesterId' => $A, 'memberId' => 'NGG-PRV-M1',
        'data' => ['awardId' => (string)$lapsing['awardId'], 'state' => 'earned', 'awardedOn' => '2020-01-01']]);
    $old = db_row("SELECT * FROM member_credentials WHERE memberId = 'NGG-PRV-M1' AND awardId = '" . (string)$lapsing['awardId'] . "'");
    chk('providers: an award with a validity gets an expiry from the date it was given',
        (string)$old['expiresOn'] === '2021-01-01');
    chk('providers: and it reads as lapsed without any job having run',
        prv_is_lapsed($old) === true && prv_shown_state($old) === 'lapsed'
        && prv_shown_state(['state' => 'earned', 'expiresOn' => '']) === 'earned');

    /* The member's own screen: where their courses lead. */
    $mine = backend_dispatch('member.providers.mine', ['memberId' => 'NGG-PRV-M1']);
    $titles = array_map(static fn($r) => $r['title'], $mine['held'] ?? []);
    chk('providers: a member sees what they hold', !empty($mine['ok']) && in_array('Graded Examination in Music', $titles, true));
    $routeTitles = array_map(static fn($r) => $r['title'], $mine['routes'] ?? []);
    chk('providers: and a route they do NOT hold only when one of their own courses leads to it',
        !in_array('Responsive Web Design', $routeTitles, true));
    chk('providers: a credential they hold still shows after they leave the course that led to it',
        count(array_filter($mine['held'] ?? [], static fn($h) => $h['state'] === 'lapsed')) === 1);

    /* Rule 5 — a body in use is not deleted silently, and retire is the answer. */
    $del = backend_dispatch('admin.providers.delete', ['requesterId' => $A, 'providerId' => $P1]);
    chk('providers: a body members hold awards from is not deleted silently',
        ($del['error'] ?? '') === 'provider_in_use' && (int)($del['uses']['credentials'] ?? 0) >= 2);
    $ret = backend_dispatch('admin.providers.delete', ['requesterId' => $A, 'providerId' => $P1, 'retire' => true]);
    chk('providers: retiring it keeps every record resolving (rule 4)',
        !empty($ret['retired'])
        && (int)db_row("SELECT COUNT(*) c FROM member_credentials WHERE providerId = '$P1'")['c'] >= 2
        && (string)db_row("SELECT status FROM providers WHERE providerId = '$P1'")['status'] === 'retired');

    /* The board: what the programme can actually claim. */
    $b = backend_dispatch('admin.providers.board', ['requesterId' => $A]);
    $row = null; foreach ($b['awards'] ?? [] as $r) if ($r['awardId'] === $AW1) $row = $r;
    chk('providers: the board counts holders per award, biggest first, and names them',
        !empty($b['ok']) && $row && (int)$row['earned'] === 1 && (int)$row['registered'] === 1
        && ($row['holders'][0]['memberId'] ?? '') === 'NGG-PRV-M1');
    chk('providers: and counts the people, not the rows', (int)($b['people'] ?? 0) === 2);

    /* One person's record. */
    $one = backend_dispatch('admin.providers.member', ['requesterId' => $A, 'memberId' => 'NGG-PRV-M1']);
    chk('providers: one member\'s credentials read back with the body that awarded them',
        !empty($one['ok']) && count($one['credentials']) === 2
        && in_array('Testwood Examinations Board', array_map(static fn($c) => $c['provider'], $one['credentials']), true));

    /* An award nobody holds goes; one people hold does not. */
    chk('providers: an award people hold is not deleted silently',
        (backend_dispatch('admin.providers.award.delete', ['requesterId' => $A, 'awardId' => $AW1])['error'] ?? '') === 'award_in_use');
    chk('providers: an award nobody holds is deleted',
        !empty(backend_dispatch('admin.providers.award.delete', ['requesterId' => $A, 'awardId' => $AW2])['deleted']));

    /* The starter registry. Every line of it is supposed to be traceable to
       a material link in this repository's own curriculum — so the test that
       matters is not "it inserted rows" but "the courses it names are real
       courses, and pressing it twice changes nothing". */
    $seed = backend_dispatch('admin.providers.seed', ['requesterId' => $A]);
    chk('providers: the starter registry seeds the bodies our own curriculum points at',
        !empty($seed['ok']) && (int)$seed['added']['providers'] >= 7 && (int)$seed['added']['awards'] >= 9);
    chk('providers: …including the free routes, marked free',
        (int)(db_row("SELECT COUNT(*) c FROM providers WHERE free = 1 AND status = 'active'")['c'] ?? 0) >= 3
        && (int)(db_row("SELECT COUNT(*) c FROM provider_awards WHERE free = 1")['c'] ?? 0) >= 5);

    /* A certificate we tell a child to aim for has to exist, and a route that
       names a course nobody teaches reaches nobody. Both are checked against
       the bundled curriculum rather than trusted. */
    $known = [];
    foreach (db_all("SELECT DISTINCT course FROM curriculum_units") as $r) $known[mb_strtolower((string)$r['course'])] = true;
    $orphans = [];
    foreach (prv_seed_data() as $b) foreach ($b['awards'] as $a) foreach ($a['courses'] as $c) {
        if ($known && !isset($known[mb_strtolower($c)])) $orphans[$c] = true;
    }
    chk('providers: every course the starter registry names is a course we actually teach'
        . ($orphans ? ' — ' . implode(', ', array_slice(array_keys($orphans), 0, 4)) : ''),
        !$orphans);
    chk('providers: every seeded body has a real https address and at least one award',
        !array_filter(prv_seed_data(), static fn($b) => !preg_match('~^https://~', (string)$b['url']) || !$b['awards']));

    $again = backend_dispatch('admin.providers.seed', ['requesterId' => $A]);
    chk('providers: seeding twice adds nothing and keeps every edit the programme made',
        !empty($again['ok']) && (int)$again['added']['providers'] === 0 && (int)$again['added']['awards'] === 0
        && (int)$again['kept']['providers'] >= 7);

    db_exec("DELETE FROM provider_awards WHERE providerId IN (SELECT providerId FROM providers WHERE slug IN ('freecodecamp','cisco-networking-academy','elements-of-ai','google','nbte','trinity-college-london','abrsm'))");
    db_exec("DELETE FROM providers WHERE slug IN ('freecodecamp','cisco-networking-academy','elements-of-ai','google','nbte','trinity-college-london','abrsm')");
    db_exec("DELETE FROM member_credentials WHERE memberId LIKE 'NGG-PRV-%'");
    db_exec("DELETE FROM provider_awards WHERE providerId IN ('$P1', '$P2')");
    db_exec("DELETE FROM providers WHERE providerId IN ('$P1', '$P2')");
    db_exec("DELETE FROM members WHERE memberId LIKE 'NGG-PRV-%'");
})();


/* ── A model id in a config file is a pin nobody revisits ────────────────── */
(function () {
    $save = $GLOBALS['CONFIG']['ai'] ?? null;

    /* Blank, or absent, or whitespace: all three mean "whatever this release
       considers current". Only `??` used to do this, which caught the absent
       case alone — and a deployment that copied config.example.php has the key
       PRESENT, so it stayed on a model a generation behind for as long as the
       file sat there. */
    chk('ai models: a blank model means this release\'s current default, not an empty model',
        ai_model_for('anthropic', '') === AI_DEFAULT_MODEL['anthropic']
        && ai_model_for('anthropic', null) === AI_DEFAULT_MODEL['anthropic']
        && ai_model_for('anthropic', '   ') === AI_DEFAULT_MODEL['anthropic']);
    chk('ai models: …and a model that IS set is still honoured, so a pin stays a pin',
        ai_model_for('anthropic', 'claude-haiku-4-5-20251001') === 'claude-haiku-4-5-20251001');
    /* Gemini falls out unchanged: its default IS '', which already means
       "ask Google for the best model this key can use". */
    chk('ai models: gemini keeps its blank, which means "ask Google"',
        ai_model_for('gemini', '') === '' && AI_DEFAULT_MODEL['gemini'] === '');

    $GLOBALS['CONFIG']['ai'] = ['provider' => 'anthropic', 'anthropic_api_key' => 'test-key', 'anthropic_model' => ''];
    $cands = ai_default_candidates();
    chk('ai models: a configured key with a blank model resolves through to the call',
        count($cands) === 1 && $cands[0]['model'] === AI_DEFAULT_MODEL['anthropic'] && $cands[0]['model'] !== '');

    $GLOBALS['CONFIG']['ai'] = ['profiles' => ['marking' => ['provider' => 'anthropic', 'api_key' => 'k', 'model' => '']]];
    $chain = ai_profile_chain('marking');
    chk('ai models: a profile with a blank model resolves too, and stays capable enough to mark',
        !empty($chain) && $chain[0]['model'] === AI_DEFAULT_MODEL['anthropic']
        && ai_model_is_capable($chain[0]['model']));

    /* The example config must not re-state what ai.php already decides. Two
       lists of defaults is the drift CLAUDE.md §11 names, and here the drift
       cost real money: the pinned small model priced ten times the current
       one per token. */
    $ex = file_get_contents(__DIR__ . '/../config.example.php');
    chk('ai models: the shipped example pins no model at all',
        preg_match("/'model'\s*=>\s*'[^']/", $ex) !== 1
        && preg_match("/_model'\s*=>\s*'[^']/", $ex) !== 1);

    /* The claim the comment in config.example.php makes, checked rather than
       asserted: the generation it used to pin really is the dearer one. */
    $oldP = ai_price_for(['provider' => 'anthropic', 'model' => 'claude-haiku-4-5-20251001', 'tier' => 'paid']);
    $newP = ai_price_for(['provider' => 'anthropic', 'model' => AI_DEFAULT_MODEL['anthropic'], 'tier' => 'paid']);
    chk('ai models: every model the example used to pin is priced in the table (no "unknown, assume dear")',
        $oldP !== AI_PRICE_UNKNOWN_PAID && $newP !== AI_PRICE_UNKNOWN_PAID);
    $small = ai_price_for(['provider' => 'anthropic', 'model' => 'claude-haiku-5', 'tier' => 'paid']);
    chk('ai models: …and the small model it pinned costs about ten times the current one',
        $oldP[0] >= $small[0] * 9 && $oldP[1] >= $small[1] * 9);

    if ($save === null) unset($GLOBALS['CONFIG']['ai']); else $GLOBALS['CONFIG']['ai'] = $save;
})();


/* A revised shipped curriculum reaches a deployment seeded from an older one
   (2026-10-29: the fuller lessons). Only a lesson still exactly as shipped
   takes the new text; one an instructor saved stays theirs; an answer already
   given keeps pointing at its unchanged question. */
(function () {
    $saveCfg = $GLOBALS['CONFIG']['seed_bundled_curriculum'] ?? null;
    unset($GLOBALS['CONFIG']['seed_bundled_curriculum']);
    $row = static fn($w, $body) => ['course' => 'Piano', 'level' => 'Year 9 · Seedtest', 'week' => $w, 'position' => 1, 'title' => 'Seed test ' . $w,
        'summary' => 'S', 'objectives' => ['O'], 'body' => $body, 'durationMins' => 30, 'passMark' => 50, 'materials' => [],
        'checks' => [['kind' => 'mcq', 'prompt' => 'Pick one', 'options' => ['a', 'b'], 'answer' => '0', 'points' => 1],
                     ['kind' => 'task', 'prompt' => 'Show what you did', 'rubric' => 'Did it', 'points' => 2]]];
    $file = static fn($a, $b) => ['seedtest' => ['key' => 'seedtest', 'allowNewCourse' => true, 'lessons' => [$row(1, $a), $row(2, $b)]]];
    $GLOBALS['__curriculum_seed_files'] = $file('Short one.', 'Short two.');
    db_exec("DELETE FROM settings WHERE settingKey = 'seed_curriculum_seedtest'");
    curriculum_seed_bundled_once();
    $u = static fn($w) => db_row("SELECT * FROM curriculum_units WHERE level = 'Year 9 · Seedtest' AND week = ?", [$w]);
    chk('seed refresh · the first file seeds both lessons', $u(1) && $u(2) && $u(1)['body'] === 'Short one.');
    $chk1 = db_row('SELECT checkId FROM curriculum_checks WHERE unitId = ? ORDER BY position LIMIT 1', [$u(1)['unitId']])['checkId'];
    // An instructor edits lesson 2 through the editor's path.
    db_update('curriculum_units', ['body' => 'Mine now.', 'updatedBy' => 'NGG-INSTR'], ['unitId' => $u(2)['unitId']]);
    curriculum_seed_bundled_once();
    chk('seed refresh · the same file again changes nothing', $u(1)['body'] === 'Short one.');
    $GLOBALS['__curriculum_seed_files'] = $file("Short one.\n\n## Understand it\n\nMuch more.", "Short two, fuller.");
    curriculum_seed_bundled_once();
    chk('seed refresh · a revised file updates a lesson still as shipped', str_contains($u(1)['body'], 'Much more.'));
    chk('seed refresh · …and leaves a lesson an instructor saved alone', $u(2)['body'] === 'Mine now.');
    chk('seed refresh · …and an unchanged question keeps its id', (bool)db_row('SELECT 1 FROM curriculum_checks WHERE checkId = ? AND unitId = ?', [$chk1, $u(1)['unitId']]));
    unset($GLOBALS['__curriculum_seed_files']);
    foreach ([1, 2] as $w) { $x = $u($w); if ($x) { db_exec('DELETE FROM curriculum_checks WHERE unitId = ?', [$x['unitId']]); db_exec('DELETE FROM curriculum_materials WHERE unitId = ?', [$x['unitId']]); db_exec('DELETE FROM curriculum_units WHERE unitId = ?', [$x['unitId']]); } }
    db_exec("DELETE FROM settings WHERE settingKey = 'seed_curriculum_seedtest'");
    if ($saveCfg !== null) $GLOBALS['CONFIG']['seed_bundled_curriculum'] = $saveCfg;
})();


/* What to do with a material (2026-10-29: "improve the quality of learning
   materials"). A material carries one line for the learner, stored, served,
   compared on re-import and refreshed from a revised seed; practice sites
   are recognised as practice; and every shipped lesson has at least two
   materials, each with its line, none of them a dead or walled link. */
(function () {
    chk('materials · a practice site is recognised as practice',
        curriculum_material_kind('', 'https://www.musictheory.net/exercises') === 'interactive'
        && curriculum_material_kind('', 'https://www.freecodecamp.org/learn/relational-database/') === 'interactive'
        && curriculum_material_kind('', 'https://www.bbc.co.uk/bitesize/subjects/zpf3cdm') === 'link');
    $base = ['course' => 'Piano', 'level' => 'Year 9 · Guidetest', 'week' => 1, 'position' => 1, 'title' => 'Guide test',
        'summary' => 'S', 'objectives' => ['O'], 'body' => 'B', 'durationMins' => 30, 'passMark' => 50,
        'checks' => [['kind' => 'mcq', 'prompt' => 'Pick one', 'options' => ['a', 'b'], 'answer' => '0', 'points' => 1],
                     ['kind' => 'task', 'prompt' => 'Show what you did', 'rubric' => 'Did it', 'points' => 2]]];
    $v = curriculum_validate($base + ['materials' => [['url' => 'https://example.org/a', 'title' => 'A', 'guide' => str_repeat('x', 400)]]], true);
    chk('materials · a guide is kept, and clipped to its limit', ($v['ok'] ?? false) && mb_strlen($v['materials'][0]['guide']) === CURR_MATERIAL_GUIDE_MAX);
    $saveCfg = $GLOBALS['CONFIG']['seed_bundled_curriculum'] ?? null;
    unset($GLOBALS['CONFIG']['seed_bundled_curriculum']);
    $file = static fn($g) => ['guidetest' => ['key' => 'guidetest', 'allowNewCourse' => true,
        'lessons' => [$base + ['materials' => [['url' => 'https://example.org/a', 'title' => 'A', 'guide' => $g]]]]]];
    $GLOBALS['__curriculum_seed_files'] = $file('Do the first three.');
    db_exec("DELETE FROM settings WHERE settingKey = 'seed_curriculum_guidetest'");
    curriculum_seed_bundled_once();
    $unit = static fn() => db_row("SELECT * FROM curriculum_units WHERE level = 'Year 9 · Guidetest'");
    chk('materials · a shipped lesson with a guide is seeded', (bool)$unit());
    $pub = static function () use ($unit) { if (!$unit()) return ['materials' => []]; $b = curriculum_load('unitId = ?', [$unit()['unitId']]); $x = reset($b); return curriculum_unit_public($x['unit'], $x['materials'], $x['checks'], false); };
    chk('materials · the learner is served the guide', ($pub()['materials'][0]['guide'] ?? '') === 'Do the first three.');
    $b = $unit() ? curriculum_load('unitId = ?', [$unit()['unitId']]) : []; $x = reset($b) ?: ['unit' => [], 'materials' => [], 'checks' => []];
    $again = curriculum_validate($base + ['materials' => [['url' => 'https://example.org/a', 'title' => 'A', 'guide' => 'Do the first three.']]], true);
    chk('materials · the same guide re-imported reads as unchanged', curriculum_fingerprint($again) === curriculum_fingerprint_stored($x));
    $GLOBALS['__curriculum_seed_files'] = $file('Now do all five.');
    curriculum_seed_bundled_once();
    chk('materials · a revised guide reaches a lesson still as shipped', ($pub()['materials'][0]['guide'] ?? '') === 'Now do all five.');
    unset($GLOBALS['__curriculum_seed_files']);
    $x = $unit(); if ($x) { db_exec('DELETE FROM curriculum_checks WHERE unitId = ?', [$x['unitId']]); db_exec('DELETE FROM curriculum_materials WHERE unitId = ?', [$x['unitId']]); db_exec('DELETE FROM curriculum_units WHERE unitId = ?', [$x['unitId']]); }
    db_exec("DELETE FROM settings WHERE settingKey = 'seed_curriculum_guidetest'");
    if ($saveCfg !== null) $GLOBALS['CONFIG']['seed_bundled_curriculum'] = $saveCfg;

    // The shipped courses themselves.
    $walled = ['abrsm.org', 'canva.com', 'justinguitar.com', 'musescore.com/sheetmusic', 'britishmuseum.org', '://www.google.com/search', 'help.openai.com', 'adobe.com/express'];
    $thin = []; $unguided = []; $bad = []; $n = 0;
    foreach (glob(__DIR__ . '/../_lib/seeds/curriculum-*.json') as $f) {
        foreach ((json_decode((string)file_get_contents($f), true)['lessons'] ?? []) as $L) {
            $ms = $L['materials'] ?? []; $n++;
            if (count($ms) < 2) $thin[] = $L['course'] . ' wk' . $L['week'];
            foreach ($ms as $m) {
                if (trim((string)($m['guide'] ?? '')) === '') $unguided[] = $m['url'];
                foreach ($walled as $w) if (str_contains((string)$m['url'], $w)) $bad[] = $m['url'];
            }
        }
    }
    chk('materials · every shipped lesson has at least two materials (' . $n . ' lessons)' . ($thin ? ': ' . implode(', ', array_slice($thin, 0, 5)) : ''), $n > 500 && !$thin);
    chk('materials · every shipped material says what to do with it' . ($unguided ? ': ' . implode(', ', array_slice($unguided, 0, 5)) : ''), !$unguided);
    chk('materials · no shipped material is a dead, walled or search-page link' . ($bad ? ': ' . implode(', ', array_slice(array_unique($bad), 0, 5)) : ''), !$bad);
})();

/* Lesson files survive a deploy (2026-10-29: "all of the diagrams and
   illustrations and gifs are no longer there"). Uploads went only to
   api/storage/curriculum, inside the folder a deploy replaces. Now: a file in
   the old place is moved out on read; with a bucket, every upload is mirrored
   and a lost disk copy is fetched back; and what is truly gone is listed. */
(function () {
    $tmpd = sys_get_temp_dir() . '/ngg-curfiles-' . bin2hex(random_bytes(4));
    $legacy = curriculum_file_legacy_dir();
    @mkdir($legacy, 0775, true);
    $GLOBALS['__curriculum_file_dir'] = $tmpd . '/safe';
    // 1. A file left in the old place is found, and moved out of the site folder.
    $f1 = str_repeat('a', 40) . '.gif';
    file_put_contents($legacy . '/' . $f1, 'GIF89a-legacy');
    $p1 = curriculum_file_path($f1);
    chk('lesson files · a file still in the old folder is found', $p1 !== '' && file_get_contents($p1) === 'GIF89a-legacy');
    chk('lesson files · …and moved out of the website folder as it is read', $p1 === $tmpd . '/safe/' . $f1 && !is_file($legacy . '/' . $f1));
    // 2. With a bucket: an upload is mirrored, and a lost disk copy comes back.
    $bucket = [];
    $GLOBALS['__store_http_mock'] = function ($m, $key, $body = '', $extra = []) use (&$bucket) {
        if ($m === 'PUT') { $bucket[$key] = $body; return ['code' => 200, 'body' => '']; }
        if ($m === 'GET') return isset($bucket[$key]) ? ['code' => 200, 'body' => $bucket[$key]] : ['code' => 404, 'body' => ''];
        return ['code' => 0, 'body' => ''];
    };
    $src = $tmpd . '/up.png';
    file_put_contents($src, base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII='));
    $put = curriculum_file_store(['tmp' => $src, 'name' => 'diagram.png'], 'NGG-TEST');
    preg_match('/f=(.+)$/', (string)($put['url'] ?? ''), $mm); $f2 = $mm[1] ?? '';
    chk('lesson files · an upload is copied to the bucket too', !empty($put['ok']) && isset($bucket[curriculum_file_bucket_key($f2)]));
    @unlink($tmpd . '/safe/' . $f2);
    $p2 = curriculum_file_path($f2);
    chk('lesson files · a copy lost from disk is fetched back from the bucket', $p2 !== '' && is_file($p2));
    // 3. Truly gone: listed, per lesson, for staff to upload again.
    unset($GLOBALS['__store_http_mock']);
    $gone = str_repeat('b', 40) . '.gif';
    $now = now_iso();
    db_insert('curriculum_units', ['unitId' => 'CUR-LOSTF', 'course' => 'Drums', 'level' => 'Year 9 · Lost', 'week' => 3, 'position' => 1, 'title' => 'The backbeat',
        'summary' => '', 'status' => 'published', 'passMark' => 50, 'version' => 1, 'objectives' => '[]',
        'body' => "Watch this:\n\n![Backbeat](/api/member/curriculum-file.php?f=$gone)", 'durationMins' => 30, 'createdAt' => $now, 'updatedAt' => $now]);
    db_insert('curriculum_materials', ['materialId' => 'MAT-LOSTF', 'unitId' => 'CUR-LOSTF', 'kind' => 'image', 'title' => 'Sticking chart',
        'url' => '/api/member/curriculum-file.php?f=' . str_repeat('c', 40) . '.png', 'position' => 1, 'createdAt' => $now, 'status' => 'approved']);
    $miss = array_values(array_filter(curriculum_missing_files(), static fn($x) => $x['unitId'] === 'CUR-LOSTF'));
    chk('lesson files · a lost picture in the text and a lost material are both listed, by lesson', count($miss) === 2
        && in_array('text', array_column($miss, 'where'), true) && in_array('material', array_column($miss, 'where'), true));
    $r = admin_curriculum_files(['requesterId' => 'NGG-NOBODY']);
    chk('lesson files · the list is for curriculum staff only', empty($r['ok']));
    db_exec("DELETE FROM curriculum_materials WHERE unitId = 'CUR-LOSTF'"); db_exec("DELETE FROM curriculum_units WHERE unitId = 'CUR-LOSTF'");
    unset($GLOBALS['__curriculum_file_dir']);
})();

/* ═══════════════════════════════════════════════════════════════════════════
   NGG's centres follow CACENTRE's locations (domain/cac-locations.php)
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
    $SU = 'NGG-2025-0099';
    $keep = ['centres' => db_all('SELECT * FROM centres'), 'members' => db_all('SELECT id, centre FROM members'), 'ss' => db_all('SELECT id, centre FROM summer_students'),
             'vols' => db_all('SELECT id, centre FROM volunteers'), 'cac' => setting_get('cacLocations'), 'att' => setting_get('attendance')];
    db_exec('DELETE FROM centres');
    db_exec("DELETE FROM settings WHERE settingKey = 'cacLocations'");
    $mk = fn($id, $name, $code, $extra = []) => db_insert('centres', array_merge(['centreId' => $id, 'name' => $name, 'code' => $code, 'color' => '#336699', 'status' => 'active', 'slug' => strtolower(str_replace(' ', '-', $name)), 'createdAt' => now_iso()], $extra));
    $mk('T-EG', 'Egbeda', 'EG');
    $mk('T-AYH', 'Ayobo Hub', 'AYH');
    $mk('T-OLD', 'Old Hall', 'OH');
    db_insert('members', ['memberId' => 'NGG-CL-1', 'fullName' => 'Lola Location', 'email' => 'lola-loc@example.com', 'type' => 'NGG', 'status' => 'active', 'role' => 'member', 'centre' => 'Ayobo Hub', 'createdAt' => now_iso(), 'updatedAt' => now_iso()]);
    $EG = 'L0123456789'; $AY = 'Labcdefabcd'; $IK = 'L1111111111'; $OH = 'L2222222222';
    $cal = ['weekdays' => [6], 'resumption' => '10:00', 'grace_minutes' => 5, 'terms' => [], 'term_start' => '', 'term_end' => '', 'holidays' => []];
    $list = fn($v, $locs) => ['version' => $v, 'tz' => 'Africa/Lagos', 'locations' => $locs];

    chk('cacentre: before CACENTRE’s list arrives, centres are added here as before', !cac_locations_active());
    chk('cacentre: a list with a bad id changes nothing', !cac_locations_sync($list('v0-xxxxxxxx', [['id' => 'nope', 'name' => 'X', 'status' => 'active']]))['ok'] && !db_row("SELECT id FROM centres WHERE name = 'X'"));

    $r = cac_locations_sync($list('v1-aaaaaaaa', [
        ['id' => $EG, 'name' => 'Egbeda', 'status' => 'active', 'aliases' => [], 'calendar' => $cal],
        ['id' => $AY, 'name' => 'Ayobo', 'status' => 'active', 'aliases' => ['Ayobo Hub'], 'calendar' => null],
        ['id' => $IK, 'name' => 'Ikotun', 'status' => 'active', 'aliases' => [], 'calendar' => null],
        ['id' => $OH, 'name' => 'Old Hall', 'status' => 'retired', 'aliases' => [], 'calendar' => null],
    ]));
    $c = fn($id) => db_row('SELECT * FROM centres WHERE cacLocationId = ?', [$id]);
    chk('cacentre: the centre NGG already had under the same name is linked, keeping its code', ($c($EG)['centreId'] ?? '') === 'T-EG' && $c($EG)['code'] === 'EG');
    chk('cacentre: …and one NGG had under a former name is linked and renamed, and its members move with it',
        ($c($AY)['centreId'] ?? '') === 'T-AYH' && $c($AY)['name'] === 'Ayobo' && db_row("SELECT centre FROM members WHERE memberId = 'NGG-CL-1'")['centre'] === 'Ayobo' && in_array('Ayobo Hub → Ayobo', $r['renamed'], true));
    chk('cacentre: a location NGG never had becomes a centre, with a code made from its name', ($c($IK)['name'] ?? '') === 'Ikotun' && $c($IK)['code'] === 'IKO' && $c($IK)['status'] === 'active');
    chk('cacentre: a location CACENTRE took off is retired here, never deleted', ($c($OH)['status'] ?? '') === 'retired' && (bool)db_row("SELECT id FROM centres WHERE centreId = 'T-OLD'"));
    chk('cacentre: the location’s calendar is kept for reading', (json_decode((string)$c($EG)['cacCalendar'], true)['resumption'] ?? '') === '10:00');
    chk('cacentre: the list is now in charge', cac_locations_active());
    chk('cacentre: the change is one audit event, saying what happened', (bool)db_row("SELECT id FROM audit_log WHERE event = 'centre.cacentre_sync' AND subject = 'v1-aaaaaaaa'"));

    /* Rename in CACENTRE: the same place, a new name, every record follows. */
    db_insert('volunteers', ['volunteerId' => 'VOL-CL-1', 'fullName' => 'Vic Vol', 'status' => 'active', 'centre' => 'Egbeda', 'createdAt' => now_iso()]);
    cac_locations_sync($list('v2-bbbbbbbb', [
        ['id' => $EG, 'name' => 'Egbeda Centre', 'status' => 'active', 'aliases' => ['Egbeda'], 'calendar' => $cal],
        ['id' => $AY, 'name' => 'Ayobo', 'status' => 'active', 'aliases' => ['Ayobo Hub'], 'calendar' => null],
        ['id' => $IK, 'name' => 'Ikotun', 'status' => 'retired', 'aliases' => [], 'calendar' => null],
    ]));
    chk('cacentre: renamed in CACENTRE, renamed here — same centre, same code', ($c($EG)['centreId'] ?? '') === 'T-EG' && $c($EG)['name'] === 'Egbeda Centre' && $c($EG)['code'] === 'EG');
    chk('cacentre: …and the records that named it follow', db_row("SELECT centre FROM volunteers WHERE volunteerId = 'VOL-CL-1'")['centre'] === 'Egbeda Centre');
    chk('cacentre: a location retired in CACENTRE is retired here', $c($IK)['status'] === 'retired');
    chk('cacentre: the same list twice changes nothing', cac_locations_sync($list('v2-bbbbbbbb', [['id' => $EG, 'name' => 'Egbeda Centre', 'status' => 'active', 'aliases' => [], 'calendar' => $cal]]))['renamed'] === []);

    /* NGG cannot then change what CACENTRE decides. */
    $up = fn($data) => backend_dispatch('admin.centres.upsert', ['requesterId' => $SU, 'data' => $data]);
    chk('cacentre: a linked centre cannot be renamed here', ($up(['centreId' => 'T-EG', 'name' => 'Egbeda West', 'code' => 'EG', 'color' => '#336699'])['error'] ?? '') === 'managed_by_cacentre');
    chk('cacentre: …nor its status changed here', ($up(['centreId' => 'T-EG', 'name' => 'Egbeda Centre', 'code' => 'EG', 'color' => '#336699', 'status' => 'archived'])['error'] ?? '') === 'managed_by_cacentre');
    chk('cacentre: …but its colour, code and page still are NGG’s', !empty($up(['centreId' => 'T-EG', 'name' => 'Egbeda Centre', 'code' => 'EGB', 'color' => '#E9A21B', 'area' => 'Egbeda'])['ok']) && $c($EG)['color'] === '#E9A21B');
    chk('cacentre: no centre is added here by hand once the list is in charge', ($up(['name' => 'Agege', 'code' => 'AGE', 'color' => '#336699'])['error'] ?? '') === 'managed_by_cacentre');
    chk('cacentre: a linked centre is not removed or retired here', (backend_dispatch('admin.centres.delete', ['requesterId' => $SU, 'centreId' => 'T-EG', 'retire' => true])['error'] ?? '') === 'managed_by_cacentre');
    $l = backend_dispatch('admin.centres.list', ['requesterId' => $SU]);
    chk('cacentre: the directory says the centres come from CACENTRE, and which ones', ($l['cacentre']['version'] ?? '') === 'v2-bbbbbbbb'
        && count(array_filter($l['centres'], fn($x) => $x['cacLocationId'] !== '')) === 4);   // Egbeda, Ayobo, and Ikotun and Old Hall, retired

    /* The gate's list arrives through the hook. */
    chk('cacentre: the gate hook takes the list', !empty(backend_dispatch('hooks.gate.locations', $list('v3-cccccccc', [['id' => $EG, 'name' => 'Egbeda Centre', 'status' => 'active', 'aliases' => [], 'calendar' => $cal]]))['ok']));

    /* A gate check-in records where it was. */
    db_exec("DELETE FROM attendance WHERE studentId = 'NGG-CL-1'");
    $h = backend_dispatch('hooks.attendance', ['source' => 'cacentre-gate', 'events' => [['ref' => 'NGG-CL-1', 'date' => attendance_today(), 'scannedAt' => gmdate('Y-m-d\TH:i:s\Z'), 'centre' => 'Egbeda', 'location' => $EG, 'desk' => 'TG5MZQC339QA']]]);
    chk('cacentre: a gate check-in records the location it was at, by its id — under its name now', ($h['results'][0]['status'] ?? '') === 'marked'
        && db_row("SELECT centre FROM attendance WHERE studentId = 'NGG-CL-1'")['centre'] === 'Egbeda Centre');

    /* The gate is told NGG's own rule for lateness. */
    setting_set('attendance', ['enabled' => true, 'tzOffset' => 60, 'graceMinutes' => 7, 'resumptionByType' => ['volunteer' => '8:15']], 'test');
    $pv = gate_person_volunteer(db_row("SELECT * FROM volunteers WHERE volunteerId = 'VOL-CL-1'"));
    chk('cacentre: the gate is told NGG’s own resumption and grace, so the desk says what NGG records',
        array_key_exists('punctuality', $pv) && ($pv['punctuality'] === null || $pv['punctuality'] === ['resumption' => '08:15', 'grace_minutes' => 7]));
    setting_set('attendance', ['enabled' => false], 'test');
    chk('cacentre: …and none at all when NGG’s attendance rules are off', gate_person_volunteer(db_row("SELECT * FROM volunteers WHERE volunteerId = 'VOL-CL-1'"))['punctuality'] === null);

    // Put things back.
    db_exec("DELETE FROM attendance WHERE studentId = 'NGG-CL-1'");
    db_exec("DELETE FROM members WHERE memberId = 'NGG-CL-1'");
    db_exec("DELETE FROM volunteers WHERE volunteerId = 'VOL-CL-1'");
    db_exec('DELETE FROM centres');
    foreach ($keep['centres'] as $row) { unset($row['id']); db_insert('centres', $row); }
    foreach ($keep['members'] as $m) db_update('members', ['centre' => $m['centre']], ['id' => (int)$m['id']]);
    foreach ($keep['ss'] as $m) db_update('summer_students', ['centre' => $m['centre']], ['id' => (int)$m['id']]);
    foreach ($keep['vols'] as $m) db_update('volunteers', ['centre' => $m['centre']], ['id' => (int)$m['id']]);
    if (is_array($keep['cac'])) setting_set('cacLocations', $keep['cac'], 'test'); else db_exec("DELETE FROM settings WHERE settingKey = 'cacLocations'");
    if (is_array($keep['att'])) setting_set('attendance', $keep['att'], 'test'); else db_exec("DELETE FROM settings WHERE settingKey = 'attendance'");
})();

// ── Make.com: the processes that wait on a person (domain/make.php) ──
(function () {
    $now = now_iso(); $today = attendance_today();
    $yday = gmdate('Y-m-d', (int)strtotime($today . ' 00:00:00 UTC') - 86400);
    db_insert('members', ['memberId' => 'NGG-MK-1', 'fullName' => 'Kemi Adeyemi', 'type' => 'NGG', 'status' => 'active', 'centre' => 'Make Centre', 'parentName' => 'Mrs Adeyemi', 'parentPhone' => '08031234567']);
    db_insert('members', ['memberId' => 'NGG-MK-2', 'fullName' => 'Tunde Bello', 'type' => 'NGG', 'status' => 'active', 'centre' => 'Make Centre', 'parentPhone' => '']);
    db_insert('infractions', ['personId' => 'NGG-MK-1', 'personType' => 'member', 'kind' => 'absence', 'date' => $yday, 'note' => 'No check-in.', 'createdAt' => $now]);
    db_insert('infractions', ['personId' => 'NGG-MK-2', 'personType' => 'member', 'kind' => 'absence', 'date' => $yday, 'note' => 'No check-in.', 'createdAt' => $now]);
    db_insert('infractions', ['personId' => 'NGG-MK-1', 'personType' => 'member', 'kind' => 'absence', 'date' => '2020-01-06', 'note' => 'Old.', 'createdAt' => $now]);

    chk('make: no subscriber, nothing built — the private list is not even assembled', (make_absences_run()['skipped'] ?? '') === 'no_subscriber'
        && !db_row("SELECT id FROM absence_asks WHERE personId = 'NGG-MK-1' LIMIT 1"));

    db_insert('integrations', ['integrationId' => 'INT-MAKE-1', 'kind' => 'webhook', 'name' => 'Make', 'config' => '{"url":"https://hook.eu1.make.com/x","secret":"s"}',
        'events' => json_encode(['private.attendance.absences', 'private.registration.stalled', 'safeguarding.*', 'edition.milestone']), 'status' => 'active', 'createdAt' => $now]);
    db_insert('integrations', ['integrationId' => 'INT-MAKE-ALL', 'kind' => 'gchat', 'name' => 'Everything room', 'config' => '{"url":"https://chat.googleapis.com/x"}',
        'events' => json_encode(['*']), 'status' => 'active', 'createdAt' => $now]);

    $r = make_absences_run();
    // The suite's own earlier absences are asked about too; read this centre's.
    $ev = db_row("SELECT eventId, payload FROM outbox WHERE kind = 'private.attendance.absences' AND payload LIKE '%\"centre\":\"Make Centre\"%' ORDER BY id DESC LIMIT 1");
    $pl = json_decode((string)($ev['payload'] ?? '{}'), true);
    $item = $pl['items'][0] ?? [];
    chk('make: an absence becomes one question per centre-day, to the guardian, first name only', ($r['asked'] ?? 0) >= 1 && count($pl['items'] ?? []) === 1
        && ($pl['centre'] ?? '') === 'Make Centre' && ($pl['date'] ?? '') === $yday && ($item['firstName'] ?? '') === 'Kemi'
        && ($item['guardianPhone'] ?? '') === '+2348031234567' && strpos((string)$ev['payload'], 'Kemi Adeyemi') === false
        && ($pl['reasons'] ?? []) === MAKE_ABSENCE_REASONS);
    chk('make: no number is recorded as no_contact, so it is not reconsidered every hour', ($r['noContact'] ?? 0) >= 1
        && db_row("SELECT status FROM absence_asks WHERE personId = 'NGG-MK-2'")['status'] === 'no_contact');
    chk('make: an old absence is not dragged up', !db_row("SELECT id FROM absence_asks WHERE date = '2020-01-06'"));
    chk('make: asked once — a second run asks nobody', (make_absences_run()['asked'] ?? -1) === 0);
    chk('make: the private list reaches the destination that names it, never the "*" room',
        (int)db_row("SELECT COUNT(*) c FROM deliveries WHERE eventId = ? AND integrationId = 'INT-MAKE-1'", [$ev['eventId']])['c'] === 1
        && (int)db_row("SELECT COUNT(*) c FROM deliveries WHERE eventId = ? AND integrationId = 'INT-MAKE-ALL'", [$ev['eventId']])['c'] === 0);

    $ref = (string)$item['ref'];
    chk('make: an unknown answer is refused, and says what is accepted', (function () use ($ref) {
        $x = backend_dispatch('hooks.make', ['action' => 'absence.reason', 'ref' => $ref, 'reason' => 'bored']);
        return $x['error'] === 'bad_reason' && $x['reasons'] === MAKE_ABSENCE_REASONS;
    })());
    $a = backend_dispatch('hooks.make', ['action' => 'absence.reason', 'ref' => $ref, 'reason' => 'Sick', 'note' => 'Fever since Monday', 'channel' => 'whatsapp', 'messageId' => 'wamid.1']);
    $row = db_row("SELECT * FROM absence_asks WHERE ref = ?", [$ref]);
    chk('make: the guardian’s answer is stored beside the absence, with where it came from', !empty($a['ok']) && $a['replaced'] === false
        && $row['status'] === 'answered' && $row['reason'] === 'sick' && $row['channel'] === 'whatsapp' && $row['messageId'] === 'wamid.1');
    chk('make: …and it explains the absence without voiding it — that stays a person’s call',
        db_row("SELECT voidedAt FROM infractions WHERE personId = 'NGG-MK-1' AND date = ?", [$yday])['voidedAt'] === '');
    $pp = backend_dispatch('admin.policy.person', ['requesterId' => 'NGG-2025-0099', 'personId' => 'NGG-MK-1']);
