        && (bool)db_row("SELECT id FROM member_ledger WHERE memberId = 'NGG-TF9-SES' AND periodKey = 'TF9S-DOMI'"));
    db_exec("DELETE FROM sessions WHERE sessionId LIKE 'TF9S-%'");

    // 8. What the member is shown.
