    $r = admin_applications_message(['requesterId' => 'NGG-IBX-ADM', 'id' => $aid, 'message' => 'Please send a clear photo of Ada.']);
    $a = db_row('SELECT status, messages FROM applications WHERE id = ?', [$aid]);
