        && $GLOBALS['__mail_sink'][0]['to'] === 'apply.ibx@example.org' && str_contains($GLOBALS['__mail_sink'][0]['html'], 'clear photo of Ada')
        && (json_decode($a['messages'], true)[0]['what'] ?? '') === 'ask');
