        && db_row('SELECT status FROM applications WHERE id = ?', [$aid])['status'] === 'rejected');
    $r = admin_applications_set_status(['requesterId' => 'NGG-IBX-ADM', 'id' => $aid, 'status' => 'waitlist']);
