                if (!$it['steps'] || trim((string)$it['hint']) === '' || trim((string)$it['stem']) === '') $bad[] = "$c/$fi teaching";
                if ($it['kind'] === 'num' && !is_numeric((string)$it['key'])) $bad[] = "$c/$fi numeric";
